INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('28a63128-e653-569f-b8de-59601846db3d', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 22, '<p>සුවල්‍ය ක්‍රමය (agile method) සම්බන්ධයෙන් වැරදි වන්නේ පහත කුමක් ද?</p>', '<p>සුවල්‍ය ක්‍රමය (agile method) සම්බන්ධයෙන් වැරදි වන්නේ පහත කුමක් ද?</p>', NULL, 'ඇජයිල් (Agile) ක්‍රමවේදය වෙනස්වන අවශ්‍යතා ඇති ව්‍යාපෘති සඳහා වඩාත් සුදුසු වුවද, නිශ්චිත අවශ්‍යතා ඇති ව්‍යාපෘති සඳහාද එය භාවිත කළ හැකිය. එබැවින් ''යොදාගත නොහැකිය'' යන්න වැරදි ප්‍රකාශයකි.', 'ඇජයිල් (Agile) ක්‍රමවේදය වෙනස්වන අවශ්‍යතා ඇති ව්‍යාපෘති සඳහා වඩාත් සුදුසු වුවද, නිශ්චිත අවශ්‍යතා ඇති ව්‍යාපෘති සඳහාද එය භාවිත කළ හැකිය. එබැවින් ''යොදාගත නොහැකිය'' යන්න වැරදි ප්‍රකාශයකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c931810f-5ef7-412d-9d08-5a8427e972bd', '28a63128-e653-569f-b8de-59601846db3d', 'ව්‍යාපෘතියට නිශ්චිත අවශ්‍යතා කුලකයක් ඇති විට මෙය යොදාගත නොහැකිය.', 'ව්‍යාපෘතියට නිශ්චිත අවශ්‍යතා කුලකයක් ඇති විට මෙය යොදාගත නොහැකිය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b5fa5758-ae66-4f2a-b974-49305d703dac', '28a63128-e653-569f-b8de-59601846db3d', 'කාර්ය නිමකිරීම සඳහා කාණ්ඩ වලට බෙදූ කාලසටහනක් නිර්දේශ කරයි.', 'කාර්ය නිමකිරීම සඳහා කාණ්ඩ වලට බෙදූ කාලසටහනක් නිර්දේශ කරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e575c2c2-a885-49ba-99bd-342c3a6bf431', '28a63128-e653-569f-b8de-59601846db3d', 'ක්‍රමිකව, ක්‍රියාත්මක මට්ටමේ නිමැවුම පුනර්කරණ ආකාරයෙන් ලබා දේ.', 'ක්‍රමිකව, ක්‍රියාත්මක මට්ටමේ නිමැවුම පුනර්කරණ ආකාරයෙන් ලබා දේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('27a6b77c-3e12-4ddd-8498-1862cea81059', '28a63128-e653-569f-b8de-59601846db3d', 'සෑම අදියරකදීම අදාළ පුද්ගලයින්ට (උදා: ගැනුම්කරුට, පරිශීලකයාට) ප්‍රගතිය සමාලෝචනය කර ප්‍රතිපෝෂණ ලබාදීමට පහසුකම් ලබා දේ.', 'සෑම අදියරකදීම අදාළ පුද්ගලයින්ට (උදා: ගැනුම්කරුට, පරිශීලකයාට) ප්‍රගතිය සමාලෝචනය කර ප්‍රතිපෝෂණ ලබාදීමට පහසුකම් ලබා දේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9ce26d74-9d99-44b2-8fcb-698d47987125', '28a63128-e653-569f-b8de-59601846db3d', 'සෑම අදියරේදීම නිමැවුම ස්වාධීනව පරීක්ෂා (test) කෙරේ.', 'සෑම අදියරේදීම නිමැවුම ස්වාධීනව පරීක්ෂා (test) කෙරේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0ccae4cb-66f3-51e5-973d-b9c039932e0c', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 23, '<p>වස්තු නැඹුරු ක්‍රමලේඛනය (Object Oriented Programming) සම්බන්ධයෙන් පහත කවරක් නිවැරදි ද?<br><br>A - වස්තු හැසිරීම හා ඒවායේ අන්තර්ක්‍රියා මගින් පද්ධති ප්‍රතිදානය තීරණය වේ.<br>B - පද්ධතිය වස්තූන්ගේ එකතුවක් ලෙස ආකෘතිගත කෙරෙයි.<br>C - මෙලෙස ක්‍රමලේඛයක් ලිවීම, ව්‍යුහගත (structured) ක්‍රමයට ක්‍රමලේඛයක් ලිවීමට වඩා වෙනස් වේ.</p>', '<p>වස්තු නැඹුරු ක්‍රමලේඛනය (Object Oriented Programming) සම්බන්ධයෙන් පහත කවරක් නිවැරදි ද?<br><br>A - වස්තු හැසිරීම හා ඒවායේ අන්තර්ක්‍රියා මගින් පද්ධති ප්‍රතිදානය තීරණය වේ.<br>B - පද්ධතිය වස්තූන්ගේ එකතුවක් ලෙස ආකෘතිගත කෙරෙයි.<br>C - මෙලෙස ක්‍රමලේඛයක් ලිවීම, ව්‍යුහගත (structured) ක්‍රමයට ක්‍රමලේඛයක් ලිවීමට වඩා වෙනස් වේ.</p>', NULL, 'OOP ක්‍රමවේදයේදී පද්ධතිය වස්තූන්ගේ එකතුවක් ලෙස සලකන අතර ඒවා අතර පණිවිඩ හුවමාරුවෙන් පද්ධතිය ක්‍රියා කරයි. මෙය පැරණි ව්‍යුහගත (structured) ක්‍රමයට වඩා වෙනස් සංකල්පයකි. එබැවින් ප්‍රකාශ තුනම සත්‍ය වේ.', 'OOP ක්‍රමවේදයේදී පද්ධතිය වස්තූන්ගේ එකතුවක් ලෙස සලකන අතර ඒවා අතර පණිවිඩ හුවමාරුවෙන් පද්ධතිය ක්‍රියා කරයි. මෙය පැරණි ව්‍යුහගත (structured) ක්‍රමයට වඩා වෙනස් සංකල්පයකි. එබැවින් ප්‍රකාශ තුනම සත්‍ය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
