INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d8a42962-6013-58ed-8107-fd4a588b050d', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 25, '<p>පහතින් දක්වා ඇත්තේ පද්ධතියට අදාළ පළමු මට්ටමේ DFD රූ සටහන යැයි සලකන්න.<br>ඉහත රූපයේ P, Q, R සහ S සඳහා නිවැරදි ආදේශ කිරීම් දක්වන්නේ පහත කවරක් ද?</p>
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b8ece689-1c8a-43d2-8d8e-c1d0ea0f5980', 'd8a42962-6013-58ed-8107-fd4a588b050d', 'P - ස්ථානය, Q - රියැදුරු කේතය, R - මගියාගේ සහ රියැදුරන්ගේ ස්ථානයන් ලබාගන්න, S - මගියාගේ සහ රියැදුරන්ගේ ස්ථානයන්', 'P - ස්ථානය, Q - රියැදුරු කේතය, R - මගියාගේ සහ රියැදුරන්ගේ ස්ථානයන් ලබාගන්න, S - මගියාගේ සහ රියැදුරන්ගේ ස්ථානයන්', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('acc86ead-28fc-4eb3-a37d-006e36861f2d', 'd8a42962-6013-58ed-8107-fd4a588b050d', 'P - ස්ථානය, Q - රියැදුරු කේතය සහ ස්ථානය, R - මගියාගේ සහ රියැදුරන්ගේ විස්තර ලබාගන්න, S - මගියාගේ සහ රියැදුරන්ගේ විස්තර', 'P - ස්ථානය, Q - රියැදුරු කේතය සහ ස්ථානය, R - මගියාගේ සහ රියැදුරන්ගේ විස්තර ලබාගන්න, S - මගියාගේ සහ රියැදුරන්ගේ විස්තර', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3211fa34-41ad-4378-a35c-d95694df4d3d', 'd8a42962-6013-58ed-8107-fd4a588b050d', 'P - NIC අංකය, Q - NIC අංකය, R - මගියාගේ සහ රියැදුරන්ගේ NIC අංක ලබාගන්න, S - මගියාගේ සහ රියැදුරන්ගේ NIC අංක', 'P - NIC අංකය, Q - NIC අංකය, R - මගියාගේ සහ රියැදුරන්ගේ NIC අංක ලබාගන්න, S - මගියාගේ සහ රියැදුරන්ගේ NIC අංක', NULL, 'sanitized', 'v1', 2, 0);
