INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2c897a5b-15d6-4f37-99e1-21c6ba7af156', 'd8a42962-6013-58ed-8107-fd4a588b050d', 'P - මගියාගේ කේතය, Q - ස්ථානය, R - මගියාගේ සහ රියැදුරන්ගේ ස්ථානයන් ලබාගන්න, S - මගියාගේ සහ රියැදුරන්ගේ ස්ථානයන්', 'P - මගියාගේ කේතය, Q - ස්ථානය, R - මගියාගේ සහ රියැදුරන්ගේ ස්ථානයන් ලබාගන්න, S - මගියාගේ සහ රියැදුරන්ගේ ස්ථානයන්', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4973bd4b-c571-589a-9945-5928f4d68221', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 26, '<p>ඉහත පළමු මට්ටමේ DFD රූ සටහන පසුව දියුණු කරනු ලදුව, දත්ත ගබඩාවක් (D1), R ක්‍රියාවලියට සම්බන්ධ කරන ලදි. එම දත්ත ගබඩාව කුමක් විය හැකි ද?</p>', '<p>ඉහත පළමු මට්ටමේ DFD රූ සටහන පසුව දියුණු කරනු ලදුව, දත්ත ගබඩාවක් (D1), R ක්‍රියාවලියට සම්බන්ධ කරන ලදි. එම දත්ත ගබඩාව කුමක් විය හැකි ද?</p>', NULL, 'ආසන්නම ටැක්සි රියදුරන් සොයාගැනීමේ ක්‍රියාවලිය සඳහා (R), පද්ධතියට ලියාපදිංචි ටැක්සි රියදුරන්ගේ විස්තර ඇතුළත් දත්ත ගබඩාවකට (Data Store) ප්‍රවේශ වීමට සිදුවේ.', 'ආසන්නම ටැක්සි රියදුරන් සොයාගැනීමේ ක්‍රියාවලිය සඳහා (R), පද්ධතියට ලියාපදිංචි ටැක්සි රියදුරන්ගේ විස්තර ඇතුළත් දත්ත ගබඩාවකට (Data Store) ප්‍රවේශ වීමට සිදුවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
