INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e71f24fd-f3ea-5838-bcd5-29bac0f0e823', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 33, '<p>StudentNo, SubjectName සහ Grade යන උපලැකිවල අගයයන් ලබා ගැනීමට අදාළ SQL වගන්තිය පහත කවරක් ද?</p>', '<p>StudentNo, SubjectName සහ Grade යන උපලැකිවල අගයයන් ලබා ගැනීමට අදාළ SQL වගන්තිය පහත කවරක් ද?</p>', NULL, 'INNER JOIN භාවිතයේදී සම්බන්ධ කළ යුතු වගුව ''INNER JOIN Subjects'' ලෙසද, සම්බන්ධතාවයේ කොන්දේසිය ''ON Results.SubjectID = Subjects.SubjectID'' ලෙසද දැක්වීම නිවැරදි SQL කාරක රීතියයි (Syntax).', 'INNER JOIN භාවිතයේදී සම්බන්ධ කළ යුතු වගුව ''INNER JOIN Subjects'' ලෙසද, සම්බන්ධතාවයේ කොන්දේසිය ''ON Results.SubjectID = Subjects.SubjectID'' ලෙසද දැක්වීම නිවැරදි SQL කාරක රීතියයි (Syntax).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('30d7a133-5620-4a8a-881b-3678d74f2f22', 'e71f24fd-f3ea-5838-bcd5-29bac0f0e823', 'SELECT Results. StudentNo, Subjects. SubjectName, Results. Grade FROM Results INNER JOIN ON Results. SubjectID = Subjects.SubjectID;', 'SELECT Results. StudentNo, Subjects. SubjectName, Results. Grade FROM Results INNER JOIN ON Results. SubjectID = Subjects.SubjectID;', NULL, 'sanitized', 'v1', 0, 1);
