INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e52a75b5-6aec-517d-9788-70f7c8b9b06c', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 34, '<p>Results වගුව සම්බන්ධයෙන් පහත කවර වගන්තියක් නිවැරදි වේද?</p>', '<p>Results වගුව සම්බන්ධයෙන් පහත කවර වගන්තියක් නිවැරදි වේද?</p>', NULL, 'වගුවේ FirstName සහ NIC යන දත්ත රඳා පවතින්නේ StudentNo මත පමණි (SubjectID මත නොවේ). එනම් ප්‍රාථමික යතුරේ කොටසක් මත අර්ධ පරායත්තතාවයක් (Partial Dependency) පවතී. එබැවින් එය 2NF හි නොමැති අතර, 1NF හි පවතී.', 'වගුවේ FirstName සහ NIC යන දත්ත රඳා පවතින්නේ StudentNo මත පමණි (SubjectID මත නොවේ). එනම් ප්‍රාථමික යතුරේ කොටසක් මත අර්ධ පරායත්තතාවයක් (Partial Dependency) පවතී. එබැවින් එය 2NF හි නොමැති අතර, 1NF හි පවතී.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bb4f9579-381f-4e98-959c-7564356dc6ea', 'e52a75b5-6aec-517d-9788-70f7c8b9b06c', 'යතුරු නොවන (non-key) සියලු උපලැකි (attributes) ප්‍රාථමික යතුර මත මුළුමනින්ම කාර්ය බද්ධව පරායත්ත වේ.', 'යතුරු නොවන (non-key) සියලු උපලැකි (attributes) ප්‍රාථමික යතුර මත මුළුමනින්ම කාර්ය බද්ධව පරායත්ත වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('28df0744-e15d-4e25-9568-c7be11119647', 'e52a75b5-6aec-517d-9788-70f7c8b9b06c', 'එයට එක් නිරූප්‍ය (candidate key) යතුරක් ඇත.', 'එයට එක් නිරූප්‍ය (candidate key) යතුරක් ඇත.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4db4317a-119a-4b5d-8f58-9e302a0c4da4', 'e52a75b5-6aec-517d-9788-70f7c8b9b06c', 'එය පළමු ප්‍රමත කරණයෙහි (1NF) පවතී.', 'එය පළමු ප්‍රමත කරණයෙහි (1NF) පවතී.', NULL, 'sanitized', 'v1', 2, 0);
