INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ce1ba86f-73c4-4e5a-a7c4-c2405c30f991', 'e52a75b5-6aec-517d-9788-70f7c8b9b06c', 'වගුවේ ගණනීයතාව (cardinality) 4 වේ.', 'වගුවේ ගණනීයතාව (cardinality) 4 වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ffe63961-720c-58b8-82a8-3ce22e8e04c9', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 35, '<p>Results වගුව ඊලඟ ප්‍රමත කරණයට (2NF) පත්කරන විට පහත කුමන පරායත්තතාව (dependency) ඉවත් වේ ද?</p>', '<p>Results වගුව ඊලඟ ප්‍රමත කරණයට (2NF) පත්කරන විට පහත කුමන පරායත්තතාව (dependency) ඉවත් වේ ද?</p>', NULL, 'පළමු ප්‍රමතකරණයේ (1NF) සිට දෙවන ප්‍රමතකරණයට (2NF) පත් කිරීමේදී, ප්‍රාථමික යතුරේ කොටසක් මත පමණක් යැපෙන යතුරු නොවන උපලැකි ඉවත් කිරීම සිදු කෙරේ. මෙය අර්ධ පරායත්තතාව (Partial Dependency) ඉවත් කිරීම ලෙස හැඳින්වේ.', 'පළමු ප්‍රමතකරණයේ (1NF) සිට දෙවන ප්‍රමතකරණයට (2NF) පත් කිරීමේදී, ප්‍රාථමික යතුරේ කොටසක් මත පමණක් යැපෙන යතුරු නොවන උපලැකි ඉවත් කිරීම සිදු කෙරේ. මෙය අර්ධ පරායත්තතාව (Partial Dependency) ඉවත් කිරීම ලෙස හැඳින්වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3ddc8f90-67a2-46b7-ba7f-efcb0843862c', 'ffe63961-720c-58b8-82a8-3ce22e8e04c9', 'ආගන්තුක යතුරු (foreign key) පරායත්තතාව', 'ආගන්තුක යතුරු (foreign key) පරායත්තතාව', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('03d50ba1-0b35-4f36-bf95-2627835e4d2f', 'ffe63961-720c-58b8-82a8-3ce22e8e04c9', 'යතුරු නොවන (non-key) උපලැකි, ප්‍රාථමික යතුර (primary key) මත පුර්ණ කාර්ය බද්ධ (full functional) පරායත්තතාව', 'යතුරු නොවන (non-key) උපලැකි, ප්‍රාථමික යතුර (primary key) මත පුර්ණ කාර්ය බද්ධ (full functional) පරායත්තතාව', NULL, 'sanitized', 'v1', 1, 0);
