INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f2554207-f4be-5efc-ae28-1647561603eb', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 43, '<p>පහත දැක්වෙන පයිතන් කේත කොටසේ ප්‍රතිදානය කුමක් වේද?<br>S = ["covid", "pandemic", "vaccine", "booster", "virus"]<br>V = "aeiou"<br>count = 0<br>for i in range(len(S)):<br>    for j in range(len(S[i])):<br>        if (S[i][j] in V):<br>            count = count + 1<br>print(count)</p>', '<p>පහත දැක්වෙන පයිතන් කේත කොටසේ ප්‍රතිදානය කුමක් වේද?<br>S = ["covid", "pandemic", "vaccine", "booster", "virus"]<br>V = "aeiou"<br>count = 0<br>for i in range(len(S)):<br>    for j in range(len(S[i])):<br>        if (S[i][j] in V):<br>            count = count + 1<br>print(count)</p>', NULL, 'මෙම කේතය මගින් S ලැයිස්තුවේ ඇති සියලුම වචනවල ඇති ස්වර (vowels - a, e, i, o, u) ගණන ගණනය කරයි. "covid"(2) + "pandemic"(3) + "vaccine"(3) + "booster"(3) + "virus"(2) = 13.', 'මෙම කේතය මගින් S ලැයිස්තුවේ ඇති සියලුම වචනවල ඇති ස්වර (vowels - a, e, i, o, u) ගණන ගණනය කරයි. "covid"(2) + "pandemic"(3) + "vaccine"(3) + "booster"(3) + "virus"(2) = 13.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
