INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ba16920c-a317-5a6b-940a-ee61395fd9aa', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 44, '<p>පහත දැක්වෙන පයිතන් කේතය ක්‍රියාත්මක කළ විට ප්‍රතිදානය කුමක් වේ ද?<br>s=1<br>for i in range(1,10):<br>    if (i<5):<br>        s=s*i<br>    elif (i<8):<br>        s=s-i<br>    else:<br>        s=s+i<br>        break<br>print(s)</p>', '<p>පහත දැක්වෙන පයිතන් කේතය ක්‍රියාත්මක කළ විට ප්‍රතිදානය කුමක් වේ ද?<br>s=1<br>for i in range(1,10):<br>    if (i<5):<br>        s=s*i<br>    elif (i<8):<br>        s=s-i<br>    else:<br>        s=s+i<br>        break<br>print(s)</p>', NULL, 'ලූපය $i=1$ සිට 4 දක්වා $s=s*i$ ($s=24$) ලෙස ගමන් කරයි. ඉන්පසු $i=5$ සිට 7 දක්වා $s=s-i$ ($24-5-6-7 = 6$) ලෙස ගමන් කරයි. $i=8$ වන විට else කොටසට ගොස් $s=s+8$ ($6+8=14$) වී break වේ. ප්‍රතිදානය 14 වේ.', 'ලූපය $i=1$ සිට 4 දක්වා $s=s*i$ ($s=24$) ලෙස ගමන් කරයි. ඉන්පසු $i=5$ සිට 7 දක්වා $s=s-i$ ($24-5-6-7 = 6$) ලෙස ගමන් කරයි. $i=8$ වන විට else කොටසට ගොස් $s=s+8$ ($6+8=14$) වී break වේ. ප්‍රතිදානය 14 වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
