INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('be5332dd-c7a1-5af7-9981-17c106fe3d3a', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 50, '<p>පහත දැක්වෙන PHP කේතය ක්‍රියාත්මක කළ විට ප්‍රතිදානය කුමක් වේ ද?<br><br>$$class = array ("12-A", "12-B", "13-A");$$<br>$$echo "IT classes are " . $class [1] . " and " . $class [2];$$</p>', '<p>පහත දැක්වෙන PHP කේතය ක්‍රියාත්මක කළ විට ප්‍රතිදානය කුමක් වේ ද?<br><br>$$class = array ("12-A", "12-B", "13-A");$$<br>$$echo "IT classes are " . $class [1] . " and " . $class [2];$$</p>', NULL, 'PHP අරාවන්හි (Arrays) දර්ශක අගය (index) ආරම්භ වන්නේ 0 මගිනි. ඒ අනුව $class[0] = "12-A", class[1] = "12-B", class[2] = "13-A"$ වේ. එබැවින් echo ප්‍රකාශය මගින් "IT classes are 12-B and 13-A" ලෙස ප්‍රතිදානය වේ.', 'PHP අරාවන්හි (Arrays) දර්ශක අගය (index) ආරම්භ වන්නේ 0 මගිනි. ඒ අනුව $class[0] = "12-A", class[1] = "12-B", class[2] = "13-A"$ වේ. එබැවින් echo ප්‍රකාශය මගින් "IT classes are 12-B and 13-A" ලෙස ප්‍රතිදානය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
