INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6fb0d9fc-b1e7-4bf1-a466-8b7db21ff065', 'fca46646-ff0b-5a29-a6b7-f11025620972', 'වාරි කර්මාන්තයේ දියුණුවට කටයුතු කිරීම', 'වාරි කර්මාන්තයේ දියුණුවට කටයුතු කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3335674b-998f-5bd0-b486-d4f28533e403', '4f0ef551-c2fe-5cd0-880d-dc3d0a98267d', 10, '<p>රටක දේශපාලන බලය මධ්‍යගත වූ විට,</p>', '<p>රටක දේශපාලන බලය මධ්‍යගත වූ විට,</p>', NULL, 'දේශපාලන බලය එක් මධ්‍යස්ථානයකට හෝ එක් පාලකයෙකු යටතට කේන්ද්‍රගත වීම මධ්‍යගත පාලනයයි. මෙහි ප්‍රතිඵලය වන්නේ රටේ ප්‍රාදේශීය බෙදීම් නැවතී ශක්තිමත්, එක්සත් රාජ්‍යයක් බිහි වීමයි.', 'දේශපාලන බලය එක් මධ්‍යස්ථානයකට හෝ එක් පාලකයෙකු යටතට කේන්ද්‍රගත වීම මධ්‍යගත පාලනයයි. මෙහි ප්‍රතිඵලය වන්නේ රටේ ප්‍රාදේශීය බෙදීම් නැවතී ශක්තිමත්, එක්සත් රාජ්‍යයක් බිහි වීමයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
