INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('bbe7018c-53da-5114-8d48-812b4248a2dd', '4f0ef551-c2fe-5cd0-880d-dc3d0a98267d', 17, '<p>සීගිරි ජල මල් වල ජල කඳේ උස වෙනස් කිරීමට අතීත නිර්මාණ ශිල්පීන් යොදාගත් උපක්‍රමය වූයේ,</p>', '<p>සීගිරි ජල මල් වල ජල කඳේ උස වෙනස් කිරීමට අතීත නිර්මාණ ශිල්පීන් යොදාගත් උපක්‍රමය වූයේ,</p>', NULL, 'ජලය විදින මල් වල (Fountains) ජල පීඩනය සහ ජල කඳේ උස පාලනය කිරීම සඳහා ජලය පිටවන සිදුරුවල විෂ්කම්භය (ප්‍රමාණය) වෙනස් කිරීමේ විද්‍යාත්මක මූලධර්මය ශ්‍රී ලාංකික ඉංජිනේරුවන් භාවිතා කර ඇත.', 'ජලය විදින මල් වල (Fountains) ජල පීඩනය සහ ජල කඳේ උස පාලනය කිරීම සඳහා ජලය පිටවන සිදුරුවල විෂ්කම්භය (ප්‍රමාණය) වෙනස් කිරීමේ විද්‍යාත්මක මූලධර්මය ශ්‍රී ලාංකික ඉංජිනේරුවන් භාවිතා කර ඇත.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c9223c14-07cc-40ba-a9f5-4de3aa39a46d', 'bbe7018c-53da-5114-8d48-812b4248a2dd', 'ගල් පතුරේ සිදුරු වල විෂ්කම්භය සමානව නිර්මාණය කිරීම ය.', 'ගල් පතුරේ සිදුරු වල විෂ්කම්භය සමානව නිර්මාණය කිරීම ය.', NULL, 'sanitized', 'v1', 0, 1);
