INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('263ae14c-7df4-4ff4-992c-80c5d4e4a48e', '57da5008-a7de-511c-becf-b33dd25eb543', 'ජාත්‍යන්තරව පිළිගත් පොදු කාසි වර්ගයක් ගනුදෙනු සඳහා භාවිත කිරීම', 'ජාත්‍යන්තරව පිළිගත් පොදු කාසි වර්ගයක් ගනුදෙනු සඳහා භාවිත කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ab3dd924-3500-5280-b661-05d0727c3c5a', '4f0ef551-c2fe-5cd0-880d-dc3d0a98267d', 19, '<p>හේන් වගා කිරීම වෙනුවෙන් රජයට අය කරගත් බද්ද හැඳින්වූයේ මින් කුමන නමකින්ද?</p>', '<p>හේන් වගා කිරීම වෙනුවෙන් රජයට අය කරගත් බද්ද හැඳින්වූයේ මින් කුමන නමකින්ද?</p>', NULL, 'හේන් වගාව සඳහා කැලෑ එළි කිරීමේදී ''කැත්ත'' භාවිතා කරන බැවින්, ඒ වෙනුවෙන් අය කළ බද්ද ''කැති අඩ'' (කැති කහවනු) ලෙස හැඳින්විය.', 'හේන් වගාව සඳහා කැලෑ එළි කිරීමේදී ''කැත්ත'' භාවිතා කරන බැවින්, ඒ වෙනුවෙන් අය කළ බද්ද ''කැති අඩ'' (කැති කහවනු) ලෙස හැඳින්විය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
