INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d8d08f70-d317-4506-a0dc-b8986693a586', 'f150454e-f965-550d-bcd5-2a0171b3eeb8', 'මන්නාරම් මුහුදේ මුතු කිමිදීමේ කටයුතු වල දී යාපනේ පාලකයන්ගෙන් පෘතුගීසීන්ට බාධා එල්ල වීමයි.', 'මන්නාරම් මුහුදේ මුතු කිමිදීමේ කටයුතු වල දී යාපනේ පාලකයන්ගෙන් පෘතුගීසීන්ට බාධා එල්ල වීමයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a713a968-8b2a-40e5-a621-d591201810d2', 'f150454e-f965-550d-bcd5-2a0171b3eeb8', 'යාපනේ සිංහාසනයට උරුමකම් කියූ ඇතැම් ද්‍රවිඩ කුමාරවරුන් පෘතුගීසීන්ට පක්ෂව කටයුතු කිරීමයි.', 'යාපනේ සිංහාසනයට උරුමකම් කියූ ඇතැම් ද්‍රවිඩ කුමාරවරුන් පෘතුගීසීන්ට පක්ෂව කටයුතු කිරීමයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1c419015-a919-450c-bbbf-3d894441e331', 'f150454e-f965-550d-bcd5-2a0171b3eeb8', 'යාපනය රාජධානියේ කතෝලික ආගම ප්‍රචාරය කිරීමට එරෙහිව එහි පාලකයන්ගෙන් දැඩි විරෝධතා එල්ල වීමයි.', 'යාපනය රාජධානියේ කතෝලික ආගම ප්‍රචාරය කිරීමට එරෙහිව එහි පාලකයන්ගෙන් දැඩි විරෝධතා එල්ල වීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9b9ed31e-e104-55e1-b86e-d4e735a326e7', '4f0ef551-c2fe-5cd0-880d-dc3d0a98267d', 24, '<p>මධ්‍යතන යුගයේ දී ආසියානු වෙළෙඳ ඒකාධිකාරය හිමි වූයේ,</p>', '<p>මධ්‍යතන යුගයේ දී ආසියානු වෙළෙඳ ඒකාධිකාරය හිමි වූයේ,</p>', NULL, 'මධ්‍යතන යුගයේ (Middle Ages) ඉන්දියන් සාගරයේ සහ ආසියානු වෙළෙඳාමේ ඒකාධිකාරය මුස්ලිම් හෙවත් අරාබි වෙළෙඳුන් සතුව පැවතිණි. පෘතුගීසීන් පෙරදිගට පැමිණියේ මෙම ඒකාධිකාරය බිඳ දැමීම සඳහාය.', 'මධ්‍යතන යුගයේ (Middle Ages) ඉන්දියන් සාගරයේ සහ ආසියානු වෙළෙඳාමේ ඒකාධිකාරය මුස්ලිම් හෙවත් අරාබි වෙළෙඳුන් සතුව පැවතිණි. පෘතුගීසීන් පෙරදිගට පැමිණියේ මෙම ඒකාධිකාරය බිඳ දැමීම සඳහාය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
