INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b7c55e9a-31fa-46f1-9dbe-228a6c1d71aa', 'dc43dcb9-e397-5d23-a59e-cb8fd1afd3a1', 'අස්වැන්නෙන් කොටසක් බදු වශයෙන් ගෙවීමට සිදු වූ නිසාය.', 'අස්වැන්නෙන් කොටසක් බදු වශයෙන් ගෙවීමට සිදු වූ නිසාය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d8b982c3-489c-52e3-8553-53b48c3ab9d6', '4f0ef551-c2fe-5cd0-880d-dc3d0a98267d', 39, '<p>"මේ අවස්ථාවේ අප බලය අල්ලා නොගතහොත් ඉතිහාසය අපට සමාව නොදෙනු ඇත." මෙම ප්‍රකාශය කිනම් විප්ලවයක් හා සම්බන්ධ වේ ද?</p>', '<p>"මේ අවස්ථාවේ අප බලය අල්ලා නොගතහොත් ඉතිහාසය අපට සමාව නොදෙනු ඇත." මෙම ප්‍රකාශය කිනම් විප්ලවයක් හා සම්බන්ධ වේ ද?</p>', NULL, 'මෙම ප්‍රකාශය රුසියානු විප්ලවයේ නායක ව්ලැදිමීර් ලෙනින් විසින් 1917 ඔක්තෝබර් විප්ලවයට ආසන්න දිනවලදී සිය බොල්ෂෙවික් පාක්ෂිකයින් දිරිමත් කිරීම සඳහා කරන ලද්දකි.', 'මෙම ප්‍රකාශය රුසියානු විප්ලවයේ නායක ව්ලැදිමීර් ලෙනින් විසින් 1917 ඔක්තෝබර් විප්ලවයට ආසන්න දිනවලදී සිය බොල්ෂෙවික් පාක්ෂිකයින් දිරිමත් කිරීම සඳහා කරන ලද්දකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
