INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1ad131ea-0ec0-5913-8793-2d7d7b45e989', '5635da63-e255-520e-927d-0e7025bbba96', 8, '<p>"තිඹිරිගෙය" යනුවෙන් හඳුන්වන්නේ මින් කුමක්ද?</p>', '<p>"තිඹිරිගෙය" යනුවෙන් හඳුන්වන්නේ මින් කුමක්ද?</p>', NULL, 'පැරණි සමාජයේ දරුවන් ප්‍රසූත කිරීම සඳහා වෙන් කරන ලද විශේෂිත කුටිය හෝ නිවස ''තිඹිරිගෙය'' ලෙස හැඳින්විය.', 'පැරණි සමාජයේ දරුවන් ප්‍රසූත කිරීම සඳහා වෙන් කරන ලද විශේෂිත කුටිය හෝ නිවස ''තිඹිරිගෙය'' ලෙස හැඳින්විය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f25f7122-e3d1-49f5-8173-3826619a9fbb', '1ad131ea-0ec0-5913-8793-2d7d7b45e989', 'ප්‍රසූතිය සඳහා ඉදි කළ ස්ථානය', 'ප්‍රසූතිය සඳහා ඉදි කළ ස්ථානය', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a8f07dee-be05-4445-99bf-23ebbfdb9402', '1ad131ea-0ec0-5913-8793-2d7d7b45e989', 'ගමේ ආරවුල් විසඳන ලද ස්ථානය', 'ගමේ ආරවුල් විසඳන ලද ස්ථානය', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('aff37ade-4933-47b8-a3a3-cb6982a84d6d', '1ad131ea-0ec0-5913-8793-2d7d7b45e989', 'ආගමික කටයුතු සඳහා භාවිත කළ ස්ථානය', 'ආගමික කටයුතු සඳහා භාවිත කළ ස්ථානය', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ca8a5f87-d00d-4e3f-8eb2-8bba9fc37d3d', '1ad131ea-0ec0-5913-8793-2d7d7b45e989', 'අධ්‍යාපන කටයුතු සිදු කළ ස්ථානය', 'අධ්‍යාපන කටයුතු සිදු කළ ස්ථානය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('920fde8f-f903-5ea4-b7f2-67b6bcd4ad91', '5635da63-e255-520e-927d-0e7025bbba96', 9, '<p>පහත දැක්වෙන මිනුම් ඒකක සලකන්න.<br>A - ගව්ව<br>B - වියත<br>C - යොදුන<br>D - අමුණ<br><br>ඒවා අතුරෙන් දුර මැනීම සඳහා යොදාගත් මිනුම් ඒකක පමණක් දැක්වෙන පිළිතුර කුමක්ද?</p>', '<p>පහත දැක්වෙන මිනුම් ඒකක සලකන්න.<br>A - ගව්ව<br>B - වියත<br>C - යොදුන<br>D - අමුණ<br><br>ඒවා අතුරෙන් දුර මැනීම සඳහා යොදාගත් මිනුම් ඒකක පමණක් දැක්වෙන පිළිතුර කුමක්ද?</p>', NULL, 'අතීතයේදී ගමනාගමන දුර මැනීම සඳහා ''ගව්ව'' සහ ''යොදුන'' යන ඒකක භාවිත කළ අතර, ''අමුණ'' යනු ධාන්‍ය මැනීම සඳහා යොදාගත් ඒකකයකි.', 'අතීතයේදී ගමනාගමන දුර මැනීම සඳහා ''ගව්ව'' සහ ''යොදුන'' යන ඒකක භාවිත කළ අතර, ''අමුණ'' යනු ධාන්‍ය මැනීම සඳහා යොදාගත් ඒකකයකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
