INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c6a5226a-7827-5204-88d4-34beac2a33d8', '5635da63-e255-520e-927d-0e7025bbba96', 18, '<p>පහත ප්‍රකාශ අතුරෙන් පුනරුද සමයේ කලා ශිල්පවල ලක්ෂණයක් දැක්වෙන්නේ කුමකින්ද?</p>', '<p>පහත ප්‍රකාශ අතුරෙන් පුනරුද සමයේ කලා ශිල්පවල ලක්ෂණයක් දැක්වෙන්නේ කුමකින්ද?</p>', NULL, 'මධ්‍යතන යුගයේදී නිර්මාණකරුවා අදෘශ්‍යමානව සිටි නමුත් යුරෝපීය පුනරුදයත් සමග කලාකරුවන්ට සමාජ පිළිගැනීමක් ලැබුණු අතර තමන්ගේ කලා කෘතිවල තමන්ගේ නම (අත්සන) සටහන් කිරීම ආරම්භ විය.', 'මධ්‍යතන යුගයේදී නිර්මාණකරුවා අදෘශ්‍යමානව සිටි නමුත් යුරෝපීය පුනරුදයත් සමග කලාකරුවන්ට සමාජ පිළිගැනීමක් ලැබුණු අතර තමන්ගේ කලා කෘතිවල තමන්ගේ නම (අත්සන) සටහන් කිරීම ආරම්භ විය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('540f573d-9579-4d1f-800b-1fd266c889eb', 'c6a5226a-7827-5204-88d4-34beac2a33d8', 'කලා නිර්මාණ ආගමට නැඹුරු වීම', 'කලා නිර්මාණ ආගමට නැඹුරු වීම', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e9dda806-dd2c-416f-86ff-8126f290dcff', 'c6a5226a-7827-5204-88d4-34beac2a33d8', 'කලා කෘති ඒවා නිර්මාණය කළ කතුවරුන්ගේ නමින් එළිදැක්වීම', 'කලා කෘති ඒවා නිර්මාණය කළ කතුවරුන්ගේ නමින් එළිදැක්වීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('679b42fb-48c4-41e7-b432-d7074e615aef', 'c6a5226a-7827-5204-88d4-34beac2a33d8', 'පල්ලිය පමණක් කලා නිර්මාණ වලට අනුග්‍රහ දැක්වීම', 'පල්ලිය පමණක් කලා නිර්මාණ වලට අනුග්‍රහ දැක්වීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cd4a11fc-f618-457c-9389-3890082a1cfc', 'c6a5226a-7827-5204-88d4-34beac2a33d8', 'ආගමික වශයෙන් වැදගත් වූ පුද්ගලයන් පමණක් චිත්‍ර වලට වස්තු විෂය වීම', 'ආගමික වශයෙන් වැදගත් වූ පුද්ගලයන් පමණක් චිත්‍ර වලට වස්තු විෂය වීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('30501466-1c33-591f-b6b0-3af81d120cce', '5635da63-e255-520e-927d-0e7025bbba96', 19, '<p>පහත සඳහන් කරුණු අතුරෙන් යාපන රාජ්‍යය බිඳ වැටීමට හේතු වූ කරුණු දැක්වෙන පිළිතුර කුමක්ද?<br>A - යාපන රාජ්‍යයේ උරුමකරුවන් අතර ඇති වූ බල අරගල<br>B - යාපන ප්‍රදේශයේ කතෝලික ආගම ප්‍රචාරය කිරීම<br>C - යාපනයේ පාලකයන්ට ප්‍රමාණවත් නිත්‍ය හමුදාවක් නොසිටීම<br>D - යාපනයේ බහුතර ජනතාව පෘතුගීසින්ට පක්ෂපාතී වීම</p>', '<p>පහත සඳහන් කරුණු අතුරෙන් යාපන රාජ්‍යය බිඳ වැටීමට හේතු වූ කරුණු දැක්වෙන පිළිතුර කුමක්ද?<br>A - යාපන රාජ්‍යයේ උරුමකරුවන් අතර ඇති වූ බල අරගල<br>B - යාපන ප්‍රදේශයේ කතෝලික ආගම ප්‍රචාරය කිරීම<br>C - යාපනයේ පාලකයන්ට ප්‍රමාණවත් නිත්‍ය හමුදාවක් නොසිටීම<br>D - යාපනයේ බහුතර ජනතාව පෘතුගීසින්ට පක්ෂපාතී වීම</p>', NULL, 'යාපනය රාජ්‍යය පෘතුගීසීන්ට යටත් වීමට ප්‍රධාන වශයෙන්ම බලපෑවේ රාජ්‍ය උරුමය සඳහා ඇතිවූ අභ්‍යන්තර බල අරගල (A) සහ පෘතුගීසීන්ගේ ප්‍රබල යුද බලයට මුහුණදීමට තරම් ශක්තිමත් නිත්‍ය හමුදාවක් ඔවුන්ට නොමැති වීමයි (C).', 'යාපනය රාජ්‍යය පෘතුගීසීන්ට යටත් වීමට ප්‍රධාන වශයෙන්ම බලපෑවේ රාජ්‍ය උරුමය සඳහා ඇතිවූ අභ්‍යන්තර බල අරගල (A) සහ පෘතුගීසීන්ගේ ප්‍රබල යුද බලයට මුහුණදීමට තරම් ශක්තිමත් නිත්‍ය හමුදාවක් ඔවුන්ට නොමැති වීමයි (C).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
