INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7e032dfa-c521-5372-9009-a9af9fc21135', '5635da63-e255-520e-927d-0e7025bbba96', 21, '<p>කාර්මික විප්ලවය නිසා සමාජයේ ඇති වූ ප්‍රධාන වෙනසක් වුයේ,</p>', '<p>කාර්මික විප්ලවය නිසා සමාජයේ ඇති වූ ප්‍රධාන වෙනසක් වුයේ,</p>', NULL, 'කාර්මික විප්ලවයත් සමඟ සමාජය තුළ ප්‍රාග්ධනය හිමි ''ධනපති පන්තිය'' සහ කර්මාන්තශාලාවල ශ්‍රමය වගුරන ''කම්කරු හෙවත් නිර්ධන පන්තිය'' ලෙස පැහැදිලි පන්ති භේදයක් නිර්මාණය විය.', 'කාර්මික විප්ලවයත් සමඟ සමාජය තුළ ප්‍රාග්ධනය හිමි ''ධනපති පන්තිය'' සහ කර්මාන්තශාලාවල ශ්‍රමය වගුරන ''කම්කරු හෙවත් නිර්ධන පන්තිය'' ලෙස පැහැදිලි පන්ති භේදයක් නිර්මාණය විය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e7d127e2-3e34-4ed1-8dac-2f66ba8d5dc8', '7e032dfa-c521-5372-9009-a9af9fc21135', 'ලිබරල්වාදය, සමාජ වාදය වැනි දාර්ශනික මතවල ව්‍යාප්තියයි.', 'ලිබරල්වාදය, සමාජ වාදය වැනි දාර්ශනික මතවල ව්‍යාප්තියයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5c9b2380-7b63-434c-ae3b-0d124924bea8', '7e032dfa-c521-5372-9009-a9af9fc21135', 'සාම්ප්‍රදායික කෘෂි ආර්ථික රටාව වෙනුවට ආනයන - අපනයන ආර්ථික රටාවක් බිහිවීමයි.', 'සාම්ප්‍රදායික කෘෂි ආර්ථික රටාව වෙනුවට ආනයන - අපනයන ආර්ථික රටාවක් බිහිවීමයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('851c87ed-d01a-40df-bad1-9eb668e15f03', '7e032dfa-c521-5372-9009-a9af9fc21135', 'බහුජාතික සමාගම් වල බිහිවීමයි.', 'බහුජාතික සමාගම් වල බිහිවීමයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9906593b-15e4-4911-8beb-b7467d484399', '7e032dfa-c521-5372-9009-a9af9fc21135', 'ධනපති පන්තියක් හා නිර්ධන පන්තියක් බිහිවීමයි.', 'ධනපති පන්තියක් හා නිර්ධන පන්තියක් බිහිවීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('bd61fb88-1e78-577a-9205-0ae526e3a96b', '5635da63-e255-520e-927d-0e7025bbba96', 22, '<p>A සිට F තෙක් තොරතුරු ඇසුරෙන් පිළිතුරු සපයන්න.<br>නිපැයුම:<br>A - දුවන නඩාව<br>B - රෝලර් යන්ත්‍රය<br>C - ආරක්ෂක ලාම්පුව<br><br>කර්මාන්තය:<br>D - ගල් අඟුරු<br>E - (රෙදිපිළි)<br>F - යකඩ හා වානේ<br><br>ජෝන් කේ නමැත්තාගේ නිපැයුම හා එයට සම්බන්ධ කර්මාන්තය පිළිබඳ තොරතුරු දැක්වෙන පිළිතුර කුමක්ද?</p>', '<p>A සිට F තෙක් තොරතුරු ඇසුරෙන් පිළිතුරු සපයන්න.<br>නිපැයුම:<br>A - දුවන නඩාව<br>B - රෝලර් යන්ත්‍රය<br>C - ආරක්ෂක ලාම්පුව<br><br>කර්මාන්තය:<br>D - ගල් අඟුරු<br>E - (රෙදිපිළි)<br>F - යකඩ හා වානේ<br><br>ජෝන් කේ නමැත්තාගේ නිපැයුම හා එයට සම්බන්ධ කර්මාන්තය පිළිබඳ තොරතුරු දැක්වෙන පිළිතුර කුමක්ද?</p>', NULL, 'ජෝන් කේ (John Kay) විසින් රෙදිපිළි කර්මාන්තය (E) සඳහා ''දුවන නඩාව'' හෙවත් Flying Shuttle (A) නිපදවන ලදී.', 'ජෝන් කේ (John Kay) විසින් රෙදිපිළි කර්මාන්තය (E) සඳහා ''දුවන නඩාව'' හෙවත් Flying Shuttle (A) නිපදවන ලදී.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
