INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3ef6905a-33df-5d36-a8c3-afaa7d6c5475', '5635da63-e255-520e-927d-0e7025bbba96', 30, '<p>කෝල්බෲක ප්‍රතිසංස්කරණ මගින් හඳුන්වා දුන් ආර්ථික ප්‍රතිසංස්කරණ යෝජනාව වන්නේ මින් කුමක්ද?</p>', '<p>කෝල්බෲක ප්‍රතිසංස්කරණ මගින් හඳුන්වා දුන් ආර්ථික ප්‍රතිසංස්කරණ යෝජනාව වන්නේ මින් කුමක්ද?</p>', NULL, '1833 කෝල්බෲක් - කැමරන් ප්‍රතිසංස්කරණ මගින් රාජකාරි ක්‍රමය සහ රජය සතුව තිබූ වෙළඳ ඒකාධිකාරය අහෝසි කරමින් නිදහස් වෙළඳ ආර්ථිකයකට මඟපෑදීම ප්‍රධාන ආර්ථික යෝජනාව විය.', '1833 කෝල්බෲක් - කැමරන් ප්‍රතිසංස්කරණ මගින් රාජකාරි ක්‍රමය සහ රජය සතුව තිබූ වෙළඳ ඒකාධිකාරය අහෝසි කරමින් නිදහස් වෙළඳ ආර්ථිකයකට මඟපෑදීම ප්‍රධාන ආර්ථික යෝජනාව විය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c198fd30-38a3-464b-a6dc-3e3799fb86b2', '3ef6905a-33df-5d36-a8c3-afaa7d6c5475', 'උඩරට හා පහතරට ඒකාබද්ධ කිරීම', 'උඩරට හා පහතරට ඒකාබද්ධ කිරීම', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('07eaddac-9955-48ab-8ad6-eb35b29d0f32', '3ef6905a-33df-5d36-a8c3-afaa7d6c5475', 'රජයේ වෙළෙඳ ඒකාධිකාරය අහෝසි කිරීම', 'රජයේ වෙළෙඳ ඒකාධිකාරය අහෝසි කිරීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('813451fe-49aa-4d4a-90bb-56946e86af16', '3ef6905a-33df-5d36-a8c3-afaa7d6c5475', 'ව්‍යවස්ථාදායක හා විධායක සභා පිහිටුවීම', 'ව්‍යවස්ථාදායක හා විධායක සභා පිහිටුවීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9ab60b88-218d-4917-aa62-4244a6e710e6', '3ef6905a-33df-5d36-a8c3-afaa7d6c5475', 'ඉංග්‍රීසි භාෂා අධ්‍යාපනය ක්‍රියාත්මක කිරීම', 'ඉංග්‍රීසි භාෂා අධ්‍යාපනය ක්‍රියාත්මක කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d025ee77-b3fe-5ad5-995b-5c1240dfc0f9', '5635da63-e255-520e-927d-0e7025bbba96', 31, '<p>බ්‍රිතාන්‍ය පාලන සමයේ දී වතු වගාවේ ව්‍යාප්තිය හා දියුණුව නිසා හටගත් සමාජ ගැටලුවක් වූයේ,</p>', '<p>බ්‍රිතාන්‍ය පාලන සමයේ දී වතු වගාවේ ව්‍යාප්තිය හා දියුණුව නිසා හටගත් සමාජ ගැටලුවක් වූයේ,</p>', NULL, 'වතු ආර්ථිකයේ වර්ධනයත් සමඟ රේන්ද ක්‍රමය හරහා මද්‍යසාර (මත්පැන්) අලෙවිය විශාල වශයෙන් සමාජය තුළ ව්‍යාප්ත වූ අතර, එය බරපතළ ''සමාජ ගැටලුවක්'' බවට පත්වූ නිසා පසුව අමද්‍යප ව්‍යාපාරය බිහි විය.', 'වතු ආර්ථිකයේ වර්ධනයත් සමඟ රේන්ද ක්‍රමය හරහා මද්‍යසාර (මත්පැන්) අලෙවිය විශාල වශයෙන් සමාජය තුළ ව්‍යාප්ත වූ අතර, එය බරපතළ ''සමාජ ගැටලුවක්'' බවට පත්වූ නිසා පසුව අමද්‍යප ව්‍යාපාරය බිහි විය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('34ed00b6-ff2d-4e71-aa16-ca212598805b', 'd025ee77-b3fe-5ad5-995b-5c1240dfc0f9', 'මද්‍යසාර භාවිතය ව්‍යාප්ත වීම ය.', 'මද්‍යසාර භාවිතය ව්‍යාප්ත වීම ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('535d44ba-84ee-44cb-99d6-0e62249a2d6d', 'd025ee77-b3fe-5ad5-995b-5c1240dfc0f9', 'ආනයනික භාණ්ඩ භාවිතය ප්‍රචලිත වීම ය.', 'ආනයනික භාණ්ඩ භාවිතය ප්‍රචලිත වීම ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f0828be3-9654-4f77-8c20-52888ac6c563', 'd025ee77-b3fe-5ad5-995b-5c1240dfc0f9', 'දේශීය කෘෂිකර්මාන්තය අඩපණ වීම ය.', 'දේශීය කෘෂිකර්මාන්තය අඩපණ වීම ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('504000a9-2ae3-40b4-b7fe-1fc520e4ddbc', 'd025ee77-b3fe-5ad5-995b-5c1240dfc0f9', 'භාණ්ඩ හුවමාරුව වෙනුවට මුදල් භාවිතය ප්‍රචලිත වීම ය.', 'භාණ්ඩ හුවමාරුව වෙනුවට මුදල් භාවිතය ප්‍රචලිත වීම ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('af026c2b-a89a-5108-9ca3-710a90e91bb9', '5635da63-e255-520e-927d-0e7025bbba96', 32, '<p>ශ්‍රී ලංකාවට නිදහස ලැබීමෙන් පසු පිහිටුවන ලද දේශපාලන පක්ෂය මින් කුමක්ද?</p>', '<p>ශ්‍රී ලංකාවට නිදහස ලැබීමෙන් පසු පිහිටුවන ලද දේශපාලන පක්ෂය මින් කුමක්ද?</p>', NULL, 'ශ්‍රී ලංකාවට නිදහස ලැබුණේ 1948 දී ය. එක්සත් ජාතික පක්ෂය (1946) සහ වම්මුන්ගේ පක්ෂ නිදහසට පෙර බිහි වූ අතර, ශ්‍රී ලංකා නිදහස් පක්ෂය එස්. ඩබ්. ආර්. ඩී. බණ්ඩාරනායක මහතා විසින් පිහිටුවන ලද්දේ 1951 දී ය.', 'ශ්‍රී ලංකාවට නිදහස ලැබුණේ 1948 දී ය. එක්සත් ජාතික පක්ෂය (1946) සහ වම්මුන්ගේ පක්ෂ නිදහසට පෙර බිහි වූ අතර, ශ්‍රී ලංකා නිදහස් පක්ෂය එස්. ඩබ්. ආර්. ඩී. බණ්ඩාරනායක මහතා විසින් පිහිටුවන ලද්දේ 1951 දී ය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
