INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bae11b0d-7fd1-46ca-9a15-7f1c82674921', 'af026c2b-a89a-5108-9ca3-710a90e91bb9', 'ශ්‍රී ලංකා නිදහස් පක්ෂය', 'ශ්‍රී ලංකා නිදහස් පක්ෂය', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9bbdf9ae-f405-44e6-a319-77453c0c38ae', 'af026c2b-a89a-5108-9ca3-710a90e91bb9', 'ලංකා සම සමාජ පක්ෂය', 'ලංකා සම සමාජ පක්ෂය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('07b8c273-116c-5fe2-9dd2-8f9d86121526', '5635da63-e255-520e-927d-0e7025bbba96', 33, '<p>වියළි කලාපයේ ගොවි ජනපද ව්‍යාපාරය ආරම්භ කළ තැනැත්තා වන්නේ,</p>', '<p>වියළි කලාපයේ ගොවි ජනපද ව්‍යාපාරය ආරම්භ කළ තැනැත්තා වන්නේ,</p>', NULL, 'කෘෂිකර්ම ඇමතිවරයා ලෙසත් පසුව අගමැතිවරයා ලෙසත් ඩී. එස්. සේනානායක මහතා රජරට වියළි කලාපයේ ගොවි ජනපද (උදා: මින්නේරිය) පිහිටුවමින් කෘෂිකර්මය නගා සිටුවීය.', 'කෘෂිකර්ම ඇමතිවරයා ලෙසත් පසුව අගමැතිවරයා ලෙසත් ඩී. එස්. සේනානායක මහතා රජරට වියළි කලාපයේ ගොවි ජනපද (උදා: මින්නේරිය) පිහිටුවමින් කෘෂිකර්මය නගා සිටුවීය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
