INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e11ad983-9929-4ac6-a9ca-6cc0b6bcb9ba', '806c9e82-8adc-5c8f-9bda-b87b957b39b8', 'අපනයන ආශ්‍රිත කර්මාන්ත දියුණු කිරීමට විදේශීය ධන ආයෝජකයින් මෙරටට ගෙන්වා ගැනීම', 'අපනයන ආශ්‍රිත කර්මාන්ත දියුණු කිරීමට විදේශීය ධන ආයෝජකයින් මෙරටට ගෙන්වා ගැනීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6a182285-9780-4aa0-a117-b67f08e6648a', '806c9e82-8adc-5c8f-9bda-b87b957b39b8', 'රාජ්‍ය මැදිහත්වීමෙන් රට තුළ මහා පරිමාණ කර්මාන්තශාලා වර්ධනය කිරීම', 'රාජ්‍ය මැදිහත්වීමෙන් රට තුළ මහා පරිමාණ කර්මාන්තශාලා වර්ධනය කිරීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('50fdce03-496b-4637-8913-0601b472f579', '806c9e82-8adc-5c8f-9bda-b87b957b39b8', 'දේශීය ගෘහස්ථ කර්මාන්ත හා සුළු කර්මාන්ත දියුණු කිරීම', 'දේශීය ගෘහස්ථ කර්මාන්ත හා සුළු කර්මාන්ත දියුණු කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5bac8959-0500-500d-a327-4f04d16d8e41', '5635da63-e255-520e-927d-0e7025bbba96', 37, '<p>එක්සත් ජාතීන්ගේ සංවිධානයේ මහලේකම්වරයා පත් කරනු ලබන්නේ,</p>', '<p>එක්සත් ජාතීන්ගේ සංවිධානයේ මහලේකම්වරයා පත් කරනු ලබන්නේ,</p>', NULL, 'එක්සත් ජාතීන්ගේ සංවිධානයේ ප්‍රධාන පරිපාලන නිලධාරියා වන මහලේකම්වරයා, ආරක්ෂක මණ්ඩලයේ (Security Council) නිර්දේශයක් මත මහා මණ්ඩලය (General Assembly) විසින් පත් කරනු ලබයි.', 'එක්සත් ජාතීන්ගේ සංවිධානයේ ප්‍රධාන පරිපාලන නිලධාරියා වන මහලේකම්වරයා, ආරක්ෂක මණ්ඩලයේ (Security Council) නිර්දේශයක් මත මහා මණ්ඩලය (General Assembly) විසින් පත් කරනු ලබයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
