INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8f77f1df-ff97-43e0-a83c-0b3ab1af341a', '934eece0-48f3-587c-be6f-fcb1e66f630d', 'ආවර්තයක් හරහා වමේ සිට දකුණට කැටායනවල විශාලත්වය අඩු වේ.', 'ආවර්තයක් හරහා වමේ සිට දකුණට කැටායනවල විශාලත්වය අඩු වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('54b48b60-f3fc-437e-8f3f-0a6002b1bd60', '934eece0-48f3-587c-be6f-fcb1e66f630d', 'ආවර්තයක් හරහා වමේ සිට දකුණට ඇනා යන වල විශාලත්වය වැඩි වේ.', 'ආවර්තයක් හරහා වමේ සිට දකුණට ඇනා යන වල විශාලත්වය වැඩි වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('163c4d5d-2116-40cb-b706-32524cf8960f', '934eece0-48f3-587c-be6f-fcb1e66f630d', 'දෙවැනි ආවර්තයේ මූල ද්‍රව්‍ය සාදන ඇනායන, තුන්වැනි ආවර්තයේ මූලද්‍රව්‍ය සාදන කැටායන වලට වඩා විශාල වේ.', 'දෙවැනි ආවර්තයේ මූල ද්‍රව්‍ය සාදන ඇනායන, තුන්වැනි ආවර්තයේ මූලද්‍රව්‍ය සාදන කැටායන වලට වඩා විශාල වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('72a6f897-19a1-5265-af38-8d013c50934c', '63ada726-c109-5ebe-b233-668ff3edf116', 5, '<p>මූල ද්‍රව්‍යයක පරමාණුවක අවසාන ඉලෙක්ට්‍රෝන දෙක හා සම්බන්ධ ක්වොන්ටම් අංක කුලක $(3, 0, 0, +1/2)$ සහ $(3, 0, 0, -1/2)$ වේ. මූල ද්‍රව්‍යය වනුයේ,</p>', '<p>මූල ද්‍රව්‍යයක පරමාණුවක අවසාන ඉලෙක්ට්‍රෝන දෙක හා සම්බන්ධ ක්වොන්ටම් අංක කුලක $(3, 0, 0, +1/2)$ සහ $(3, 0, 0, -1/2)$ වේ. මූල ද්‍රව්‍යය වනුයේ,</p>', NULL, 'ක්වොන්ටම් අංක කුලකයෙන් දැක්වෙන්නේ ප්‍රධාන ශක්ති මට්ටම $n=3$ සහ උපකවචය $l=0$ (s උපකවචය) බවයි. අවසාන ඉලෙක්ට්‍රෝන දෙක $3s^2$ වන බැවින් එය මැග්නීසියම් (Mg) වේ.', 'ක්වොන්ටම් අංක කුලකයෙන් දැක්වෙන්නේ ප්‍රධාන ශක්ති මට්ටම $n=3$ සහ උපකවචය $l=0$ (s උපකවචය) බවයි. අවසාන ඉලෙක්ට්‍රෝන දෙක $3s^2$ වන බැවින් එය මැග්නීසියම් (Mg) වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
