INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cea74394-3e49-5811-9d25-1daf4ac84a56', '63ada726-c109-5ebe-b233-668ff3edf116', 6, '<p>$KIO_{3}$ $0.60~g$ ක නියැදියක් ජලයේ දියකර එයට වැඩිපුර $KI$ එකතු කරන ලදි. $KIO_{3}$ සම්පුර්ණයෙන්ම $I_{3}^{-}$ බවට පත් කිරීමට අවශ්‍ය වන අවම $3.0~mol~dm^{-3}$ $HCl$ ප්‍රමාණය වන්නේ, ($O=16$, $K=39$, $I=127$)</p>', '<p>$KIO_{3}$ $0.60~g$ ක නියැදියක් ජලයේ දියකර එයට වැඩිපුර $KI$ එකතු කරන ලදි. $KIO_{3}$ සම්පුර්ණයෙන්ම $I_{3}^{-}$ බවට පත් කිරීමට අවශ්‍ය වන අවම $3.0~mol~dm^{-3}$ $HCl$ ප්‍රමාණය වන්නේ, ($O=16$, $K=39$, $I=127$)</p>', NULL, 'අයනික සමීකරණය: $IO_3^- + 8I^- + 6H^+ \rightarrow 3I_3^- + 3H_2O$<br>$KIO_3$ මවුලික ස්කන්ධය = $214~g~mol^{-1}$<br>$KIO_3$ මවුල ගණන = \frac{0.60}{214} = 2.8 \times 10^{-3}~mol<br>අවශ්‍ය $H^+$ මවුල ගණන = $6 \times 2.8 \times 10^{-3} = 0.0168~mol$<br>අවශ්‍ය $HCl$ පරිමාව $V = \frac{n}{c} = \frac{0.0168}{3.0} = 0.0056~dm^3 = 5.6~cm^3$', 'අයනික සමීකරණය: $IO_3^- + 8I^- + 6H^+ \rightarrow 3I_3^- + 3H_2O$<br>$KIO_3$ මවුලික ස්කන්ධය = $214~g~mol^{-1}$<br>$KIO_3$ මවුල ගණන = \frac{0.60}{214} = 2.8 \times 10^{-3}~mol<br>අවශ්‍ය $H^+$ මවුල ගණන = $6 \times 2.8 \times 10^{-3} = 0.0168~mol$<br>අවශ්‍ය $HCl$ පරිමාව $V = \frac{n}{c} = \frac{0.0168}{3.0} = 0.0056~dm^3 = 5.6~cm^3$', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
