INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cf6c071d-8574-5ee1-8f84-07b53ec961cb', '63ada726-c109-5ebe-b233-668ff3edf116', 7, '<p>$25^{\circ}C$ දී $MnS(s)$ හි ද්‍රාව්‍යතා ගුණිතය, $K_{sp}$ $5.0\times10^{-15}~mol^{2}~dm^{-6}$ වේ.<br>$H_{2}S(aq)$ හි අම්ල විඝටන නියත $K_{1}$ හා $K_{2}$ පිළිවෙළින්, $1.0\times10^{-7}~mol~dm^{-3}$ සහ $1.0\times10^{-13}~mol~dm^{-3}$ වේ.<br>$MnS(s)+2H^{+}(aq)\rightleftharpoons Mn^{2+}(aq)+H_{2}S(aq)$ ප්‍රතික්‍රියාවේ $K_{c}$ අගය,</p>', '<p>$25^{\circ}C$ දී $MnS(s)$ හි ද්‍රාව්‍යතා ගුණිතය, $K_{sp}$ $5.0\times10^{-15}~mol^{2}~dm^{-6}$ වේ.<br>$H_{2}S(aq)$ හි අම්ල විඝටන නියත $K_{1}$ හා $K_{2}$ පිළිවෙළින්, $1.0\times10^{-7}~mol~dm^{-3}$ සහ $1.0\times10^{-13}~mol~dm^{-3}$ වේ.<br>$MnS(s)+2H^{+}(aq)\rightleftharpoons Mn^{2+}(aq)+H_{2}S(aq)$ ප්‍රතික්‍රියාවේ $K_{c}$ අගය,</p>', NULL, '$K_c = \frac{[Mn^{2+}][H_2S]}{[H^+]^2}$<br>ලවය හා හරය $[S^{2-}]$ මගින් ගුණ කළ විට:<br>$K_c = \frac{[Mn^{2+}][S^{2-}][H_2S]}{[H^+]^2[S^{2-}]} = \frac{K_{sp}}{K_1 \times K_2}$<br>$K_c = \frac{5.0 \times 10^{-15}}{1.0 \times 10^{-7} \times 1.0 \times 10^{-13}}$<br>$K_c = 5.0 \times 10^5$', '$K_c = \frac{[Mn^{2+}][H_2S]}{[H^+]^2}$<br>ලවය හා හරය $[S^{2-}]$ මගින් ගුණ කළ විට:<br>$K_c = \frac{[Mn^{2+}][S^{2-}][H_2S]}{[H^+]^2[S^{2-}]} = \frac{K_{sp}}{K_1 \times K_2}$<br>$K_c = \frac{5.0 \times 10^{-15}}{1.0 \times 10^{-7} \times 1.0 \times 10^{-13}}$<br>$K_c = 5.0 \times 10^5$', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
