INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6280fa84-0e6c-5601-8dfd-82fa11ca3f5e', '63ada726-c109-5ebe-b233-668ff3edf116', 8, '<p>A නමැති කාබනික සංයෝගයේ බර අනුව 39.97% ක් C, 6.73% ක් H හා 53.30% ක් O අඩංගු වේ. A හි ආනුභවික සූත්‍රය වනුයේ, ($H=1$, $C=12$, $O=16$)</p>', '<p>A නමැති කාබනික සංයෝගයේ බර අනුව 39.97% ක් C, 6.73% ක් H හා 53.30% ක් O අඩංගු වේ. A හි ආනුභවික සූත්‍රය වනුයේ, ($H=1$, $C=12$, $O=16$)</p>', NULL, 'මූලද්‍රව්‍යවල මවුල අනුපාතය සෙවීම:<br>$C = \frac{39.97}{12} = 3.33$<br>$H = \frac{6.73}{1} = 6.73$<br>$O = \frac{53.30}{16} = 3.33$<br>$C : H : O = 3.33 : 6.73 : 3.33 \approx 1 : 2 : 1$<br>එබැවින් ආනුභවික සූත්‍රය $CH_2O$ වේ.', 'මූලද්‍රව්‍යවල මවුල අනුපාතය සෙවීම:<br>$C = \frac{39.97}{12} = 3.33$<br>$H = \frac{6.73}{1} = 6.73$<br>$O = \frac{53.30}{16} = 3.33$<br>$C : H : O = 3.33 : 6.73 : 3.33 \approx 1 : 2 : 1$<br>එබැවින් ආනුභවික සූත්‍රය $CH_2O$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
