INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e3a6ebc4-23cf-4e99-862b-65cd1573b692', '5d386442-3b6b-5f12-ba2e-71c39c6b2b5c', 'k වැඩි වන අතර ප්‍රතික්‍රියාවේ ශීඝ්‍රතාව නොවෙනස්ව පවතී.', 'k වැඩි වන අතර ප්‍රතික්‍රියාවේ ශීඝ්‍රතාව නොවෙනස්ව පවතී.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5dd0f48b-c996-430d-824a-4fdb933a4d86', '5d386442-3b6b-5f12-ba2e-71c39c6b2b5c', 'k නොවෙනස්ව පවතින අතර ප්‍රතික්‍රියාවේ ශීඝ්‍රතාව වැඩි වේ.', 'k නොවෙනස්ව පවතින අතර ප්‍රතික්‍රියාවේ ශීඝ්‍රතාව වැඩි වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('746cbb5d-1d02-5e56-a681-05c6cde9661d', '63ada726-c109-5ebe-b233-668ff3edf116', 19, '<p>$25^{\circ}C$ දී $Ag^{+}(aq)+e\longrightarrow Ag(s)$ අර්ධ ප්‍රතික්‍රියාවේ සම්මත ඔක්සිහරණ විභවය $E^{\circ}=0.80~V$ බව දී ඇත.<br>$M(s)+3Ag^{+}(aq)\longrightarrow3Ag(s)+M^{3+}(aq)$ කෝෂයේ $25^{\circ}C$ දී $E_{cell}^{\circ}=2.46~V$ වේ.<br>$25^{\circ}C$ දී $M^{3+}(aq)+3e\longrightarrow M(s)$ අර්ධ ප්‍රතික්‍රියාවේ සම්මත ඔක්සිහරණ විභවය වනුයේ,</p>', '<p>$25^{\circ}C$ දී $Ag^{+}(aq)+e\longrightarrow Ag(s)$ අර්ධ ප්‍රතික්‍රියාවේ සම්මත ඔක්සිහරණ විභවය $E^{\circ}=0.80~V$ බව දී ඇත.<br>$M(s)+3Ag^{+}(aq)\longrightarrow3Ag(s)+M^{3+}(aq)$ කෝෂයේ $25^{\circ}C$ දී $E_{cell}^{\circ}=2.46~V$ වේ.<br>$25^{\circ}C$ දී $M^{3+}(aq)+3e\longrightarrow M(s)$ අර්ධ ප්‍රතික්‍රියාවේ සම්මත ඔක්සිහරණ විභවය වනුයේ,</p>', NULL, 'සම්මත කෝෂ විභවය ගණනය කිරීම: $E_{cell}^{\circ} = E_{cathode}^{\circ} - E_{anode}^{\circ}$<br>මෙහි ඔක්සිහරණය සිදුවන්නේ $Ag$ අයන වලට බැවින් කැතෝඩය $Ag$ වේ. ඔක්සිකරණය වන්නේ $M$ බැවින් ඇනෝඩය $M$ වේ.<br>$2.46~V = 0.80~V - E_{M}^{\circ}$<br>$E_{M}^{\circ} = 0.80~V - 2.46~V = -1.66~V$', 'සම්මත කෝෂ විභවය ගණනය කිරීම: $E_{cell}^{\circ} = E_{cathode}^{\circ} - E_{anode}^{\circ}$<br>මෙහි ඔක්සිහරණය සිදුවන්නේ $Ag$ අයන වලට බැවින් කැතෝඩය $Ag$ වේ. ඔක්සිකරණය වන්නේ $M$ බැවින් ඇනෝඩය $M$ වේ.<br>$2.46~V = 0.80~V - E_{M}^{\circ}$<br>$E_{M}^{\circ} = 0.80~V - 2.46~V = -1.66~V$', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
