INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1d87205f-e5f8-5f19-9ed0-0c03c0e42ddd', '63ada726-c109-5ebe-b233-668ff3edf116', 21, '<p>ආන්තරික ලෝහ හා ඒවායේ සංයෝග පිළිබඳ ව මින් කුමන වගන්තිය සත්‍ය වේද?</p>', '<p>ආන්තරික ලෝහ හා ඒවායේ සංයෝග පිළිබඳ ව මින් කුමන වගන්තිය සත්‍ය වේද?</p>', NULL, '$TiO_2$ හි අඩංගු වන්නේ $Ti^{4+}$ අයනයයි. $ScCl_3$ හි අඩංගු වන්නේ $Sc^{3+}$ අයනයයි. මේ අයන දෙකෙහිම ඉලෙක්ට්‍රෝන 18ක් අඩංගු වන අතර, ඒවායේ ඉලෙක්ට්‍රෝන වින්‍යාසය ආගන් ($Ar$) උච්ච වායුවේ වින්‍යාසයට ($1s^{2}2s^{2}2p^{6}3s^{2}3p^{6}$) සමාන වේ. එබැවින් ඒවායේ ඉලෙක්ට්‍රෝන වින්‍යාස එකම වේ.', '$TiO_2$ හි අඩංගු වන්නේ $Ti^{4+}$ අයනයයි. $ScCl_3$ හි අඩංගු වන්නේ $Sc^{3+}$ අයනයයි. මේ අයන දෙකෙහිම ඉලෙක්ට්‍රෝන 18ක් අඩංගු වන අතර, ඒවායේ ඉලෙක්ට්‍රෝන වින්‍යාසය ආගන් ($Ar$) උච්ච වායුවේ වින්‍යාසයට ($1s^{2}2s^{2}2p^{6}3s^{2}3p^{6}$) සමාන වේ. එබැවින් ඒවායේ ඉලෙක්ට්‍රෝන වින්‍යාස එකම වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('da1074e2-b22f-40fa-93f8-43b7e1ae37c2', '1d87205f-e5f8-5f19-9ed0-0c03c0e42ddd', 'කොපර් හි ඉලෙක්ට්‍රෝන වින්‍යාසය $1s^{2}2s^{2}2p^{6}3s^{2}3p^{6}3d^{10}$ වේ.', 'කොපර් හි ඉලෙක්ට්‍රෝන වින්‍යාසය $1s^{2}2s^{2}2p^{6}3s^{2}3p^{6}3d^{10}$ වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('42019b5e-6bb7-4dbe-8fd0-571b0e266376', '1d87205f-e5f8-5f19-9ed0-0c03c0e42ddd', 'd - ඉලෙක්ට්‍රෝන ඇති සියලු ම මූල ද්‍රව්‍ය, ආන්තරික මූල ද්‍රව්‍ය වේ.', 'd - ඉලෙක්ට්‍රෝන ඇති සියලු ම මූල ද්‍රව්‍ය, ආන්තරික මූල ද්‍රව්‍ය වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('dc26472e-7bf6-44a6-a83e-128ab5096523', '1d87205f-e5f8-5f19-9ed0-0c03c0e42ddd', '$TiO_{2}$ හි $Ti$ වල ඉලෙක්ට්‍රෝන වින්‍යාසය හා $ScCl_{3}$ හි $Sc$ වල ඉලෙක්ට්‍රෝන වින්‍යාසය එකම වේ.', '$TiO_{2}$ හි $Ti$ වල ඉලෙක්ට්‍රෝන වින්‍යාසය හා $ScCl_{3}$ හි $Sc$ වල ඉලෙක්ට්‍රෝන වින්‍යාසය එකම වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ebcbcc87-8209-475f-92ac-8d53afedcc54', '1d87205f-e5f8-5f19-9ed0-0c03c0e42ddd', 'දෙන ලද ආන්තරික ලෝහයක ඔක්සයිඩවල ආම්ලිකතාව, ලෝහ අයනයෙහි ඔක්සිකරණ අවස්ථාව වැඩිවන විට අඩු වේ.', 'දෙන ලද ආන්තරික ලෝහයක ඔක්සයිඩවල ආම්ලිකතාව, ලෝහ අයනයෙහි ඔක්සිකරණ අවස්ථාව වැඩිවන විට අඩු වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('64a3cd50-6dc3-444d-a353-0d577068ba7d', '1d87205f-e5f8-5f19-9ed0-0c03c0e42ddd', '3d ශ්‍රේණියේ ආන්තරික ලෝහ වලට ක්වොන්ටම් අංකය $m_{l}=\pm3$ තිබිය හැක.', '3d ශ්‍රේණියේ ආන්තරික ලෝහ වලට ක්වොන්ටම් අංකය $m_{l}=\pm3$ තිබිය හැක.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a45722d5-44ed-58a5-8d90-12b76ea15542', '63ada726-c109-5ebe-b233-668ff3edf116', 22, '<p>නියත උෂ්ණත්වයක ඇති සංවෘත භාජනයක් තුළ $PCl_{3}(g)+3NH_{3}(g)\rightleftharpoons P(NH_{2})_{3}(g)+3HCl(g)$ යන සමතුලිතතාව පවතී. උෂ්ණත්වය නියතව පවත්වා ගෙන මෙම භාජනයේ පරිමාව වැඩි කළේ නම්, ඉදිරි හා ආපසු ප්‍රතික්‍රියාවන්හි ශීඝ්‍රතාවල සිදුවිය හැකි වෙනස්කම් පිළිබඳව පහත සඳහන් කුමක් සත්‍ය වේද?</p>', '<p>නියත උෂ්ණත්වයක ඇති සංවෘත භාජනයක් තුළ $PCl_{3}(g)+3NH_{3}(g)\rightleftharpoons P(NH_{2})_{3}(g)+3HCl(g)$ යන සමතුලිතතාව පවතී. උෂ්ණත්වය නියතව පවත්වා ගෙන මෙම භාජනයේ පරිමාව වැඩි කළේ නම්, ඉදිරි හා ආපසු ප්‍රතික්‍රියාවන්හි ශීඝ්‍රතාවල සිදුවිය හැකි වෙනස්කම් පිළිබඳව පහත සඳහන් කුමක් සත්‍ය වේද?</p>', NULL, 'පරිමාව වැඩි කරන විට පද්ධතියේ පීඩනය සහ සියලුම වායුමය සංරචකවල සාන්ද්‍රණ අඩු වේ. සාන්ද්‍රණය අඩුවන විට, අණු අතර සිදුවන ඵලදායී ගැටුම් ප්‍රමාණය අඩුවන බැවින් ඉදිරි සහ ආපසු යන ප්‍රතික්‍රියා දෙකෙහිම ශීඝ්‍රතාවන් අඩු වේ.', 'පරිමාව වැඩි කරන විට පද්ධතියේ පීඩනය සහ සියලුම වායුමය සංරචකවල සාන්ද්‍රණ අඩු වේ. සාන්ද්‍රණය අඩුවන විට, අණු අතර සිදුවන ඵලදායී ගැටුම් ප්‍රමාණය අඩුවන බැවින් ඉදිරි සහ ආපසු යන ප්‍රතික්‍රියා දෙකෙහිම ශීඝ්‍රතාවන් අඩු වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
