INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('78a034c4-34a5-4010-83ad-de7102e2cdfd', '943aadc2-a2d9-5e5b-8467-c40e5437686f', '3d ආන්තරික ලෝහ වල විද්‍යුත් සෘණතාව 4s ලෝහවල විද්‍යුත් සෘණතාවට වඩා ඉහළ ය.', '3d ආන්තරික ලෝහ වල විද්‍යුත් සෘණතාව 4s ලෝහවල විද්‍යුත් සෘණතාවට වඩා ඉහළ ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9398777a-6e19-4a09-977c-edd0c3867ab6', '943aadc2-a2d9-5e5b-8467-c40e5437686f', '+7 ඔක්සිකරණ අවස්ථාව පෙන්නුම් කරන්නේ එක මූල ද්‍රව්‍යයක් පමණි.', '+7 ඔක්සිකරණ අවස්ථාව පෙන්නුම් කරන්නේ එක මූල ද්‍රව්‍යයක් පමණි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('55d117c7-1d79-4fea-8740-ae96be63f94c', '943aadc2-a2d9-5e5b-8467-c40e5437686f', '$MnO_{4}^{-}$, $Cr_{2}O_{7}^{2-}$ වැනි ඔක්සොඅයන ඔක්සිහරණයට ප්‍රතිරෝධයක් දක්වයි.', '$MnO_{4}^{-}$, $Cr_{2}O_{7}^{2-}$ වැනි ඔක්සොඅයන ඔක්සිහරණයට ප්‍රතිරෝධයක් දක්වයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7fbdfb42-b4b2-5e66-9851-49599de44dc7', '63ada726-c109-5ebe-b233-668ff3edf116', 25, '<p><br><br>ඉහත සඳහන් සංයෝගය වැඩිපුර $CH_{3}MgBr$ සමග ප්‍රතික්‍රියා කර ජලවිච්ඡේදනය කළ විට ලැබෙන ප්‍රධාන ඵලය වනුයේ,</p>', '<p><br><br>ඉහත සඳහන් සංයෝගය වැඩිපුර $CH_{3}MgBr$ සමග ප්‍රතික්‍රියා කර ජලවිච්ඡේදනය කළ විට ලැබෙන ප්‍රධාන ඵලය වනුයේ,</p>', NULL, 'මෙම සංයෝගයේ එස්ටර කාණ්ඩයක් ($-COOC_2H_5$) සහ එපොක්සයිඩ් වළල්ලක් (epoxide) අඩංගු වේ. ග්‍රිනාඩ් ප්‍රතිකාරකය ($CH_3MgBr$) එස්ටරය සමඟ ප්‍රතික්‍රියා කර තෘතියික මද්‍යසාරයක් සාදන අතර, එපොක්සයිඩය සමඟ ප්‍රතික්‍රියා කර වළල්ල විවෘත වීමෙන් ද්විතියික/ප්‍රාථමික මද්‍යසාරයක් ලබා දෙයි. නිවැරදි ඵලය 5 වන රූපයෙන් දැක්වේ.', 'මෙම සංයෝගයේ එස්ටර කාණ්ඩයක් ($-COOC_2H_5$) සහ එපොක්සයිඩ් වළල්ලක් (epoxide) අඩංගු වේ. ග්‍රිනාඩ් ප්‍රතිකාරකය ($CH_3MgBr$) එස්ටරය සමඟ ප්‍රතික්‍රියා කර තෘතියික මද්‍යසාරයක් සාදන අතර, එපොක්සයිඩය සමඟ ප්‍රතික්‍රියා කර වළල්ල විවෘත වීමෙන් ද්විතියික/ප්‍රාථමික මද්‍යසාරයක් ලබා දෙයි. නිවැරදි ඵලය 5 වන රූපයෙන් දැක්වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
