INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9ce40d2e-b0ad-52b2-b209-c6be1f2e8980', '63ada726-c109-5ebe-b233-668ff3edf116', 27, '<p>$NH_{3}$ සම්බන්ධව පහත සඳහන් කුමන වගන්තිය අසත්‍ය වේද?</p>', '<p>$NH_{3}$ සම්බන්ධව පහත සඳහන් කුමන වගන්තිය අසත්‍ය වේද?</p>', NULL, 'ඇමෝනියා ($NH_3$) සාමාන්‍යයෙන් ලුවිස් භස්මයක් ලෙස ක්‍රියා කළද, එයට ක්ෂාර ලෝහ වැනි ප්‍රබල විද්‍යුත් ධන මූලද්‍රව්‍ය සමඟ ප්‍රතික්‍රියා කිරීමේදී දුබල අම්ලයක් ලෙසද ක්‍රියා කර ලෝහ ඇමයිඩ සාදාගත හැක. එබැවින් එය භස්මයක් ලෙස ''පමණක්'' ක්‍රියා කරයි යන්න අසත්‍ය ප්‍රකාශයකි.', 'ඇමෝනියා ($NH_3$) සාමාන්‍යයෙන් ලුවිස් භස්මයක් ලෙස ක්‍රියා කළද, එයට ක්ෂාර ලෝහ වැනි ප්‍රබල විද්‍යුත් ධන මූලද්‍රව්‍ය සමඟ ප්‍රතික්‍රියා කිරීමේදී දුබල අම්ලයක් ලෙසද ක්‍රියා කර ලෝහ ඇමයිඩ සාදාගත හැක. එබැවින් එය භස්මයක් ලෙස ''පමණක්'' ක්‍රියා කරයි යන්න අසත්‍ය ප්‍රකාශයකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b66c7ef9-541b-4ad0-8413-484f18ec59b8', '9ce40d2e-b0ad-52b2-b209-c6be1f2e8980', '$NH_{3}$ වලට ක්‍රියා කළ හැක්කේ භස්මයක් ලෙස පමණි.', '$NH_{3}$ වලට ක්‍රියා කළ හැක්කේ භස්මයක් ලෙස පමණි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('77ec45bf-8a2c-46b4-a01f-bb3d25e3b6ac', '9ce40d2e-b0ad-52b2-b209-c6be1f2e8980', '$NH_{3}$ නෙස්ලර් ප්‍රතිකාරකය සමග දුඹුරු වර්ණයක් ලබා දේ.', '$NH_{3}$ නෙස්ලර් ප්‍රතිකාරකය සමග දුඹුරු වර්ණයක් ලබා දේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('82666197-5c9b-4ee8-973c-1fbbfa39b22f', '9ce40d2e-b0ad-52b2-b209-c6be1f2e8980', '$NH_{3}$, ඔක්සිජන් වල දහනය වී $N_{2}$ වායුව ලබා දේ.', '$NH_{3}$, ඔක්සිජන් වල දහනය වී $N_{2}$ වායුව ලබා දේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('36b66182-2429-4d13-b458-08adc9e296f1', '9ce40d2e-b0ad-52b2-b209-c6be1f2e8980', '$NH_{3}$, $Li$ සමග ප්‍රතික්‍රියා කර $Li_{3}N$ සහ $H_{2}$ වායුව ලබා දේ.', '$NH_{3}$, $Li$ සමග ප්‍රතික්‍රියා කර $Li_{3}N$ සහ $H_{2}$ වායුව ලබා දේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ada0ab2e-53cb-4971-a3ea-b4d7e085c157', '9ce40d2e-b0ad-52b2-b209-c6be1f2e8980', '$NH_{3}$ වල බන්ධන කෝණය $109^{\circ} 28''$ ට වඩා අඩුවන නමුත්, $NF_{3}$ වල බන්ධන කෝණයට වඩා වැඩි වේ.', '$NH_{3}$ වල බන්ධන කෝණය $109^{\circ} 28''$ ට වඩා අඩුවන නමුත්, $NF_{3}$ වල බන්ධන කෝණයට වඩා වැඩි වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8b877e6f-3da9-5eb5-9c4b-b0b023ed8a7c', '63ada726-c109-5ebe-b233-668ff3edf116', 28, '<p>$Zn^{2+}(aq)/Zn(s)$ සහ $Sn^{2+}(aq)/Sn(s)$ ඉලෙක්ට්‍රෝඩ භාවිත කර විද්‍යුත් රසායනික කෝෂයක් සාදන ලදි. පහත සඳහන් කුමන වගන්තිය මෙම කෝෂයෙහි ක්‍රියාවලිය නිවැරදි ව විස්තර කරයිද?<br>$E^{\circ}_{Zn^{2+}(aq)/Zn(s)}=-0.76~V$, $E^{\circ}_{Sn^{2+}(aq)/Sn(s)}=-0.14~V$</p>', '<p>$Zn^{2+}(aq)/Zn(s)$ සහ $Sn^{2+}(aq)/Sn(s)$ ඉලෙක්ට්‍රෝඩ භාවිත කර විද්‍යුත් රසායනික කෝෂයක් සාදන ලදි. පහත සඳහන් කුමන වගන්තිය මෙම කෝෂයෙහි ක්‍රියාවලිය නිවැරදි ව විස්තර කරයිද?<br>$E^{\circ}_{Zn^{2+}(aq)/Zn(s)}=-0.76~V$, $E^{\circ}_{Sn^{2+}(aq)/Sn(s)}=-0.14~V$</p>', NULL, '$Zn$ හි සම්මත ඔක්සිහරණ විභවය (-0.76 V) $Sn$ හි විභවයට (-0.14 V) වඩා අඩු බැවින්, වඩා සක්‍රීය ලෝහය වන $Zn$ ඔක්සිකරණය වී ඇනෝඩය ලෙස ක්‍රියා කරයි. ඇනෝඩයේ නිදහස් වන ඉලෙක්ට්‍රෝන බාහිර පරිපථය ඔස්සේ කැතෝඩය ($Sn$) වෙත ගමන් කරයි.', '$Zn$ හි සම්මත ඔක්සිහරණ විභවය (-0.76 V) $Sn$ හි විභවයට (-0.14 V) වඩා අඩු බැවින්, වඩා සක්‍රීය ලෝහය වන $Zn$ ඔක්සිකරණය වී ඇනෝඩය ලෙස ක්‍රියා කරයි. ඇනෝඩයේ නිදහස් වන ඉලෙක්ට්‍රෝන බාහිර පරිපථය ඔස්සේ කැතෝඩය ($Sn$) වෙත ගමන් කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('87a98461-fb52-4aa3-a0ff-a26d31a500aa', '8b877e6f-3da9-5eb5-9c4b-b0b023ed8a7c', '$Zn$ ඉලෙක්ට්‍රෝඩය කැතෝඩය වේ. $Zn$ ඔක්සිකරණය වේ. ඉලෙක්ට්‍රෝන $Sn$ සිට $Zn$ වෙත ගලා යයි.', '$Zn$ ඉලෙක්ට්‍රෝඩය කැතෝඩය වේ. $Zn$ ඔක්සිකරණය වේ. ඉලෙක්ට්‍රෝන $Sn$ සිට $Zn$ වෙත ගලා යයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7c480f36-e873-4447-8542-b9da7a70723c', '8b877e6f-3da9-5eb5-9c4b-b0b023ed8a7c', '$Zn$ ඉලෙක්ට්‍රෝඩය කැතෝඩය වේ, $Sn$ ඔක්සිකරණය වේ. ඉලෙක්ට්‍රෝන $Sn$ සිට $Zn$ වෙත ගලා යයි.', '$Zn$ ඉලෙක්ට්‍රෝඩය කැතෝඩය වේ, $Sn$ ඔක්සිකරණය වේ. ඉලෙක්ට්‍රෝන $Sn$ සිට $Zn$ වෙත ගලා යයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('755440aa-7a87-4591-942c-8322d928384c', '8b877e6f-3da9-5eb5-9c4b-b0b023ed8a7c', '$Sn$ ඉලෙක්ට්‍රෝඩය ඇනෝඩය වේ, $Zn^{2+}(aq)$ ඔක්සිහරණය වේ. ඉලෙක්ට්‍රෝන $Zn$ සිට $Sn$ වෙත ගලා යයි.', '$Sn$ ඉලෙක්ට්‍රෝඩය ඇනෝඩය වේ, $Zn^{2+}(aq)$ ඔක්සිහරණය වේ. ඉලෙක්ට්‍රෝන $Zn$ සිට $Sn$ වෙත ගලා යයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('570d4184-4949-42c3-8ca7-489cc54e7569', '8b877e6f-3da9-5eb5-9c4b-b0b023ed8a7c', '$Zn$ ඉලෙක්ට්‍රෝඩය ඇනෝඩය වේ. $Zn$ ඔක්සිකරණය වේ. ඉලෙක්ට්‍රෝන $Zn$ සිට $Sn$ වෙත ගලා යයි.', '$Zn$ ඉලෙක්ට්‍රෝඩය ඇනෝඩය වේ. $Zn$ ඔක්සිකරණය වේ. ඉලෙක්ට්‍රෝන $Zn$ සිට $Sn$ වෙත ගලා යයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9bdd88bf-5f94-44d6-8c45-707a9aa30d62', '8b877e6f-3da9-5eb5-9c4b-b0b023ed8a7c', '$Zn$ ඉලෙක්ට්‍රෝඩය ඇනෝඩය වේ, $Sn^{2+}(aq)$ ඔක්සිහරණය වේ. ඉලෙක්ට්‍රෝන $Sn$ සිට $Zn$ වෙත ගලා යයි.', '$Zn$ ඉලෙක්ට්‍රෝඩය ඇනෝඩය වේ, $Sn^{2+}(aq)$ ඔක්සිහරණය වේ. ඉලෙක්ට්‍රෝන $Sn$ සිට $Zn$ වෙත ගලා යයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('65e84d50-cb46-50ce-a4e1-1fee76af5397', '63ada726-c109-5ebe-b233-668ff3edf116', 29, '<p>පහත සඳහන් කුමන වගන්තිය $C_{6}H_{5}NH_{2}$ පිළිබඳව අසත්‍ය වේ ද?</p>', '<p>පහත සඳහන් කුමන වගන්තිය $C_{6}H_{5}NH_{2}$ පිළිබඳව අසත්‍ය වේ ද?</p>', NULL, 'ඇනිලීන් ($C_6H_5NH_2$) යනු භාස්මික සංයෝගයකි. භස්මයක් තවත් භස්මයක් වන $NaOH$ සමඟ ප්‍රතික්‍රියා කර ඇමෝනියා ($NH_3$) වායුව නිදහස් නොකරයි. ඇමෝනියා වායුව සාමාන්‍යයෙන් පිටවන්නේ ඒමයිඩ වැනි සංයෝග $NaOH$ සමඟ රත් කළ විටය.', 'ඇනිලීන් ($C_6H_5NH_2$) යනු භාස්මික සංයෝගයකි. භස්මයක් තවත් භස්මයක් වන $NaOH$ සමඟ ප්‍රතික්‍රියා කර ඇමෝනියා ($NH_3$) වායුව නිදහස් නොකරයි. ඇමෝනියා වායුව සාමාන්‍යයෙන් පිටවන්නේ ඒමයිඩ වැනි සංයෝග $NaOH$ සමඟ රත් කළ විටය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8d8880e8-2c23-4e7e-b7d8-a6fea5f24e75', '65e84d50-cb46-50ce-a4e1-1fee76af5397', '$CH_{3}COCl$ සමග ප්‍රතික්‍රියා කර ඒමයිඩයක් සාදයි.', '$CH_{3}COCl$ සමග ප්‍රතික්‍රියා කර ඒමයිඩයක් සාදයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9fc88be8-3fae-4260-bc60-0c483f9ecf24', '65e84d50-cb46-50ce-a4e1-1fee76af5397', 'ජලීය $NaOH$ සමග රත් කළ විට ඇමෝනියා වායුව පිට කරයි.', 'ජලීය $NaOH$ සමග රත් කළ විට ඇමෝනියා වායුව පිට කරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('07c2930b-f4c8-473e-80db-ed2f79305a5e', '65e84d50-cb46-50ce-a4e1-1fee76af5397', 'බ්‍රෝමීන් දියර සමග සුදු පැහැති අවක්ෂේපයක් ලබා දේ.', 'බ්‍රෝමීන් දියර සමග සුදු පැහැති අවක්ෂේපයක් ලබා දේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('61a18715-315a-4b4e-9a4e-03e0c4c36ee9', '65e84d50-cb46-50ce-a4e1-1fee76af5397', 'නයිට්‍රස් අම්ලය සමඟ ප්‍රතික්‍රියා කර වූ විට ෆීනෝලයක් ලබා දේ.', 'නයිට්‍රස් අම්ලය සමඟ ප්‍රතික්‍රියා කර වූ විට ෆීනෝලයක් ලබා දේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('145526a1-a47b-4362-bf18-d39fbb362e48', '65e84d50-cb46-50ce-a4e1-1fee76af5397', '$C_{6}H_{5}CH_{2}NH_{2}$ වලට වඩා භාස්මිකතාව අඩුය.', '$C_{6}H_{5}CH_{2}NH_{2}$ වලට වඩා භාස්මිකතාව අඩුය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a7ae6785-57cd-54e7-8e87-a8c3ce7dbb80', '63ada726-c109-5ebe-b233-668ff3edf116', 30, '<p>$CH_{3}COOAg(s)$ හා ස්පර්ශ වෙමින් පවතින සන්තෘප්ත සිල්වර් ඇසිටේට් ද්‍රාවණ හතරක් බීකර හතරක අඩංගු වේ. පහත සඳහන් ද්‍රාවණ එක් එක් බීකරයට වෙන වෙනම එකතු කළ විට සිල්වර් ඇසිටේට්හි ද්‍රාව්‍යතාව වෙනස් වන්නේ,<br><br>එකතු කරන ද්‍රාවණ: $CH_{3}COONa$, තනුක $HNO_{3}$, $NH_{4}OH$, $AgNO_{3}$</p>', '<p>$CH_{3}COOAg(s)$ හා ස්පර්ශ වෙමින් පවතින සන්තෘප්ත සිල්වර් ඇසිටේට් ද්‍රාවණ හතරක් බීකර හතරක අඩංගු වේ. පහත සඳහන් ද්‍රාවණ එක් එක් බීකරයට වෙන වෙනම එකතු කළ විට සිල්වර් ඇසිටේට්හි ද්‍රාව්‍යතාව වෙනස් වන්නේ,<br><br>එකතු කරන ද්‍රාවණ: $CH_{3}COONa$, තනුක $HNO_{3}$, $NH_{4}OH$, $AgNO_{3}$</p>', NULL, '$CH_3COONa$ සහ $AgNO_3$ එකතු කළ විට අදාළ පොදු අයන ($CH_3COO^-$ සහ $Ag^+$) හේතුවෙන් ද්‍රාව්‍යතාව අඩු වේ. තනුක $HNO_3$ එකතු කළ විට $H^+$ අයන, $CH_3COO^-$ සමඟ බැඳී දුබල අම්ලයක් වන $CH_3COOH$ සාදන නිසා සමතුලිතතාව දකුණට බර වී ද්‍රාව්‍යතාව වැඩි වේ. $NH_4OH$ එකතු කළ විට $Ag^+$ අයන සමඟ සංකීර්ණයක් ($[Ag(NH_3)_2]^+$) සාදන නිසා ද්‍රාව්‍යතාව වැඩි වේ.', '$CH_3COONa$ සහ $AgNO_3$ එකතු කළ විට අදාළ පොදු අයන ($CH_3COO^-$ සහ $Ag^+$) හේතුවෙන් ද්‍රාව්‍යතාව අඩු වේ. තනුක $HNO_3$ එකතු කළ විට $H^+$ අයන, $CH_3COO^-$ සමඟ බැඳී දුබල අම්ලයක් වන $CH_3COOH$ සාදන නිසා සමතුලිතතාව දකුණට බර වී ද්‍රාව්‍යතාව වැඩි වේ. $NH_4OH$ එකතු කළ විට $Ag^+$ අයන සමඟ සංකීර්ණයක් ($[Ag(NH_3)_2]^+$) සාදන නිසා ද්‍රාව්‍යතාව වැඩි වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = exclu