INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8a3668ff-e34d-441d-a1fd-f1a579a46934', 'a7ae6785-57cd-54e7-8e87-a8c3ce7dbb80', '$CH_{3}COONa$: වැඩි වේ. | තනුක $HNO_{3}$: අඩු වේ. | $NH_{4}OH$: වැඩි වේ. | $AgNO_{3}$: අඩු වේ.', '$CH_{3}COONa$: වැඩි වේ. | තනුක $HNO_{3}$: අඩු වේ. | $NH_{4}OH$: වැඩි වේ. | $AgNO_{3}$: අඩු වේ.', NULL, 'sanitized', 'v1', 0, 1);
