INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1eee671a-70f0-45dc-adf5-c10d8dc319e0', '7250a4ca-bf8a-54a9-8c25-e266fffe10d0', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fdf046a2-3a4c-587d-b537-039823eb1318', '63ada726-c109-5ebe-b233-668ff3edf116', 46, '<p>පළමු වැනි ප්‍රකාශය: සියලු ම ස්වයංසිද්ධ ප්‍රතික්‍රියා තාපදායක වේ.<br>දෙවැනි ප්‍රකාශය: ඕනෑම ප්‍රතික්‍රියාවකට $\Delta G=\Delta H+T\Delta S$ වේ.</p>', '<p>පළමු වැනි ප්‍රකාශය: සියලු ම ස්වයංසිද්ධ ප්‍රතික්‍රියා තාපදායක වේ.<br>දෙවැනි ප්‍රකාශය: ඕනෑම ප්‍රතික්‍රියාවකට $\Delta G=\Delta H+T\Delta S$ වේ.</p>', NULL, 'තාපාවශෝෂක ප්‍රතික්‍රියා පවා එන්ට්‍රොපිය වැඩිවීම මත ස්වයංසිද්ධ විය හැකි බැවින් පළමු ප්‍රකාශය අසත්‍ය වේ. ගිබ්ස් ශක්ති සමීකරණය $\Delta G=\Delta H-T\Delta S$ වන බැවින් දෙවැනි ප්‍රකාශය ද අසත්‍ය වේ.', 'තාපාවශෝෂක ප්‍රතික්‍රියා පවා එන්ට්‍රොපිය වැඩිවීම මත ස්වයංසිද්ධ විය හැකි බැවින් පළමු ප්‍රකාශය අසත්‍ය වේ. ගිබ්ස් ශක්ති සමීකරණය $\Delta G=\Delta H-T\Delta S$ වන බැවින් දෙවැනි ප්‍රකාශය ද අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
