INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('049450ab-c965-4f8c-9c5c-96e70e90c903', 'fdf046a2-3a4c-587d-b537-039823eb1318', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන නමුත් පළමු වැනි ප්‍රකාශය නිවැරදි ව පහදා නොදෙයි.', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන නමුත් පළමු වැනි ප්‍රකාශය නිවැරදි ව පහදා නොදෙයි.', NULL, 'sanitized', 'v1', 1, 0);
