INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('069019d2-5d50-49db-87fd-8b955245b98a', '85aaa397-4357-5834-8fb7-fa93b1adc127', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන නමුත් පළමු වැනි ප්‍රකාශය නිවැරදි ව පහදා නොදෙයි.', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන නමුත් පළමු වැනි ප්‍රකාශය නිවැරදි ව පහදා නොදෙයි.', NULL, 'sanitized', 'v1', 1, 0);
