INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('86e65e12-dd05-4edd-9d8d-7ded7c02ab18', '85aaa397-4357-5834-8fb7-fa93b1adc127', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('dac8ea2c-4454-5050-9067-6a5911b7a032', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 1, '<p>ශාක සෛලවල පහත දැක්වෙන ඉන්ද්‍රියිකා අතුරෙන් කවරක් මේද, කාබොහයිඩ්‍රේටවලට පරිවර්තනය කරයිද?</p>', '<p>ශාක සෛලවල පහත දැක්වෙන ඉන්ද්‍රියිකා අතුරෙන් කවරක් මේද, කාබොහයිඩ්‍රේටවලට පරිවර්තනය කරයිද?</p>', NULL, 'ග්ලයොක්සිසෝම මගින් මේද කාබොහයිඩ්‍රේට බවට පරිවර්තනය කිරීම (ග්ලයිඔක්සිලේට් චක්‍රය) සිදු කරයි.', 'ග්ලයොක්සිසෝම මගින් මේද කාබොහයිඩ්‍රේට බවට පරිවර්තනය කිරීම (ග්ලයිඔක්සිලේට් චක්‍රය) සිදු කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
