INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a339fb4a-9fa8-43ea-a79e-a54e55a9416f', '3708d3db-2382-5cb7-afa3-fa70a76f57b0', 'සියලු ම ප්‍රාග්න්‍යෂ්ටික ජීවීන්ගේ රයිබොසෝම දක්නට නැත.', 'සියලු ම ප්‍රාග්න්‍යෂ්ටික ජීවීන්ගේ රයිබොසෝම දක්නට නැත.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('294f4a59-840f-4b49-b706-8e5c830dfd19', '3708d3db-2382-5cb7-afa3-fa70a76f57b0', 'සියලු ම ප්‍රාග්න්‍යෂ්ටික ජීවීන් ක්ෂුද්‍රජීවීන් නොවේ.', 'සියලු ම ප්‍රාග්න්‍යෂ්ටික ජීවීන් ක්ෂුද්‍රජීවීන් නොවේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3c12f76c-056d-53b0-a561-b3d942c0230a', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 3, '<p>එක්තරා ජීවියෙකුගේ DNAවල සංයුතියෙන් $23.3\%$ක් ඇඩිනීන් (A) භෂ්මය වේ. පහත සඳහන් කවරක් එම ජීවියාගේ DNAවල භෂ්ම සංයුතිය විය හැකි ද?</p>', '<p>එක්තරා ජීවියෙකුගේ DNAවල සංයුතියෙන් $23.3\%$ක් ඇඩිනීන් (A) භෂ්මය වේ. පහත සඳහන් කවරක් එම ජීවියාගේ DNAවල භෂ්ම සංයුතිය විය හැකි ද?</p>', NULL, 'චාගාෆ් නියමයට අනුව $A = T$ සහ $G = C$ වේ. $A = 23.3\%$ නම්, $T = 23.3\%$ වේ. එවිට $A + T = 46.6\%$. ඉතිරි ප්‍රතිශතය $100\% - 46.6\% = 53.4\%$ වේ. එය $G$ සහ $C$ අතර සමව බෙදී යා යුතු බැවින් $G = C = 26.7\%$ වේ.', 'චාගාෆ් නියමයට අනුව $A = T$ සහ $G = C$ වේ. $A = 23.3\%$ නම්, $T = 23.3\%$ වේ. එවිට $A + T = 46.6\%$. ඉතිරි ප්‍රතිශතය $100\% - 46.6\% = 53.4\%$ වේ. එය $G$ සහ $C$ අතර සමව බෙදී යා යුතු බැවින් $G = C = 26.7\%$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
