INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a4cfb021-0725-4b7b-837a-2d00e2bf984b', '3adca883-99a4-5bc8-84c9-470da020155f', 'ග්ලූකෝස්, $CO_2$ වලට සහ ජලයට ඔක්සිකරණය වීම', 'ග්ලූකෝස්, $CO_2$ වලට සහ ජලයට ඔක්සිකරණය වීම', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d3586ea1-dc09-515e-9504-b91045801dcb', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 6, '<p>ශාකවල $C_3$ සහ $C_4$ ප්‍රභාසංශ්ලේෂණ පිළිබඳ පහත දැක්වෙන සංසන්දන අතුරෙන් වැරදි වන්නේ කුමක්ද?</p>', '<p>ශාකවල $C_3$ සහ $C_4$ ප්‍රභාසංශ්ලේෂණ පිළිබඳ පහත දැක්වෙන සංසන්දන අතුරෙන් වැරදි වන්නේ කුමක්ද?</p>', NULL, 'සාමාන්‍යයෙන් $C_4$ ශාක වල ප්‍රභාසංශ්ලේෂණ ඵලදාව $C_3$ ශාක වලට වඩා වැඩිය. එබැවින් 4 වන සංසන්දනය වැරදිය.', 'සාමාන්‍යයෙන් $C_4$ ශාක වල ප්‍රභාසංශ්ලේෂණ ඵලදාව $C_3$ ශාක වලට වඩා වැඩිය. එබැවින් 4 වන සංසන්දනය වැරදිය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('558750e7-1f4a-4c02-8b51-2b755e189593', 'd3586ea1-dc09-515e-9504-b91045801dcb', '$C_3$: $CO_2$ තිර කිරීම සිදු වන්නේ එක් වරක් පමණි. - $C_4$: $CO_2$ තිර කිරීම දෙවරක් සිදු වේ.', '$C_3$: $CO_2$ තිර කිරීම සිදු වන්නේ එක් වරක් පමණි. - $C_4$: $CO_2$ තිර කිරීම දෙවරක් සිදු වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6434070e-0d6b-406e-9f76-0f2f3cda5304', 'd3586ea1-dc09-515e-9504-b91045801dcb', '$C_3$: ප්‍රධාන $CO_2$ ප්‍රතිග්‍රාහකය RuBP වේ. - $C_4$: ප්‍රධාන $CO_2$ ප්‍රතිග්‍රාහකය PEP වේ.', '$C_3$: ප්‍රධාන $CO_2$ ප්‍රතිග්‍රාහකය RuBP වේ. - $C_4$: ප්‍රධාන $CO_2$ ප්‍රතිග්‍රාහකය PEP වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c1b7d4ec-b8b5-4785-bddc-eb52dd229fd7', 'd3586ea1-dc09-515e-9504-b91045801dcb', '$C_3$: $CO_2$ තිර කිරීමේ එන්සයිමය RuBP කාබොක්සිලේස් වේ. - $C_4$: $CO_2$ තිර කිරීමේ එන්සයිමය PEP කාබොක්සිලේස් වේ.', '$C_3$: $CO_2$ තිර කිරීමේ එන්සයිමය RuBP කාබොක්සිලේස් වේ. - $C_4$: $CO_2$ තිර කිරීමේ එන්සයිමය PEP කාබොක්සිලේස් වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('86134ea7-3027-4e39-b6d9-23c9e46436b9', 'd3586ea1-dc09-515e-9504-b91045801dcb', '$C_3$: ප්‍රභාසංශ්ලේෂණ ඵලදාව වැඩිය. - $C_4$: ප්‍රභාසංශ්ලේෂණ ඵලදාව සාමාන්‍යයෙන් අඩු ය.', '$C_3$: ප්‍රභාසංශ්ලේෂණ ඵලදාව වැඩිය. - $C_4$: ප්‍රභාසංශ්ලේෂණ ඵලදාව සාමාන්‍යයෙන් අඩු ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d9bb4bef-739f-4d28-bc0c-bca3780ee750', 'd3586ea1-dc09-515e-9504-b91045801dcb', '$C_3$: ප්‍රභාසංශ්ලේෂණයේ ප්‍රථම ඵලය PGA වේ. - $C_4$: ප්‍රභාසංශ්ලේෂණයේ ප්‍රථම ඵලය ඔක්සැලොඇසිටේට් වේ.', '$C_3$: ප්‍රභාසංශ්ලේෂණයේ ප්‍රථම ඵලය PGA වේ. - $C_4$: ප්‍රභාසංශ්ලේෂණයේ ප්‍රථම ඵලය ඔක්සැලොඇසිටේට් වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9d45910f-f55d-56bd-93d4-c72b4b99f851', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 7, '<p>A, B, C සහ D ලෙස සලකුණු කර ඇති එක් එක් ජීවියාගේ ලක්ෂණයක් බැගින් පහත දී ඇත.<br><br>(A) විෂමබීජාණුක වේ.<br>(B) ජන්මාණුශාකය ප්‍රභාසංශ්ලේෂක වේ.<br>(C) බීජ නොමැත.<br>(D) ජන්මාණුශාකය තලසාකාර වේ.<br><br>A, B, C සහ D යන ජීවීන් නිවැරදි අනුපිළිවෙළින්</p>', '<p>A, B, C සහ D ලෙස සලකුණු කර ඇති එක් එක් ජීවියාගේ ලක්ෂණයක් බැගින් පහත දී ඇත.<br><br>(A) විෂමබීජාණුක වේ.<br>(B) ජන්මාණුශාකය ප්‍රභාසංශ්ලේෂක වේ.<br>(C) බීජ නොමැත.<br>(D) ජන්මාණුශාකය තලසාකාර වේ.<br><br>A, B, C සහ D යන ජීවීන් නිවැරදි අනුපිළිවෙළින්</p>', NULL, '(A) Selaginella යනු විෂම බීජාණුක ශාකයකි. (B) Nephrolepis හි ජන්මාණු ශාකය ප්‍රභාසංශ්ලේෂක වේ (ප්‍රෝතැල්ලසය). (C) Lycopodium යනු බීජ රහිත සනාල ශාකයකි. (D) Marchantia හි ජන්මාණු ශාකය තලසාකාර වේ.', '(A) Selaginella යනු විෂම බීජාණුක ශාකයකි. (B) Nephrolepis හි ජන්මාණු ශාකය ප්‍රභාසංශ්ලේෂක වේ (ප්‍රෝතැල්ලසය). (C) Lycopodium යනු බීජ රහිත සනාල ශාකයකි. (D) Marchantia හි ජන්මාණු ශාකය තලසාකාර වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
