INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d306288f-8f56-499d-a26d-8f8e1cd3d3ec', 'a62c5eb7-12f5-5cc2-b541-247c5c95657d', '$B_{1}$, $B_{2}$, පැන්ටොතෙනික් අම්ලය', '$B_{1}$, $B_{2}$, පැන්ටොතෙනික් අම්ලය', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('473c1f7a-68c8-51d4-91e6-63840f841a4e', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 12, '<p>මිනිසාගේ ශ්වසන පද්ධතිය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ක්ද?</p>', '<p>මිනිසාගේ ශ්වසන පද්ධතිය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ක්ද?</p>', NULL, 'ආශ්වාසයේදී බාහිර අන්තර්පර්ශුක පේශි (external intercostal muscles) සංකෝචනය වී පර්ශු ඉහළට හා පිටතට ගමන් කිරීමෙන් උරස් කුහරයේ පරිමාව වැඩි වේ.<br><br>අනෙකුත් ප්‍රකාශ වැරදිය: දකුණු පෙනහල්ල ඛණ්ඩිකා 3කින් සමන්විත වේ. ශ්වාසනාල කුහරය ව්‍යාජස්තරිත පක්ෂ්මල ස්තම්භික අපිච්ඡදයකින් ආස්තරණය වේ. වායු හුවමාරුව විසරණයෙන් සිදුවන බැවින් ශක්තිය අනවශ්‍යය. ස්වරාලය 3-6 ග්‍රෛවී කශේරුකා මට්ටමේ පවතී.', 'ආශ්වාසයේදී බාහිර අන්තර්පර්ශුක පේශි (external intercostal muscles) සංකෝචනය වී පර්ශු ඉහළට හා පිටතට ගමන් කිරීමෙන් උරස් කුහරයේ පරිමාව වැඩි වේ.<br><br>අනෙකුත් ප්‍රකාශ වැරදිය: දකුණු පෙනහල්ල ඛණ්ඩිකා 3කින් සමන්විත වේ. ශ්වාසනාල කුහරය ව්‍යාජස්තරිත පක්ෂ්මල ස්තම්භික අපිච්ඡදයකින් ආස්තරණය වේ. වායු හුවමාරුව විසරණයෙන් සිදුවන බැවින් ශක්තිය අනවශ්‍යය. ස්වරාලය 3-6 ග්‍රෛවී කශේරුකා මට්ටමේ පවතී.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('db19dd5b-e752-4b50-a787-354198acd914', '473c1f7a-68c8-51d4-91e6-63840f841a4e', 'බාහිර අන්තර්පර්ශුක පේශිවල සංකෝචනය නිසා ආශ්වාසය සිදු වේ.', 'බාහිර අන්තර්පර්ශුක පේශිවල සංකෝචනය නිසා ආශ්වාසය සිදු වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('93820a65-0fa9-43ae-8857-0b37bd642c5e', '473c1f7a-68c8-51d4-91e6-63840f841a4e', 'ශ්වාසනාල කුහරය ස්තම්භික අපිච්ඡදයෙන් ආස්තරණය වේ.', 'ශ්වාසනාල කුහරය ස්තම්භික අපිච්ඡදයෙන් ආස්තරණය වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a6d18241-c705-4b6a-a957-61f43dc0f044', '473c1f7a-68c8-51d4-91e6-63840f841a4e', 'දකුණු පෙනහැල්ල ඛණ්ඩිකා දෙකකින් සමන්විත වේ.', 'දකුණු පෙනහැල්ල ඛණ්ඩිකා දෙකකින් සමන්විත වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c3dcf5ce-819b-4a3e-8ff2-a90835a7f417', '473c1f7a-68c8-51d4-91e6-63840f841a4e', 'පෙනහැලි තුළ දී ශ්වසන වායු හුවමාරුව සඳහා ශක්තිය අවශ්‍ය වේ.', 'පෙනහැලි තුළ දී ශ්වසන වායු හුවමාරුව සඳහා ශක්තිය අවශ්‍ය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('310e45f8-a8e9-450f-a9b1-d6251e116a4b', '473c1f7a-68c8-51d4-91e6-63840f841a4e', 'ස්වරාලය දෙවැනි සහ තුන්වැනි ග්‍රෛවී කශේරුකා මට්ටමේ පිහිටයි.', 'ස්වරාලය දෙවැනි සහ තුන්වැනි ග්‍රෛවී කශේරුකා මට්ටමේ පිහිටයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f94406d7-6266-55db-b7e0-44eeedfb4c84', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 13, '<p>මිනිස් රුධිරය පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මිනිස් රුධිරය පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'කාබන් ඩයොක්සයිඩ් ($CO_2$) වැඩිම ප්‍රමාණයක් ($70\%$ පමණ) පරිවහනය වන්නේ රුධිර ප්ලාස්මාවේ බයිකාබනේට් අයන ($HCO_3^-$) ලෙසිනි. හිමොග්ලොබින් සමග බැඳී පරිවහනය වන්නේ $23\%$ පමණ සුළු ප්‍රමාණයකි.', 'කාබන් ඩයොක්සයිඩ් ($CO_2$) වැඩිම ප්‍රමාණයක් ($70\%$ පමණ) පරිවහනය වන්නේ රුධිර ප්ලාස්මාවේ බයිකාබනේට් අයන ($HCO_3^-$) ලෙසිනි. හිමොග්ලොබින් සමග බැඳී පරිවහනය වන්නේ $23\%$ පමණ සුළු ප්‍රමාණයකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('af374479-92f7-4f88-a6f3-045fef793aac', 'f94406d7-6266-55db-b7e0-44eeedfb4c84', 'එය විශේෂිත සම්බන්ධක පටකයකි.', 'එය විශේෂිත සම්බන්ධක පටකයකි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2d968b1a-8f9b-43b3-82ca-d47f69d774bc', 'f94406d7-6266-55db-b7e0-44eeedfb4c84', 'පරිණත රක්තාණුවක්, න්‍යෂ්ටිය සහ මයිටොකොන්ඩ්‍රියා යන දෙක ම නොදරයි.', 'පරිණත රක්තාණුවක්, න්‍යෂ්ටිය සහ මයිටොකොන්ඩ්‍රියා යන දෙක ම නොදරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('dbd1fb08-3ee2-4af8-b29a-eea48b90f995', 'f94406d7-6266-55db-b7e0-44eeedfb4c84', 'නියුට්‍රොෆිල සහ මොනොසයිට භක්ෂසෛලකතාව දක්වන සුදු රුධිරාණු වේ.', 'නියුට්‍රොෆිල සහ මොනොසයිට භක්ෂසෛලකතාව දක්වන සුදු රුධිරාණු වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f25eb8dd-1a86-41fe-a239-57bc1a73b801', 'f94406d7-6266-55db-b7e0-44eeedfb4c84', 'කාබන් ඩයොක්සයිඩ්වලින් වැඩි ම ප්‍රමාණයක් පරිවහනය කෙරෙනුයේ හීමොග්ලොබින් සමඟ සම්බන්ධ වීමෙනි.', 'කාබන් ඩයොක්සයිඩ්වලින් වැඩි ම ප්‍රමාණයක් පරිවහනය කෙරෙනුයේ හීමොග්ලොබින් සමඟ සම්බන්ධ වීමෙනි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c95bb36e-6019-4c71-9ce5-840bbd9a6cb5', 'f94406d7-6266-55db-b7e0-44eeedfb4c84', 'එය දේහ උෂ්ණත්වය යාමනය කිරීමට උපකාරී වේ.', 'එය දේහ උෂ්ණත්වය යාමනය කිරීමට උපකාරී වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f1e4ced5-fd69-517a-bb11-816fa9d293c8', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 14, '<p>මිනිස් හෘදයේ සන්නායක පද්ධතියේ කොටසක් නොවන්නේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', '<p>මිනිස් හෘදයේ සන්නායක පද්ධතියේ කොටසක් නොවන්නේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', NULL, 'හෘද් රජ්ජු (Chordae tendineae) යනු කර්ණික කෝෂික කපාට (ද්වීතුණ්ඩ හා ත්‍රිතුණ්ඩ කපාට)වල පියන් කෝෂිකා බිත්තිවල ඇති පැපිලරි පේශීවලට සම්බන්ධ කරන තන්තුමය ව්‍යුහයන් වන අතර, ඒවා හෘද සන්නායක පද්ධතියට අයත් නොවේ. සන්නායක පද්ධතියට SA ගැටය, AV ගැටය, හිස් කළඹ සහ පර්කින්ජේ තන්තු අයත් වේ.', 'හෘද් රජ්ජු (Chordae tendineae) යනු කර්ණික කෝෂික කපාට (ද්වීතුණ්ඩ හා ත්‍රිතුණ්ඩ කපාට)වල පියන් කෝෂිකා බිත්තිවල ඇති පැපිලරි පේශීවලට සම්බන්ධ කරන තන්තුමය ව්‍යුහයන් වන අතර, ඒවා හෘද සන්නායක පද්ධතියට අයත් නොවේ. සන්නායක පද්ධතියට SA ගැටය, AV ගැටය, හිස් කළඹ සහ පර්කින්ජේ තන්තු අයත් වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
