INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9842d19e-ea68-4c9d-bfc0-7d8f3bd0af44', 'fb303f06-6b89-50ff-8f3a-6144606d9e96', 'ශාකවල වර්ධනය වන මුලාග්‍ර හා ප්‍රරෝහ අග්‍ර සාමාන්‍යයෙන් සීනි අපායනය වන ස්ථාන වේ.', 'ශාකවල වර්ධනය වන මුලාග්‍ර හා ප්‍රරෝහ අග්‍ර සාමාන්‍යයෙන් සීනි අපායනය වන ස්ථාන වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('67a341bb-d6e4-486c-92a4-bbcfdb922cb9', 'fb303f06-6b89-50ff-8f3a-6144606d9e96', 'එක් පෙනේර නළ ඒකකයක සිට ඊළඟ පෙනේර නළ ඒකකයට ප්ලෝයම යුෂ පරිසංක්‍රමණය වීම නිෂ්ක්‍රීය ක්‍රියාවලියකි.', 'එක් පෙනේර නළ ඒකකයක සිට ඊළඟ පෙනේර නළ ඒකකයට ප්ලෝයම යුෂ පරිසංක්‍රමණය වීම නිෂ්ක්‍රීය ක්‍රියාවලියකි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4db60110-93b4-5cf1-903a-fb03c114b9bf', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 17, '<p>මානව වර්ධක හෝර්මෝනය පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මානව වර්ධක හෝර්මෝනය පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'මානව වර්ධක හෝර්මෝනය (hGH) මේද බිඳවැටීම (lipolysis) උත්තේජනය කරන අතර මේද සංශ්ලේෂණය වැඩි නොකරයි. එසේම එය ප්‍රෝටීන් සංශ්ලේෂණය වැඩි කරමින් රුධිර ග්ලූකෝස් මට්ටම ඉහළ නංවයි.', 'මානව වර්ධක හෝර්මෝනය (hGH) මේද බිඳවැටීම (lipolysis) උත්තේජනය කරන අතර මේද සංශ්ලේෂණය වැඩි නොකරයි. එසේම එය ප්‍රෝටීන් සංශ්ලේෂණය වැඩි කරමින් රුධිර ග්ලූකෝස් මට්ටම ඉහළ නංවයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
