INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('03f9accc-31c1-4a07-86bc-7295efd6b6f4', '4db60110-93b4-5cf1-903a-fb03c114b9bf', 'එය අක්මාවේ පරිවෘත්තිය යාමනය කරයි.', 'එය අක්මාවේ පරිවෘත්තිය යාමනය කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3e023470-c60c-54a6-8fb4-f11ac8194afd', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 18, '<p>මිනිස් මොළය පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මිනිස් මොළය පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'කැස්ස (coughing), කිවිසුම් යාම, ගිලීම සහ වමනය වැනි ක්‍රියාවන් සඳහා වූ ප්‍රතීක මධ්‍යස්ථාන පිහිටා ඇත්තේ සුෂුම්නා ශීර්ෂයේ (medulla oblongata) මිස වැරෝලි සේතුවේ (pons) නොවේ.', 'කැස්ස (coughing), කිවිසුම් යාම, ගිලීම සහ වමනය වැනි ක්‍රියාවන් සඳහා වූ ප්‍රතීක මධ්‍යස්ථාන පිහිටා ඇත්තේ සුෂුම්නා ශීර්ෂයේ (medulla oblongata) මිස වැරෝලි සේතුවේ (pons) නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b4c208f8-8e2b-48bd-883e-a996b611165e', '3e023470-c60c-54a6-8fb4-f11ac8194afd', 'කථනය හා සම්බන්ධ ක්‍රියාකාරී ප්‍රදේශය පිහිටන්නේ ලලාට ඛණ්ඩිකාවේය.', 'කථනය හා සම්බන්ධ ක්‍රියාකාරී ප්‍රදේශය පිහිටන්නේ ලලාට ඛණ්ඩිකාවේය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b1a59770-8dda-4cf5-93a6-a31a9a2a8dae', '3e023470-c60c-54a6-8fb4-f11ac8194afd', 'කැලෝස දේහය මගින් මස්තිෂ්කයේ අර්ධ ගෝල දෙක සම්බන්ධ වේ.', 'කැලෝස දේහය මගින් මස්තිෂ්කයේ අර්ධ ගෝල දෙක සම්බන්ධ වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('29aa1394-c42c-469b-8256-0fb1690f3320', '3e023470-c60c-54a6-8fb4-f11ac8194afd', 'සංතුලනය සහ සමතුලිතතාව පවත්වා ගැනීමේ ලා අනුමස්තිෂ්කය වැදගත් කාර්යභාරයක් ඉටු කරයි.', 'සංතුලනය සහ සමතුලිතතාව පවත්වා ගැනීමේ ලා අනුමස්තිෂ්කය වැදගත් කාර්යභාරයක් ඉටු කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('73997aed-9aad-4660-bf77-31771fd59481', '3e023470-c60c-54a6-8fb4-f11ac8194afd', 'සංවේදක තොරතුරු සමෝධානය කිරීමේ දී තැල මස දායක වේ.', 'සංවේදක තොරතුරු සමෝධානය කිරීමේ දී තැල මස දායක වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('38847efd-fd16-4c85-8fb5-40b1b8226c9a', '3e023470-c60c-54a6-8fb4-f11ac8194afd', 'කැස්ස සඳහා ප්‍රතීක මධ්‍යස්ථානය පිහිටන්නේ වැරෝලි සේතුවේය.', 'කැස්ස සඳහා ප්‍රතීක මධ්‍යස්ථානය පිහිටන්නේ වැරෝලි සේතුවේය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5d0d36aa-1bdf-54df-8b3d-d5e282434803', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 19, '<p>මිනිස් චාලක නියුරෝනයක ක්‍රියා විභවයක් පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මිනිස් චාලක නියුරෝනයක ක්‍රියා විභවයක් පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'ක්‍රියා විභවයකදී විධ්‍රැවණ (depolarization) කලාවට වහාම පසුව ඇතිවන්නේ ප්‍රතිධ්‍රැවණ (repolarization) කලාවයි. උපරිධ්‍රැවණය (hyperpolarization) ඇතිවන්නේ ප්‍රතිධ්‍රැවණ කලාවෙන් පසුවය.', 'ක්‍රියා විභවයකදී විධ්‍රැවණ (depolarization) කලාවට වහාම පසුව ඇතිවන්නේ ප්‍රතිධ්‍රැවණ (repolarization) කලාවයි. උපරිධ්‍රැවණය (hyperpolarization) ඇතිවන්නේ ප්‍රතිධ්‍රැවණ කලාවෙන් පසුවය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7cef9b2f-0aad-4a62-bf1d-a99990189d73', '5d0d36aa-1bdf-54df-8b3d-d5e282434803', 'එක් ක්‍රියා විභවයකට වහාම පසුව, දෙවැනි ක්‍රියා විභවයක් ජනනය කිරීමට නොහැකි ය.', 'එක් ක්‍රියා විභවයකට වහාම පසුව, දෙවැනි ක්‍රියා විභවයක් ජනනය කිරීමට නොහැකි ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2d32ca7e-8d99-4074-8c59-da9d3964658c', '5d0d36aa-1bdf-54df-8b3d-d5e282434803', 'එය ජනනය වනුයේ රැන්වියර් ගැටවල දී පමණි.', 'එය ජනනය වනුයේ රැන්වියර් ගැටවල දී පමණි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('67cab400-87e4-4a4b-8745-f49c1342fa18', '5d0d36aa-1bdf-54df-8b3d-d5e282434803', 'එහි විධ්‍රැවණ කලාවට වහාම පසුව, උපරිධ්‍රැවණ කලාව ඇති වේ.', 'එහි විධ්‍රැවණ කලාවට වහාම පසුව, උපරිධ්‍රැවණ කලාව ඇති වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('56083814-95d1-4671-9f0e-3c12450f5952', '5d0d36aa-1bdf-54df-8b3d-d5e282434803', 'එහි කාලසීමාව මිලිතත්පර දෙකක් පමණ වේ.', 'එහි කාලසීමාව මිලිතත්පර දෙකක් පමණ වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('40a994dc-ed85-40b7-ada1-8503755050c9', '5d0d36aa-1bdf-54df-8b3d-d5e282434803', 'එය ජනනය කිරීම සඳහා දේහලිය උත්තේජයක් අත්‍යවශ්‍ය වේ.', 'එය ජනනය කිරීම සඳහා දේහලිය උත්තේජයක් අත්‍යවශ්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7b925149-f326-516f-9d23-b402dcad55ce', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 20, '<p>බහිස්ස්‍රාවය පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>බහිස්ස්‍රාවය පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'මලපහ කිරීම (Defecation) යනු ආහාර ජීර්ණ පද්ධතිය හරහා ගමන් ගත් ජීර්ණය නොවූ ආහාර කොටස් සිරුරෙන් බැහැර කිරීමයි. බහිස්ස්‍රාවය (Excretion) යනු දේහ සෛල වල පරිවෘත්තීය ප්‍රතික්‍රියා වලින් ජනනය වන අපද්‍රව්‍ය බැහැර කිරීමයි. එබැවින් මලපහ කිරීම ජීව විද්‍යාත්මක බහිස්ස්‍රාවී ක්‍රියාවලියක් ලෙස නොසැලකේ.', 'මලපහ කිරීම (Defecation) යනු ආහාර ජීර්ණ පද්ධතිය හරහා ගමන් ගත් ජීර්ණය නොවූ ආහාර කොටස් සිරුරෙන් බැහැර කිරීමයි. බහිස්ස්‍රාවය (Excretion) යනු දේහ සෛල වල පරිවෘත්තීය ප්‍රතික්‍රියා වලින් ජනනය වන අපද්‍රව්‍ය බැහැර කිරීමයි. එබැවින් මලපහ කිරීම ජීව විද්‍යාත්මක බහිස්ස්‍රාවී ක්‍රියාවලියක් ලෙස නොසැලකේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
