INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('da2185dc-bd06-458b-9d23-01a5971f16b9', '7b925149-f326-516f-9d23-b402dcad55ce', 'පිත්ත වර්ණක මිනිසාගේ බහිස්ස්‍රාවී ඵලයක් වේ.', 'පිත්ත වර්ණක මිනිසාගේ බහිස්ස්‍රාවී ඵලයක් වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e53a3008-bf95-4c7d-a87b-9ff07d5c3fe0', '7b925149-f326-516f-9d23-b402dcad55ce', 'නයිට්‍රජනීය බහිස්ස්‍රාවී ඵලය ලෙස යුරික් අම්ලය නිපද වන විට කාබන් හානිය උපරිම වේ.', 'නයිට්‍රජනීය බහිස්ස්‍රාවී ඵලය ලෙස යුරික් අම්ලය නිපද වන විට කාබන් හානිය උපරිම වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d323e6cd-0ac6-4b06-bfc9-710308fabc46', '7b925149-f326-516f-9d23-b402dcad55ce', 'බහිස්ස්‍රාවී ඵලයක් ලෙස ඇමෝනියා නිපදවීමට ශක්තිය අවශ්‍ය නොවේ.', 'බහිස්ස්‍රාවී ඵලයක් ලෙස ඇමෝනියා නිපදවීමට ශක්තිය අවශ්‍ය නොවේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('13dca0c3-baed-5dc7-944c-a541de5ab815', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 21, '<p>සිනිඳු පේශී පිළිබඳ වැරදි වනුයේ පහත සඳහන් ප්‍රකාශ අතුරෙන් කුමක්ද?</p>', '<p>සිනිඳු පේශී පිළිබඳ වැරදි වනුයේ පහත සඳහන් ප්‍රකාශ අතුරෙන් කුමක්ද?</p>', NULL, 'සිනිඳු පේශි ඉක්මනින් විඩාවට පත් නොවේ. ඒවාට දිගු කාලයක් තිස්සේ විඩාවට පත් නොවී නොකඩවා සංකෝචනය වී පැවතීමේ හැකියාව ඇත. ඉක්මනින් විඩාවට පත්වන්නේ කංකාල පේශි වේ.', 'සිනිඳු පේශි ඉක්මනින් විඩාවට පත් නොවේ. ඒවාට දිගු කාලයක් තිස්සේ විඩාවට පත් නොවී නොකඩවා සංකෝචනය වී පැවතීමේ හැකියාව ඇත. ඉක්මනින් විඩාවට පත්වන්නේ කංකාල පේශි වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
