INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ceb1fcaf-b0c1-4278-befd-822e0031d6cd', '76b04360-ee95-56ed-95c2-9692b229d280', 'එය සංකෝචනය වීමේ දී බල පහර ශ්‍රේණියක් ඇති වේ.', 'එය සංකෝචනය වීමේ දී බල පහර ශ්‍රේණියක් ඇති වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e64938e3-1b7b-4b16-a8db-34d2c6f57fe5', '76b04360-ee95-56ed-95c2-9692b229d280', 'ATP සහ $Ca^{2+}$ රහිත ව එයට සංකෝචනය වීමට නොහැකි ය.', 'ATP සහ $Ca^{2+}$ රහිත ව එයට සංකෝචනය වීමට නොහැකි ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('49460a1c-3019-4569-a473-15507d367c90', '76b04360-ee95-56ed-95c2-9692b229d280', 'එය සංකෝචනය වීමේ දී Z රේඛා දෙකක් අතර දුර කෙටි වේ.', 'එය සංකෝචනය වීමේ දී Z රේඛා දෙකක් අතර දුර කෙටි වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('458d95f8-8a99-57a5-8e57-fc8e41cf52c3', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 23, '<p>මිනිස් අංසඵලකය පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මිනිස් අංසඵලකය පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'මෙහි 4 සහ 5 යන ප්‍රකාශ දෙකම වැරදි වේ. (විභාග පිළිතුරු පත්‍රයේ පිළිතුරු 4 සහ 5 ලෙස දක්වා ඇත). ග්ලෙනොයිඩ කුහරය පිහිටන්නේ අංසඵලකයේ පාර්ශ්වික දාරයේ (lateral border) ය. එසේම තුණ්ඩාකාර ප්‍රසරය (coracoid process) ඉහළ දාරයෙන් පැන නොනගින අතර එය පැන නගින්නේ ග්ලෙනොයිඩ කුහරයේ ඉහළ දාරයට සම්බන්ධවය.', 'මෙහි 4 සහ 5 යන ප්‍රකාශ දෙකම වැරදි වේ. (විභාග පිළිතුරු පත්‍රයේ පිළිතුරු 4 සහ 5 ලෙස දක්වා ඇත). ග්ලෙනොයිඩ කුහරය පිහිටන්නේ අංසඵලකයේ පාර්ශ්වික දාරයේ (lateral border) ය. එසේම තුණ්ඩාකාර ප්‍රසරය (coracoid process) ඉහළ දාරයෙන් පැන නොනගින අතර එය පැන නගින්නේ ග්ලෙනොයිඩ කුහරයේ ඉහළ දාරයට සම්බන්ධවය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
