INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7d4adb8b-fcf9-4820-9a12-e369f6e36db6', '458d95f8-8a99-57a5-8e57-fc8e41cf52c3', 'තුණ්ඩාකාර ප්‍රසරය, එහි ඉහළ දාරයෙන් පැන නැඟුණු ප්‍රසරයකි.', 'තුණ්ඩාකාර ප්‍රසරය, එහි ඉහළ දාරයෙන් පැන නැඟුණු ප්‍රසරයකි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('278c11f0-4dc6-5524-9cb0-3cd5f6d5e1e1', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 24, '<p>මිනිසාගේ පහළ ගාත්‍රය පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මිනිසාගේ පහළ ගාත්‍රය පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'ඌර්වස්ථිය (Femur) දේහයේ මධ්‍ය රේඛාවට සමාන්තරව නොපිහිටයි. එය උකුල් සන්ධියේ සිට දණිස් සන්ධිය දෙසට පහළට සහ මධ්‍ය දෙසට ආනතව (obliquely downward and medially) පිහිටයි.', 'ඌර්වස්ථිය (Femur) දේහයේ මධ්‍ය රේඛාවට සමාන්තරව නොපිහිටයි. එය උකුල් සන්ධියේ සිට දණිස් සන්ධිය දෙසට පහළට සහ මධ්‍ය දෙසට ආනතව (obliquely downward and medially) පිහිටයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
