INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cc5e7e17-691a-46fd-bfb1-63100155983c', '278c11f0-4dc6-5524-9cb0-3cd5f6d5e1e1', 'එය අස්ථි 30කින් සමන්විත වේ.', 'එය අස්ථි 30කින් සමන්විත වේ.', NULL, 'sanitized', 'v1', 2, 0);
