INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('58a875cb-a670-436b-837e-4b9f5ea8a960', '278c11f0-4dc6-5524-9cb0-3cd5f6d5e1e1', 'පාදයේ අන්වායාම සහ හරස් වක්‍ර යන දෙක ම ඇත.', 'පාදයේ අන්වායාම සහ හරස් වක්‍ර යන දෙක ම ඇත.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0d066511-234f-5044-b4de-40e552c2218f', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 25, '<p>පුරුෂයන්ගේ ප්‍රජනනය පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>පුරුෂයන්ගේ ප්‍රජනනය පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'ශුක්‍ර ආශයිකා (Seminal vesicles) ස්‍රාවයෙහි ප්‍රධාන වශයෙන් අඩංගු වන්නේ ෆ්‍රක්ටෝස් (fructose), ප්‍රොස්ටග්ලැන්ඩින් සහ කැටි ගැසීමේ ප්‍රෝටීන වේ. එහි ග්ලූකෝස් අඩංගු නොවේ.', 'ශුක්‍ර ආශයිකා (Seminal vesicles) ස්‍රාවයෙහි ප්‍රධාන වශයෙන් අඩංගු වන්නේ ෆ්‍රක්ටෝස් (fructose), ප්‍රොස්ටග්ලැන්ඩින් සහ කැටි ගැසීමේ ප්‍රෝටීන වේ. එහි ග්ලූකෝස් අඩංගු නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
