INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d7913845-ebdd-435f-a024-61347e238084', 'c4f85095-fa7c-50eb-b839-adf79ec53381', 'වාහක ස්ත්‍රියක් හීමොෆීලියාවෙන් පෙළෙන පුරුෂයෙකු හා විවාහ වූ විට ඔවුන්ගේ පුතුන් සියල්ලෝ ම හිමොෆීලියාවෙන් පෙළෙන අය වෙති.', 'වාහක ස්ත්‍රියක් හීමොෆීලියාවෙන් පෙළෙන පුරුෂයෙකු හා විවාහ වූ විට ඔවුන්ගේ පුතුන් සියල්ලෝ ම හිමොෆීලියාවෙන් පෙළෙන අය වෙති.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('506daf32-3227-5995-8bb9-3c4721e52f1e', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 32, '<p>විවිධ ජීවී කාණ්ඩ සම්භවය වූ කාලය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් වැරදි වන්නේ කුමක්ද?</p>', '<p>විවිධ ජීවී කාණ්ඩ සම්භවය වූ කාලය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් වැරදි වන්නේ කුමක්ද?</p>', NULL, 'කේතුධර ශාක (Conifers) බහුලව සම්භවය වූයේ පේලියොසොයික (Paleozoic) යුගයේ අග භාගයේ (කාබනිෆෙරස් සහ පර්මියන් අවධි වල) ය. ඒවා මීසොසොයික යුගයේදී ප්‍රමුඛ ශාක බවට පත් විය.', 'කේතුධර ශාක (Conifers) බහුලව සම්භවය වූයේ පේලියොසොයික (Paleozoic) යුගයේ අග භාගයේ (කාබනිෆෙරස් සහ පර්මියන් අවධි වල) ය. ඒවා මීසොසොයික යුගයේදී ප්‍රමුඛ ශාක බවට පත් විය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
