INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('14cfe033-ea67-4a7f-b19c-c35609cf0836', '506daf32-3227-5995-8bb9-3c4721e52f1e', 'කලලබන්ධ ක්ෂීරපායීන් සම්භවය වූයේ ක්‍රිටේසීය අවධියේ දී ය.', 'කලලබන්ධ ක්ෂීරපායීන් සම්භවය වූයේ ක්‍රිටේසීය අවධියේ දී ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4b81ba75-e9f0-4850-bce7-a28d5397fba5', '506daf32-3227-5995-8bb9-3c4721e52f1e', 'කේතුධර ශාක ඇති වූයේ මීසොසොයික යුගයේ දී ය.', 'කේතුධර ශාක ඇති වූයේ මීසොසොයික යුගයේ දී ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0d3291cb-1f1a-5f82-b080-1eec8446f6f7', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 33, '<p>අවම උෂ්ණත්ව විචලතාවක් දක්වන්නේ පහත සඳහන් කුමන භෞමික බියෝමය ද?</p>', '<p>අවම උෂ්ණත්ව විචලතාවක් දක්වන්නේ පහත සඳහන් කුමන භෞමික බියෝමය ද?</p>', NULL, 'නිවර්තන වනාන්තර (Tropical forests) සමකයට ආසන්නව පිහිටන බැවින් වසර පුරා ඉහළ හා සාපේක්ෂව නියත උෂ්ණත්වයක් පවතී. එහි දෛනික සහ වාර්ෂික උෂ්ණත්ව විචලනය අවම වේ.', 'නිවර්තන වනාන්තර (Tropical forests) සමකයට ආසන්නව පිහිටන බැවින් වසර පුරා ඉහළ හා සාපේක්ෂව නියත උෂ්ණත්වයක් පවතී. එහි දෛනික සහ වාර්ෂික උෂ්ණත්ව විචලනය අවම වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
