INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d8e5a4f3-0b85-5c50-b12e-ab8fa35da775', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 35, '<p>මෙම ප්‍රශ්නය පහත සඳහන් විශේෂ මත පදනම් වේ.<br><br>A - Lantana camara<br>B - Puntius nigrofasciatus<br>C - Garcinia quaesita<br>D - Caretta caretta<br>E - Dermochelys coriacea<br>F - Elephas maximus<br><br>ඉහත දක්වා ඇති විශේෂ පිළිබඳ පහත දී ඇති ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>මෙම ප්‍රශ්නය පහත සඳහන් විශේෂ මත පදනම් වේ.<br><br>A - Lantana camara<br>B - Puntius nigrofasciatus<br>C - Garcinia quaesita<br>D - Caretta caretta<br>E - Dermochelys coriacea<br>F - Elephas maximus<br><br>ඉහත දක්වා ඇති විශේෂ පිළිබඳ පහත දී ඇති ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'Puntius nigrofasciatus (බුලත්හපයා) සහ Garcinia quaesita (ගොරකා) යන විශේෂ දෙක ශ්‍රී ලංකාවට ආවේණික (ඒක දේශීය - Endemic) විශේෂ වේ.', 'Puntius nigrofasciatus (බුලත්හපයා) සහ Garcinia quaesita (ගොරකා) යන විශේෂ දෙක ශ්‍රී ලංකාවට ආවේණික (ඒක දේශීය - Endemic) විශේෂ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
