INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0279ed4f-fb32-4fc6-a69c-d415ee6d687a', 'd8e5a4f3-0b85-5c50-b12e-ab8fa35da775', 'ඉහත දැක්වෙන එක් විශේෂයක් එහි මුල් භූමි සීමා තුළ නෂ්ට වී ඇත.', 'ඉහත දැක්වෙන එක් විශේෂයක් එහි මුල් භූමි සීමා තුළ නෂ්ට වී ඇත.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('15a3276f-5955-4c49-9007-a7b5231dbe79', 'd8e5a4f3-0b85-5c50-b12e-ab8fa35da775', 'ඉහත දැක්වෙන එක් විශේෂයක්වත් වඳ වී යෑමේ ඉහළ අවදානමක් ඇති කාණ්ඩයට ඇතුළත් නොවේ.', 'ඉහත දැක්වෙන එක් විශේෂයක්වත් වඳ වී යෑමේ ඉහළ අවදානමක් ඇති කාණ්ඩයට ඇතුළත් නොවේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9fa60c39-165c-55e5-9f11-a910d5eb79cb', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 36, '<p>ආහාර මගින් වැළඳෙන ආසාදන සිදු කරනු ලබන පහත සඳහන් කවර ජීවියෙකුගේ, අන්තඃධූලක අන්තර්ගත වේ ද?</p>', '<p>ආහාර මගින් වැළඳෙන ආසාදන සිදු කරනු ලබන පහත සඳහන් කවර ජීවියෙකුගේ, අන්තඃධූලක අන්තර්ගත වේ ද?</p>', NULL, 'Salmonella typhi යනු ග්‍රෑම් සෘණ බැක්ටීරියාවක් වන අතර, එහි සෛල බිත්තියේ පිටත පටලයේ ඇති ලයිපොපොලිසැකරයිඩ (LPS) අන්තඃධූලක (endotoxins) ලෙස ක්‍රියා කරයි. අනෙකුත් දක්වා ඇති බොහෝ බැක්ටීරියා බාහිර ධූලක (exotoxins) ශ්‍රාවය කරයි.', 'Salmonella typhi යනු ග්‍රෑම් සෘණ බැක්ටීරියාවක් වන අතර, එහි සෛල බිත්තියේ පිටත පටලයේ ඇති ලයිපොපොලිසැකරයිඩ (LPS) අන්තඃධූලක (endotoxins) ලෙස ක්‍රියා කරයි. අනෙකුත් දක්වා ඇති බොහෝ බැක්ටීරියා බාහිර ධූලක (exotoxins) ශ්‍රාවය කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
