INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d14f2275-ca60-49d3-8466-ca3a93546860', 'f5254731-0d11-5ddf-852d-62e645d246e9', 'තමන්ගේ ම න්‍යෂ්ටික අම්ල උපයෝගී කර ගනිමින් ඒවා ධාරක පටක තුළ දී ස්වයංප්‍රතිවලිත වේ.', 'තමන්ගේ ම න්‍යෂ්ටික අම්ල උපයෝගී කර ගනිමින් ඒවා ධාරක පටක තුළ දී ස්වයංප්‍රතිවලිත වේ.', NULL, 'sanitized', 'v1', 1, 0);
