INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7f7720fd-9660-47e7-b0e4-36104308ba5e', 'f5254731-0d11-5ddf-852d-62e645d246e9', 'ඒවා ක්ෂීරපායීන්ගේ මොළ පරිහානී මාරාන්තික රෝග ඇති කරයි.', 'ඒවා ක්ෂීරපායීන්ගේ මොළ පරිහානී මාරාන්තික රෝග ඇති කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('534a486f-5a17-4ab4-82ae-b9e2b5d51f92', 'f5254731-0d11-5ddf-852d-62e645d246e9', 'ඒවා මගින් ඇතිවන රෝග සත්ත්වයින්ගෙන් මිනිසාට සම්ප්‍රේෂණය විය හැකි ය.', 'ඒවා මගින් ඇතිවන රෝග සත්ත්වයින්ගෙන් මිනිසාට සම්ප්‍රේෂණය විය හැකි ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c1844b0f-9c64-5d1f-9e07-248685f74ac6', '64570ac7-1e13-58f5-a0b0-f0ebc96bddf1', 38, '<p>පහත සඳහන් කවරක් සක්‍රිය ප්‍රතිශක්තිකරණය සඳහා භාවිත කරනු ලබන, ජාන විකරණය කරනු ලැබූ එන්නතක්ද ?</p>', '<p>පහත සඳහන් කවරක් සක්‍රිය ප්‍රතිශක්තිකරණය සඳහා භාවිත කරනු ලබන, ජාන විකරණය කරනු ලැබූ එන්නතක්ද ?</p>', NULL, 'හෙපටයිටිස් B (Hepatitis B) එන්නත යනු පුනර්සංයෝජිත DNA තාක්ෂණය (ජාන විකරණය) මගින් යීස්ට් සෛල භාවිතයෙන් නිපදවන ලද නව පරම්පරාවේ එන්නතකි.', 'හෙපටයිටිස් B (Hepatitis B) එන්නත යනු පුනර්සංයෝජිත DNA තාක්ෂණය (ජාන විකරණය) මගින් යීස්ට් සෛල භාවිතයෙන් නිපදවන ලද නව පරම්පරාවේ එන්නතකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
