INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bb17d938-2e8c-4f1d-b999-22b7813525d0', '5e745ae0-5ad4-5d0c-9fdf-d00283794d1a', 'ක්ෂුද්‍ර සූත්‍රිකා, සෛල විභාජනයේදී වර්ණ දේහවල චලනය සඳහා සහභාගී වේ.', 'ක්ෂුද්‍ර සූත්‍රිකා, සෛල විභාජනයේදී වර්ණ දේහවල චලනය සඳහා සහභාගී වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f1161184-6032-4076-a1d4-b7a02f3d1cbd', '5e745ae0-5ad4-5d0c-9fdf-d00283794d1a', 'අතරමැදි සූත්‍රිකා, සෛලයෙන් ද්‍රව්‍ය ස්‍රාවය කිරීම සඳහා අවශ්‍ය මාර්ග සපයයි.', 'අතරමැදි සූත්‍රිකා, සෛලයෙන් ද්‍රව්‍ය ස්‍රාවය කිරීම සඳහා අවශ්‍ය මාර්ග සපයයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b4944362-d9fc-590a-82d4-7acfe7bf9beb', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 5, '<p>සෛල චක්‍රයේ</p>', '<p>සෛල චක්‍රයේ</p>', NULL, 'සෛල චක්‍රයේ $G_2$ කලාවේදී ප්‍රෝටීන සංශ්ලේෂණය සිදු වේ. DNA ප්‍රතිවලිත වීම සිදු වන්නේ $S$ කලාවේදී ය. තර්කුව තැනීම සහ ක්‍රොමැටින් ඝන වීම ආරම්භ වන්නේ ප්‍රථම කලාවේදී ය.', 'සෛල චක්‍රයේ $G_2$ කලාවේදී ප්‍රෝටීන සංශ්ලේෂණය සිදු වේ. DNA ප්‍රතිවලිත වීම සිදු වන්නේ $S$ කලාවේදී ය. තර්කුව තැනීම සහ ක්‍රොමැටින් ඝන වීම ආරම්භ වන්නේ ප්‍රථම කලාවේදී ය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
