INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0da54ff7-fa28-4148-8488-7a00676e5726', 'b4944362-d9fc-590a-82d4-7acfe7bf9beb', 'ක්‍රොමැටින් තන්තුවල ඝනවීම සිදු වන්නේ $S$ කලාවේදී ය.', 'ක්‍රොමැටින් තන්තුවල ඝනවීම සිදු වන්නේ $S$ කලාවේදී ය.', NULL, 'sanitized', 'v1', 3, 0);
