INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0307728a-fe40-52b2-9f45-402b69bf6199', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 6, '<p>ක්ලෝරොෆිල් පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>ක්ලෝරොෆිල් පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'ක්ලෝරොෆිල් වර්ණක මගින් ප්‍රධාන වශයෙන් ජම්බුල, නිල් සහ රතු ආලෝකය අවශෝෂණය කරන අතර කොළ ආලෝකය පරාවර්තනය කරයි. ප්‍රධාන ප්‍රභාසංස්ලේෂක වර්ණකය ක්ලෝරොෆිල් $a$ වේ.', 'ක්ලෝරොෆිල් වර්ණක මගින් ප්‍රධාන වශයෙන් ජම්බුල, නිල් සහ රතු ආලෝකය අවශෝෂණය කරන අතර කොළ ආලෝකය පරාවර්තනය කරයි. ප්‍රධාන ප්‍රභාසංස්ලේෂක වර්ණකය ක්ලෝරොෆිල් $a$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6cd9fb40-5684-48af-82b4-d302b91af0b3', '0307728a-fe40-52b2-9f45-402b69bf6199', 'ක්ලෝරොෆිල් ජම්බුල, නිල් සහ රතු ආලෝකය අවශෝෂණය කරයි.', 'ක්ලෝරොෆිල් ජම්බුල, නිල් සහ රතු ආලෝකය අවශෝෂණය කරයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3c1fd8d1-6b35-4c3f-a854-6c570afb30f6', '0307728a-fe40-52b2-9f45-402b69bf6199', 'ශාකවල ඇති ආලෝකය ග්‍රහණය කර ගන්නා ප්‍රධාන ම වර්ණකය ක්ලෝරොෆිල් - $b$ ය.', 'ශාකවල ඇති ආලෝකය ග්‍රහණය කර ගන්නා ප්‍රධාන ම වර්ණකය ක්ලෝරොෆිල් - $b$ ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5cd86381-2071-4359-8578-e3d223d0af65', '0307728a-fe40-52b2-9f45-402b69bf6199', 'ක්ලෝරොෆිල් - $a$ වඩාත් ම කාර්යක්ෂම වන්නේ කොළ ආලෝකය ග්‍රහණය කිරීම සඳහාය.', 'ක්ලෝරොෆිල් - $a$ වඩාත් ම කාර්යක්ෂම වන්නේ කොළ ආලෝකය ග්‍රහණය කිරීම සඳහාය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4f0a952a-c9a2-498b-a587-6fb80c2b3321', '0307728a-fe40-52b2-9f45-402b69bf6199', 'අධික ව ඇති ආලෝක ශක්තිය අවශෝෂණය කිරීම සහ විසුරුවා හැරීම සඳහා ක්ලෝරොෆිල් - $a$ සහභාගී වේ.', 'අධික ව ඇති ආලෝක ශක්තිය අවශෝෂණය කිරීම සහ විසුරුවා හැරීම සඳහා ක්ලෝරොෆිල් - $a$ සහභාගී වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d729f929-41fc-4af3-8294-f5c9bb243daa', '0307728a-fe40-52b2-9f45-402b69bf6199', 'ප්‍රභාපද්ධති - 1 හිදී, ක්ලෝරොෆිල් - $a$ අවශෝෂණය කරන්නේ $680 nm$ තරංග ආයාමයේ ආලෝකය යි.', 'ප්‍රභාපද්ධති - 1 හිදී, ක්ලෝරොෆිල් - $a$ අවශෝෂණය කරන්නේ $680 nm$ තරංග ආයාමයේ ආලෝකය යි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('15710d9b-7bf6-52ae-acce-60edcebe09fa', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 7, '<p>ඊතයිල් මධ්‍යසාර පැසීමේදී, ලැක්ටික් අම්ල පැසීමේදී සහ සවායු ශ්වසනයේදී නිපදවනු ලබන සංයෝගයක් වන්නේ</p>', '<p>ඊතයිල් මධ්‍යසාර පැසීමේදී, ලැක්ටික් අම්ල පැසීමේදී සහ සවායු ශ්වසනයේදී නිපදවනු ලබන සංයෝගයක් වන්නේ</p>', NULL, 'සවායු හා නිර්වායු ශ්වසන ආකාර දෙකෙහිම පොදු පළමු අදියර වන්නේ ග්ලයිකොලිසිස් ක්‍රියාවලියයි.<br>එහිදී අවසන් ඵලය ලෙස පයිරුවේට් නිපදවනු ලැබේ.', 'සවායු හා නිර්වායු ශ්වසන ආකාර දෙකෙහිම පොදු පළමු අදියර වන්නේ ග්ලයිකොලිසිස් ක්‍රියාවලියයි.<br>එහිදී අවසන් ඵලය ලෙස පයිරුවේට් නිපදවනු ලැබේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
