INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3e85c22a-c8f3-42f2-bad8-2301c59dee6b', '1c528e6c-00f4-5171-830f-0483c62250ab', 'ට්‍රිකෝම යනු විශේෂිත අපිචර්මීය සෛල වේ.', 'ට්‍රිකෝම යනු විශේෂිත අපිචර්මීය සෛල වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9e99faa8-3476-4c4d-840d-9b769ee9afb9', '1c528e6c-00f4-5171-830f-0483c62250ab', 'අපිචර්මීය සෛල තුළ සුබෙරින් තැන්පත්වීම නිසා ජල හානිය වළකී.', 'අපිචර්මීය සෛල තුළ සුබෙරින් තැන්පත්වීම නිසා ජල හානිය වළකී.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f65bf566-f81c-5603-b735-d609692bb140', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 13, '<p>කාර්යක්ෂම ප්‍රභාසංස්ලේෂණය සඳහා ශාකවල දක්නට ලැබෙන අනුවර්තන පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>කාර්යක්ෂම ප්‍රභාසංස්ලේෂණය සඳහා ශාකවල දක්නට ලැබෙන අනුවර්තන පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'ආලෝකය සඳහා තරඟ කරන ශාක, යාබද ශාක මගින් ඇතිවන සෙවන මඟහරවා ගනිමින් උපරිම ආලෝකයක් ලබා ගැනීම සඳහා උස්ව වර්ධනය වේ. වියළි පරිසරවල ජල හානිය අවම කිරීමට පත්‍ර කුඩා වන අතර, අධි තීව්‍ර ආලෝකය වළක්වා ගැනීමට පත්‍ර සිරස්ව පිහිටයි.', 'ආලෝකය සඳහා තරඟ කරන ශාක, යාබද ශාක මගින් ඇතිවන සෙවන මඟහරවා ගනිමින් උපරිම ආලෝකයක් ලබා ගැනීම සඳහා උස්ව වර්ධනය වේ. වියළි පරිසරවල ජල හානිය අවම කිරීමට පත්‍ර කුඩා වන අතර, අධි තීව්‍ර ආලෝකය වළක්වා ගැනීමට පත්‍ර සිරස්ව පිහිටයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('209fa0cb-60ed-487b-8675-4cef55056ad2', 'f65bf566-f81c-5603-b735-d609692bb140', 'ශාකවල අතු බෙදී ඇත්තේ වායු ගෝලයෙන් උපරිම කාබන් ඩයොක්සයිඩ් ප්‍රමාණයක් අවශෝෂණය කර ගැනීමට සුදුසු රටාවකටය.', 'ශාකවල අතු බෙදී ඇත්තේ වායු ගෝලයෙන් උපරිම කාබන් ඩයොක්සයිඩ් ප්‍රමාණයක් අවශෝෂණය කර ගැනීමට සුදුසු රටාවකටය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5f700ee0-536a-442c-bb62-a57ceceebfd8', 'f65bf566-f81c-5603-b735-d609692bb140', 'උපරිම ආලෝක ග්‍රහණයක් සඳහා වියළි පරිසරවල වැඩෙන ශාකවල විශාල පත්‍ර ඇත.', 'උපරිම ආලෝක ග්‍රහණයක් සඳහා වියළි පරිසරවල වැඩෙන ශාකවල විශාල පත්‍ර ඇත.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('64358743-ab03-4ed3-964d-f1b5b018adb4', 'f65bf566-f81c-5603-b735-d609692bb140', 'සමහර ශාකවල පත්‍ර බොහෝ දුරට සිරස් ආකාරයට පිහිටා ඇත්තේ උපරිම ආලෝක ප්‍රමාණයක් ලබා ගැනීම සඳහා ය.', 'සමහර ශාකවල පත්‍ර බොහෝ දුරට සිරස් ආකාරයට පිහිටා ඇත්තේ උපරිම ආලෝක ප්‍රමාණයක් ලබා ගැනීම සඳහා ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f4b3c083-5d53-4164-8a1f-5a89ca99e54f', 'f65bf566-f81c-5603-b735-d609692bb140', 'සමහර ශාකවල පත්‍ර තිරස් ලෙස සැකසී ඇත්තේ අධි තීව්‍ර ආලෝකයෙන් වන හානි වැළැක්වීම සඳහාය.', 'සමහර ශාකවල පත්‍ර තිරස් ලෙස සැකසී ඇත්තේ අධි තීව්‍ර ආලෝකයෙන් වන හානි වැළැක්වීම සඳහාය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bbb086a2-61fb-473c-83ff-ff6a59878b94', 'f65bf566-f81c-5603-b735-d609692bb140', 'යාබද ශාක මගින් ඇති වන සෙවන වළක්වා ගැනීම සඳහා ශාක උස්ව වැඩේ.', 'යාබද ශාක මගින් ඇති වන සෙවන වළක්වා ගැනීම සඳහා ශාක උස්ව වැඩේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4684c8bd-1d45-5fd9-91c0-8f406452d654', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 14, '<p>පූටිකා විවෘත වීමේදී</p>', '<p>පූටිකා විවෘත වීමේදී</p>', NULL, 'පූටිකා විවෘත වීමේදී පාලක සෛල තුළට පොටෑසියම් අයන ($K^+$) සක්‍රියව පොම්ප කෙරේ. මෙහි ප්‍රතිඵලයක් ලෙස පාලක සෛලවල ද්‍රාව්‍ය සාන්ද්‍රණය වැඩි වී ජල විභවය අඩුවේ. ඉන්පසු අවට සෛල වලින් ජලය පාලක සෛල තුළට ආස්‍රැතිය වී ඒවායේ ශූනතාව වැඩිවේ.', 'පූටිකා විවෘත වීමේදී පාලක සෛල තුළට පොටෑසියම් අයන ($K^+$) සක්‍රියව පොම්ප කෙරේ. මෙහි ප්‍රතිඵලයක් ලෙස පාලක සෛලවල ද්‍රාව්‍ය සාන්ද්‍රණය වැඩි වී ජල විභවය අඩුවේ. ඉන්පසු අවට සෛල වලින් ජලය පාලක සෛල තුළට ආස්‍රැතිය වී ඒවායේ ශූනතාව වැඩිවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4c89c079-e136-41c2-90be-41cab01114a1', '4684c8bd-1d45-5fd9-91c0-8f406452d654', 'පාලක සෛල තුළට සෝඩියම් අයන සක්‍රිය ලෙස පරිවහනය කෙරේ.', 'පාලක සෛල තුළට සෝඩියම් අයන සක්‍රිය ලෙස පරිවහනය කෙරේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('533c90a4-303a-4b5c-aad8-8ea4618d4dfd', '4684c8bd-1d45-5fd9-91c0-8f406452d654', 'පාලක සෛලවල ශූනතා පීඩනය අඩු වේ.', 'පාලක සෛලවල ශූනතා පීඩනය අඩු වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ea6a3b46-94f2-47d2-9552-7df502e428ee', '4684c8bd-1d45-5fd9-91c0-8f406452d654', 'අධඃපූටික කුටීරයේ කාබන් ඩයොක්සයිඩ් ප්‍රමාණය වැඩි වේ.', 'අධඃපූටික කුටීරයේ කාබන් ඩයොක්සයිඩ් ප්‍රමාණය වැඩි වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1502e257-f388-4b7b-b1b8-e6b770eb7686', '4684c8bd-1d45-5fd9-91c0-8f406452d654', 'පාලක සෛලවල ජල විභවය අඩු වේ.', 'පාලක සෛලවල ජල විභවය අඩු වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('efb9d888-e814-4685-be79-10ba419f32ff', '4684c8bd-1d45-5fd9-91c0-8f406452d654', 'පාලක සෛල තුළට පොටැසියම් අයන අක්‍රිය ලෙස පරිවහනය කෙරේ.', 'පාලක සෛල තුළට පොටැසියම් අයන අක්‍රිය ලෙස පරිවහනය කෙරේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('517073f3-2f6a-50ab-aac7-83c2b6fe7dfb', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 15, '<p>ශාකවල පෝෂණ අවශ්‍යතා පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>ශාකවල පෝෂණ අවශ්‍යතා පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'මොලිබ්ඩිනම් (Mo) නයිට්‍රජන් පරිවෘත්තිය සඳහා (විශේෂයෙන් නයිට්‍රජනේස් සහ නයිට්‍රේට් රිඩක්ටේස් එන්සයිමවල ක්‍රියාකාරිත්වයට) අත්‍යවශ්‍ය ක්ෂුද්‍ර පෝෂකයකි. යකඩ යනු ක්ෂුද්‍ර පෝෂකයකි. මැග්නීසියම් ක්ලෝරොෆිල් වල සංඝටකයකි.', 'මොලිබ්ඩිනම් (Mo) නයිට්‍රජන් පරිවෘත්තිය සඳහා (විශේෂයෙන් නයිට්‍රජනේස් සහ නයිට්‍රේට් රිඩක්ටේස් එන්සයිමවල ක්‍රියාකාරිත්වයට) අත්‍යවශ්‍ය ක්ෂුද්‍ර පෝෂකයකි. යකඩ යනු ක්ෂුද්‍ර පෝෂකයකි. මැග්නීසියම් ක්ලෝරොෆිල් වල සංඝටකයකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
