INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('57dc77f0-b694-4405-beb9-d00036764db4', '517073f3-2f6a-50ab-aac7-83c2b6fe7dfb', 'නයිට්‍රජන් ඌනතාව නිසා හරිතක්ෂය ඇති වන්නේ ප්‍රධාන වශයෙන්ම ළාබාල පත්‍රවල ය.', 'නයිට්‍රජන් ඌනතාව නිසා හරිතක්ෂය ඇති වන්නේ ප්‍රධාන වශයෙන්ම ළාබාල පත්‍රවල ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('04ea6a59-3f28-4f3b-ad81-3caa1ac998d0', '517073f3-2f6a-50ab-aac7-83c2b6fe7dfb', 'මොලිබ්ඩිනම්, නයිට්‍රජන් පරිවෘත්තිය සඳහා අවශ්‍ය ය.', 'මොලිබ්ඩිනම්, නයිට්‍රජන් පරිවෘත්තිය සඳහා අවශ්‍ය ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7c002b0e-8cf6-5988-b99d-5f63234b4c64', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 16, '<p>සියලු ම භෞමික ශාකවල ලිංගික ප්‍රජනනයේ දැකිය හැකි ලක්ෂණයක් වන්නේ</p>', '<p>සියලු ම භෞමික ශාකවල ලිංගික ප්‍රජනනයේ දැකිය හැකි ලක්ෂණයක් වන්නේ</p>', NULL, 'සියලුම භෞමික ශාක (බ්‍රයෝෆයිටා, ටෙරිඩෝෆයිටා, විවෘතබීජක, ආවෘතබීජක) වල ස්ත්‍රී ජන්මාණුව (ඩිම්බය) ජන්මාණු ශාකය හෝ අදාළ ව්‍යුහය තුළ රඳවා තබා ගන්නා අතර, සංසේචනය අභ්‍යන්තරව සිදුවේ. බ්‍රයෝෆයිටා සහ ටෙරිඩෝෆයිටා සඳහා බාහිර ජලය අවශ්‍ය වේ.', 'සියලුම භෞමික ශාක (බ්‍රයෝෆයිටා, ටෙරිඩෝෆයිටා, විවෘතබීජක, ආවෘතබීජක) වල ස්ත්‍රී ජන්මාණුව (ඩිම්බය) ජන්මාණු ශාකය හෝ අදාළ ව්‍යුහය තුළ රඳවා තබා ගන්නා අතර, සංසේචනය අභ්‍යන්තරව සිදුවේ. බ්‍රයෝෆයිටා සහ ටෙරිඩෝෆයිටා සඳහා බාහිර ජලය අවශ්‍ය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
