INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('82aa8bd2-2e6b-41b1-8d35-71978d1fa367', '7c002b0e-8cf6-5988-b99d-5f63234b4c64', 'බීජාණු ආකාර දෙකක් නිපදවීමයි.', 'බීජාණු ආකාර දෙකක් නිපදවීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a80ed001-dc61-4281-91bb-5001d6de429d', '7c002b0e-8cf6-5988-b99d-5f63234b4c64', 'බීජාණු ශාක ආකාර දෙකක් තිබීමයි.', 'බීජාණු ශාක ආකාර දෙකක් තිබීමයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6e4d5461-ac91-5396-a7a5-115116dc1c9f', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 17, '<p>ශාක ආලෝකයට දක්වන ප්‍රතිචාර පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>ශාක ආලෝකයට දක්වන ප්‍රතිචාර පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'ශාකවල ප්‍රධාන ප්‍රකාශ ප්‍රතිග්‍රාහක (photoreceptors) ආකාර දෙකක් ඇත. ඒවා නම් නිල් ආලෝක ප්‍රතිග්‍රාහක (blue-light photoreceptors) සහ ෆයිටොක්‍රෝම (phytochromes) වේ. ෆයිටොක්‍රෝම මගින් බීජ ප්‍රරෝහණය වැනි ක්‍රියාවලි යාමනය කරයි.', 'ශාකවල ප්‍රධාන ප්‍රකාශ ප්‍රතිග්‍රාහක (photoreceptors) ආකාර දෙකක් ඇත. ඒවා නම් නිල් ආලෝක ප්‍රතිග්‍රාහක (blue-light photoreceptors) සහ ෆයිටොක්‍රෝම (phytochromes) වේ. ෆයිටොක්‍රෝම මගින් බීජ ප්‍රරෝහණය වැනි ක්‍රියාවලි යාමනය කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
