INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6a03b2e9-1d63-4285-a007-9819b5cd1d61', '6e4d5461-ac91-5396-a7a5-115116dc1c9f', 'හිරු එළියට කෙලින්ම නිරාවරණය වීම, සිරස් වර්ධනය උත්තේජනය කරයි.', 'හිරු එළියට කෙලින්ම නිරාවරණය වීම, සිරස් වර්ධනය උත්තේජනය කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1fafa3e8-0d57-4b4c-90fe-c291208aa20c', '6e4d5461-ac91-5396-a7a5-115116dc1c9f', 'ප්‍රකාශ රූපජනනය යාමනය කිරීම සඳහා වඩාත් ම වැදගත් වන්නේ ආලෝකයේ කොළ සහ රතු වර්ණයි.', 'ප්‍රකාශ රූපජනනය යාමනය කිරීම සඳහා වඩාත් ම වැදගත් වන්නේ ආලෝකයේ කොළ සහ රතු වර්ණයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5e30248a-da9f-4642-ba3e-6a985d9e9cb0', '6e4d5461-ac91-5396-a7a5-115116dc1c9f', 'ධන ප්‍රභාවර්තනය සිදු වන්නේ ප්‍රරෝහයේ වඩාත් දීප්තිමත් පැත්තේ ඇති සෛල වඩාත් ශීඝ්‍ර ව දික්වීම නිසාය.', 'ධන ප්‍රභාවර්තනය සිදු වන්නේ ප්‍රරෝහයේ වඩාත් දීප්තිමත් පැත්තේ ඇති සෛල වඩාත් ශීඝ්‍ර ව දික්වීම නිසාය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9b8725c4-ad26-55c4-a615-08f7ab393095', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 18, '<p>සාමාන්‍ය තත්ත්ව යටතේදී තන්තු දක්නට නොලැබෙන සම්බන්ධක පටකය වන්නේ</p>', '<p>සාමාන්‍ය තත්ත්ව යටතේදී තන්තු දක්නට නොලැබෙන සම්බන්ධක පටකය වන්නේ</p>', NULL, 'රුධිරය යනු ද්‍රවමය පූරකයක් (රුධිර ප්ලාස්මාව) සහිත විශේෂිත සම්බන්ධක පටකයකි. සාමාන්‍ය තත්ත්ව යටතේ එහි තන්තු දක්නට නොලැබෙන අතර, රුධිරය කැටි ගැසීමේදී පමණක් ෆයිබ්‍රින් (fibrin) ප්‍රෝටීන තන්තු සෑදේ.', 'රුධිරය යනු ද්‍රවමය පූරකයක් (රුධිර ප්ලාස්මාව) සහිත විශේෂිත සම්බන්ධක පටකයකි. සාමාන්‍ය තත්ත්ව යටතේ එහි තන්තු දක්නට නොලැබෙන අතර, රුධිරය කැටි ගැසීමේදී පමණක් ෆයිබ්‍රින් (fibrin) ප්‍රෝටීන තන්තු සෑදේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
