INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('00d8b5a5-39f4-4537-9883-1ec077ea500a', '3f206834-673c-56b0-91ca-e398b0cf0eb0', 'තොග වශයෙන් බුදින්නන් - සූටික්කන්', 'තොග වශයෙන් බුදින්නන් - සූටික්කන්', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fc09149d-69ba-592c-b6cb-c0c71d6b7103', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 20, '<p>මිනිසාගේ ආහාරවල ඇති න්‍යෂ්ටික අම්ල ජිරණය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>මිනිසාගේ ආහාරවල ඇති න්‍යෂ්ටික අම්ල ජිරණය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'න්‍යෂ්ටික අම්ල ජීරණය ප්‍රධාන වශයෙන් කුඩා අන්ත්‍රයේදී සිදුවේ. අග්න්‍යාශයික යුෂයේ අඩංගු නියුක්ලියේස් (Nucleases) එන්සයිම මගින් DNA සහ RNA යන දෙකම නියුක්ලියොටයිඩ බවට බිඳ හෙළනු ලැබේ.', 'න්‍යෂ්ටික අම්ල ජීරණය ප්‍රධාන වශයෙන් කුඩා අන්ත්‍රයේදී සිදුවේ. අග්න්‍යාශයික යුෂයේ අඩංගු නියුක්ලියේස් (Nucleases) එන්සයිම මගින් DNA සහ RNA යන දෙකම නියුක්ලියොටයිඩ බවට බිඳ හෙළනු ලැබේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
