INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cd68d184-e30e-4d8d-ace1-579f8140748f', 'fc09149d-69ba-592c-b6cb-c0c71d6b7103', 'නයිට්‍රජනීය භෂ්ම ජීරණය කිරීම සඳහා නියුක්ලියොසයිඩේස් සහභාගි වේ.', 'නයිට්‍රජනීය භෂ්ම ජීරණය කිරීම සඳහා නියුක්ලියොසයිඩේස් සහභාගි වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d5d927ef-d8c7-4695-951d-be2d40233a1a', 'fc09149d-69ba-592c-b6cb-c0c71d6b7103', 'අග්න්‍යාශයික නියුක්ලියේස් මගින් RNA, නියුක්ලියොටයිඩ බවට බිඳ හෙළනු ලැබේ.', 'අග්න්‍යාශයික නියුක්ලියේස් මගින් RNA, නියුක්ලියොටයිඩ බවට බිඳ හෙළනු ලැබේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2f4e501c-ffbe-417b-8184-de2031b965c9', 'fc09149d-69ba-592c-b6cb-c0c71d6b7103', 'ආන්ත්‍රික නියුක්ලියොටයිඩේස්, නයිට්‍රජනීය භෂ්ම මත ක්‍රියා කරයි.', 'ආන්ත්‍රික නියුක්ලියොටයිඩේස්, නයිට්‍රජනීය භෂ්ම මත ක්‍රියා කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('61a17ff4-405a-513a-8e82-6a056f74ea01', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 21, '<p>මන්දාතතියේ ඵල විපාකයක් විය හැක්කේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', '<p>මන්දාතතියේ ඵල විපාකයක් විය හැක්කේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', NULL, 'මන්දාතතිය (Hypotension) හෙවත් අඩු රුධිර පීඩනය පවතින විට මොළයට ලැබෙන රුධිර සැපයුම අඩුවීම හේතුවෙන් සිහි මුර්ජා වීම (fainting) සිදුවිය හැක.', 'මන්දාතතිය (Hypotension) හෙවත් අඩු රුධිර පීඩනය පවතින විට මොළයට ලැබෙන රුධිර සැපයුම අඩුවීම හේතුවෙන් සිහි මුර්ජා වීම (fainting) සිදුවිය හැක.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
