INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c8822ec4-9928-4428-91f5-5e4aa3fca122', 'd63fcdb0-177c-5c7d-8c6c-3bdc0c586199', 'ඔක්සිටොසින් - කිරි නිපදවීම උත්තේජනය කිරීම', 'ඔක්සිටොසින් - කිරි නිපදවීම උත්තේජනය කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0dba491c-c314-4714-b1d2-e4e35ac8357e', 'd63fcdb0-177c-5c7d-8c6c-3bdc0c586199', 'පැරාතයිරොයිඩ හෝර්මෝනය - රුධිරයේ කැල්සියම් මට්ටම අඩු කිරීම', 'පැරාතයිරොයිඩ හෝර්මෝනය - රුධිරයේ කැල්සියම් මට්ටම අඩු කිරීම', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ec1c548d-f38e-550e-90e3-da7376237c5d', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 27, '<p>මිනිසාගේ ශුක්‍රාණු ජනනයේදී ද්විගුණ සිට ඒකගුණ දක්වා වර්ණදේහ සංඛ්‍යාව අඩු වන්නේ</p>', '<p>මිනිසාගේ ශුක්‍රාණු ජනනයේදී ද්විගුණ සිට ඒකගුණ දක්වා වර්ණදේහ සංඛ්‍යාව අඩු වන්නේ</p>', NULL, 'පළමු ඌනන විභාජනය (Meiosis I) සිදුවන්නේ ප්‍රාථමික ශුක්‍රාණු සෛල ($2n$) වලින් ද්විතීයික ශුක්‍රාණු සෛල ($n$) සෑදීමේදීය. මෙහිදී වර්ණදේහ සංඛ්‍යාව ද්විගුණ තත්ත්වයේ සිට ඒකගුණ තත්ත්වයට අඩුවේ.', 'පළමු ඌනන විභාජනය (Meiosis I) සිදුවන්නේ ප්‍රාථමික ශුක්‍රාණු සෛල ($2n$) වලින් ද්විතීයික ශුක්‍රාණු සෛල ($n$) සෑදීමේදීය. මෙහිදී වර්ණදේහ සංඛ්‍යාව ද්විගුණ තත්ත්වයේ සිට ඒකගුණ තත්ත්වයට අඩුවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('03916e56-576f-496c-a9a2-c25dd96f350f', 'ec1c548d-f38e-550e-90e3-da7376237c5d', 'ප්‍රාක්ශුක්‍ර වලින් ශුක්‍රාණු නිපදවීමේදී ය.', 'ප්‍රාක්ශුක්‍ර වලින් ශුක්‍රාණු නිපදවීමේදී ය.', NULL, 'sanitized', 'v1', 0, 1);
