INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('202d526d-644a-48da-8753-a14bd3958143', 'ec1c548d-f38e-550e-90e3-da7376237c5d', 'ප්‍රාථමික ශුක්‍රාණු සෛලවලින් ද්විතීයික ශුක්‍රාණු සෛල නිපද වීමේදී ය.', 'ප්‍රාථමික ශුක්‍රාණු සෛලවලින් ද්විතීයික ශුක්‍රාණු සෛල නිපද වීමේදී ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('66449371-817a-43b6-a7fe-c215de7306b7', 'ec1c548d-f38e-550e-90e3-da7376237c5d', 'මූලික ජන්මාණු සෛලවලින් ශුක්‍රාණු මාතෘ සෛල නිපදවීමේදී ය.', 'මූලික ජන්මාණු සෛලවලින් ශුක්‍රාණු මාතෘ සෛල නිපදවීමේදී ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5aba9a0f-5001-488d-bb39-583b37c11fe9', 'ec1c548d-f38e-550e-90e3-da7376237c5d', 'ශුක්‍රාණුමාතෘ සෛලවලින් ප්‍රාථමික ශුක්‍රාණු සෛල නිපදවීමේදී ය.', 'ශුක්‍රාණුමාතෘ සෛලවලින් ප්‍රාථමික ශුක්‍රාණු සෛල නිපදවීමේදී ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fc29f3bb-10e9-5f0a-9b97-22460082b63c', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 28, '<p>මෙම ප්‍රශ්නය පදනම් වී ඇත්තේ පරිණත කාන්තාවන්ගේ සාමාන්‍ය ප්‍රජනක චක්‍රයේදී පූර්ව පිටියුටරියෙන් සහ ඩිම්බ කෝෂයෙන් ස්‍රාවය වන හෝමෝන වල රුධිරගත මට්ටම දැක්වෙන පහත දී ඇති රූප සටහන මත ය.<br><br>A, B, C සහ D වලින් දැක්වෙන හෝර්මෝන පිළිවෙළින්</p>', '<p>මෙම ප්‍රශ්නය පදනම් වී ඇත්තේ පරිණත කාන්තාවන්ගේ සාමාන්‍ය ප්‍රජනක චක්‍රයේදී පූර්ව පිටියුටරියෙන් සහ ඩිම්බ කෝෂයෙන් ස්‍රාවය වන හෝමෝන වල රුධිරගත මට්ටම දැක්වෙන පහත දී ඇති රූප සටහන මත ය.<br><br>A, B, C සහ D වලින් දැක්වෙන හෝර්මෝන පිළිවෙළින්</p>', NULL, 'ආර්තව චක්‍රයේ 14 වන දිනයේදී පමණ තියුණු ලෙස ඉහළ යන්නේ ලුටිනීකරණ හෝමෝනයයි (LH - A). ඩිම්බ මෝචනයට පෙර ඊස්ට්‍රජන් හෙවත් ඊස්ට්‍රඩියොල් (B) මට්ටම ඉහළ යන අතර, ඉන්පසු කෝපස් ලුටියම මගින් ප්‍රොජෙස්ටෙරෝන් (C) ශ්‍රාවය කරයි. D මගින් FSH නිරූපණය වේ.', 'ආර්තව චක්‍රයේ 14 වන දිනයේදී පමණ තියුණු ලෙස ඉහළ යන්නේ ලුටිනීකරණ හෝමෝනයයි (LH - A). ඩිම්බ මෝචනයට පෙර ඊස්ට්‍රජන් හෙවත් ඊස්ට්‍රඩියොල් (B) මට්ටම ඉහළ යන අතර, ඉන්පසු කෝපස් ලුටියම මගින් ප්‍රොජෙස්ටෙරෝන් (C) ශ්‍රාවය කරයි. D මගින් FSH නිරූපණය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
