INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1b67eec4-f3e2-4e20-b773-14c4b066f004', 'fc29f3bb-10e9-5f0a-9b97-22460082b63c', 'FSH, LH, ප්‍රොජෙස්ටරොන් සහ ඊස්ට්‍රඩියොල් වේ.', 'FSH, LH, ප්‍රොජෙස්ටරොන් සහ ඊස්ට්‍රඩියොල් වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3779afb6-955f-50be-91b2-8f78af9656a9', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 29, '<p>මානව සැකිලි පද්ධතිය පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මානව සැකිලි පද්ධතිය පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'ලකුණු දීමේ පටිපාටියට අනුව මෙම ප්‍රශ්නයට කුමන පිළිතුරක් සැපයුවද ලකුණු ලබා දී ඇත (All marks given). මන්දයත් මෙහි ඇති සියලුම ප්‍රකාශවල සුළු හෝ තාක්ෂණික දෝෂ පවතින බැවිනි. ද්විතීයික වක්‍ර වන්නේ ග්‍රීව හා කටී වක්‍ර වන අතර උරස් සහ ත්‍රිකාස්ථික වක්‍ර ප්‍රාථමික වේ.', 'ලකුණු දීමේ පටිපාටියට අනුව මෙම ප්‍රශ්නයට කුමන පිළිතුරක් සැපයුවද ලකුණු ලබා දී ඇත (All marks given). මන්දයත් මෙහි ඇති සියලුම ප්‍රකාශවල සුළු හෝ තාක්ෂණික දෝෂ පවතින බැවිනි. ද්විතීයික වක්‍ර වන්නේ ග්‍රීව හා කටී වක්‍ර වන අතර උරස් සහ ත්‍රිකාස්ථික වක්‍ර ප්‍රාථමික වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2fb25e4d-82ba-4519-9f19-312269df6446', '3779afb6-955f-50be-91b2-8f78af9656a9', 'අරාස්ථිය, අන්වරාස්ථිය සහ ප්‍රගන්ඩාස්ථිය මගින් තැනී ඇති වැලමිටි සන්ධිය නිසා පූර්ව බාහුවේ සමිංජනය සහ නිකුබ්ජනය පමණක් සිදු කළ හැකිය.', 'අරාස්ථිය, අන්වරාස්ථිය සහ ප්‍රගන්ඩාස්ථිය මගින් තැනී ඇති වැලමිටි සන්ධිය නිසා පූර්ව බාහුවේ සමිංජනය සහ නිකුබ්ජනය පමණක් සිදු කළ හැකිය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c0111b28-7081-4933-ac6c-abc406d1d075', '3779afb6-955f-50be-91b2-8f78af9656a9', 'ඌර්වස්ථිය, අනුජංඝාස්ථිය සහ දණිස් කටුව මගින් තැනෙන අසව් සන්ධිය නිසා වැඩි වේලාවක් සෘජු ව සිටගෙන සිටීමට පුළුවන.', 'ඌර්වස්ථිය, අනුජංඝාස්ථිය සහ දණිස් කටුව මගින් තැනෙන අසව් සන්ධිය නිසා වැඩි වේලාවක් සෘජු ව සිටගෙන සිටීමට පුළුවන.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('74c91e3d-5ff5-48e8-89c6-0da8f511b30e', '3779afb6-955f-50be-91b2-8f78af9656a9', 'පාදයේ වක්‍ර, සිටගෙන සිටීමේදී පමණක් දේහ බර ව්‍යාප්ත කිරීම සඳහා වැදගත් වේ.', 'පාදයේ වක්‍ර, සිටගෙන සිටීමේදී පමණක් දේහ බර ව්‍යාප්ත කිරීම සඳහා වැදගත් වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('26b58638-53d6-466d-a84c-489b0df2955d', '3779afb6-955f-50be-91b2-8f78af9656a9', 'කශේරුවේ උරස් සහ ත්‍රිකාස්ථික ප්‍රදේශ වල ඇති ද්වීතීයික වක්‍ර, සෘජු ඉරියව්ව පවත්වා ගැනීම සඳහා උපකාරී වේ.', 'කශේරුවේ උරස් සහ ත්‍රිකාස්ථික ප්‍රදේශ වල ඇති ද්වීතීයික වක්‍ර, සෘජු ඉරියව්ව පවත්වා ගැනීම සඳහා උපකාරී වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f12a347b-3113-46a5-9bf0-bb954321fdee', '3779afb6-955f-50be-91b2-8f78af9656a9', 'ඔස්ටියොපොරෝසිස් ලෙස හඳුන්වනු ලබන ප්‍රදාහක නොවන පරිහානී රෝගය නිසා ආසාදිත සන්ධි වල වේදනාව ඇති වන අතර ඒවායේ චලනය ද සීමාකාරී වේ.', 'ඔස්ටියොපොරෝසිස් ලෙස හඳුන්වනු ලබන ප්‍රදාහක නොවන පරිහානී රෝගය නිසා ආසාදිත සන්ධි වල වේදනාව ඇති වන අතර ඒවායේ චලනය ද සීමාකාරී වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('11ff9d70-03f4-54a4-b3ae-a65ccb044858', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 30, '<p>මිනිසාගේ දෑකැති සෛල රක්තහීනතාව නිදසුනක් වන්නේ,</p>', '<p>මිනිසාගේ දෑකැති සෛල රක්තහීනතාව නිදසුනක් වන්නේ,</p>', NULL, 'දෑකැති සෛල රක්තහීනතාවය (Sickle cell anemia) යනු එක් විකෘති ජානයක් මගින් දේහයේ රූපානුදර්ශී ලක්ෂණ සහ ආබාධ කිහිපයක්ම ඇති කරන බැවින් එය බහුකාර්යතාවට (Pleiotropy) කදිම නිදසුනකි.', 'දෑකැති සෛල රක්තහීනතාවය (Sickle cell anemia) යනු එක් විකෘති ජානයක් මගින් දේහයේ රූපානුදර්ශී ලක්ෂණ සහ ආබාධ කිහිපයක්ම ඇති කරන බැවින් එය බහුකාර්යතාවට (Pleiotropy) කදිම නිදසුනකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('69b78af9-da19-487a-be0e-c514cd042111', '11ff9d70-03f4-54a4-b3ae-a65ccb044858', 'විෂමයෝගී ප්‍රමුඛතාව සඳහාය.', 'විෂමයෝගී ප්‍රමුඛතාව සඳහාය.', NULL, 'sanitized', 'v1', 0, 1);
