INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('af807f00-e68a-4a10-a659-5f0ddce1f4ba', '11ff9d70-03f4-54a4-b3ae-a65ccb044858', 'අපිජාන ප්‍රවේණිය (epigenetics) සඳහා ය.', 'අපිජාන ප්‍රවේණිය (epigenetics) සඳහා ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('92b51399-dc25-565b-89c9-be9483a04bd0', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 31, '<p>$Rr \times Rr$ මුහුම පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>$Rr \times Rr$ මුහුම පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'ඒකගුණ මුහුමක ($Rr \times Rr$) $F_2$ පරම්පරාවේ රූපානුදර්ශ අනුපාතය $1:2:1$ වීම මගින් අසම්පූර්ණ ප්‍රමුඛතාව හෝ සහප්‍රමුඛතාව (Codominance) නිරූපණය වේ.', 'ඒකගුණ මුහුමක ($Rr \times Rr$) $F_2$ පරම්පරාවේ රූපානුදර්ශ අනුපාතය $1:2:1$ වීම මගින් අසම්පූර්ණ ප්‍රමුඛතාව හෝ සහප්‍රමුඛතාව (Codominance) නිරූපණය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('00c747b1-4ae4-4af4-ae5f-128fa677f7c4', '92b51399-dc25-565b-89c9-be9483a04bd0', 'සංසේචනයේදී ඩිම්බය සහ ශුක්‍රාණුව යන දෙකෙහි ම $r$ ඇලීලය තිබීමේ සම්භාවිතාව $\frac{1}{2}$ කි.', 'සංසේචනයේදී ඩිම්බය සහ ශුක්‍රාණුව යන දෙකෙහි ම $r$ ඇලීලය තිබීමේ සම්භාවිතාව $\frac{1}{2}$ කි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('dac00a95-666e-4c71-9200-a8fae6d2c05f', '92b51399-dc25-565b-89c9-be9483a04bd0', 'ඇලීල දෙකක් සහභාගි වන බැවින් මෙය ව්‍යංග මුහුමකි.', 'ඇලීල දෙකක් සහභාගි වන බැවින් මෙය ව්‍යංග මුහුමකි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a9a43e43-de59-4120-907d-835841ffd75f', '92b51399-dc25-565b-89c9-be9483a04bd0', 'මෙන්ඩලීය ප්‍රවේණියට අනුව $F_1$ පරම්පරාවේ අන්තරාභිජනනයෙන් ලැබෙන $F_2$ පරම්පරාවේ ප්‍රමුඛ රූපානුදර්ශය තිබීමේ සම්භාවිතාව $\frac{9}{16}$ කි.', 'මෙන්ඩලීය ප්‍රවේණියට අනුව $F_1$ පරම්පරාවේ අන්තරාභිජනනයෙන් ලැබෙන $F_2$ පරම්පරාවේ ප්‍රමුඛ රූපානුදර්ශය තිබීමේ සම්භාවිතාව $\frac{9}{16}$ කි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('afeaffe8-f44e-4261-ab38-fb22ed86b198', '92b51399-dc25-565b-89c9-be9483a04bd0', '$F_1$ පරම්පරාවේ අන්තරාභිජනනයෙන් ලැබුණු $F_2$ පරම්පරාවේ රූපානුදර්ශ අනුපාතය $1:2:1$ නම් එය සහප්‍රමුඛතාව නිසා විය හැකි ය.', '$F_1$ පරම්පරාවේ අන්තරාභිජනනයෙන් ලැබුණු $F_2$ පරම්පරාවේ රූපානුදර්ශ අනුපාතය $1:2:1$ නම් එය සහප්‍රමුඛතාව නිසා විය හැකි ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2a460825-f966-4567-af5a-70987fb07381', '92b51399-dc25-565b-89c9-be9483a04bd0', '$R$ සහ $r$ ප්‍රතිබද්ධය.', '$R$ සහ $r$ ප්‍රතිබද්ධය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e1b9787f-cb2f-51fa-8f29-a66e1aee03b8', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 32, '<p>කිසියම් පුද්ගලයකුගේ ජන්මාණු ජනනයේදී වර්ණ දේහ 24ක් සහිත ජන්මාණුවක් ඇති වූ අතර එය සාමාන්‍ය ජන්මාණුවක් සමග සංසේචනය වී දරුවෙකු බිහි විය. මෙම ක්‍රියාවලිය සහ එහි ප්‍රතිඵලය හොඳින් ම පැහැදිලි කෙරෙනුයේ පහත සඳහන් කුමක් මගින්ද?</p>', '<p>කිසියම් පුද්ගලයකුගේ ජන්මාණු ජනනයේදී වර්ණ දේහ 24ක් සහිත ජන්මාණුවක් ඇති වූ අතර එය සාමාන්‍ය ජන්මාණුවක් සමග සංසේචනය වී දරුවෙකු බිහි විය. මෙම ක්‍රියාවලිය සහ එහි ප්‍රතිඵලය හොඳින් ම පැහැදිලි කෙරෙනුයේ පහත සඳහන් කුමක් මගින්ද?</p>', NULL, 'අසාමාන්‍ය ජන්මාණුව (වර්ණදේහ 24) සාමාන්‍ය ජන්මාණුවක් (වර්ණදේහ 23) සමඟ සංසේචනය වූ විට වර්ණදේහ 47ක් සහිත යුක්තාණුවක් සෑදේ. මෙය විෂම ගුණකතාවට (Aneuploidy) අයත් ත්‍රිදේහතාවකි (Trisomy). ඩවුන් සහලක්ෂණය යනු මෙලෙස ඇතිවන ත්‍රිදේහතාවකට නිදසුනකි.', 'අසාමාන්‍ය ජන්මාණුව (වර්ණදේහ 24) සාමාන්‍ය ජන්මාණුවක් (වර්ණදේහ 23) සමඟ සංසේචනය වූ විට වර්ණදේහ 47ක් සහිත යුක්තාණුවක් සෑදේ. මෙය විෂම ගුණකතාවට (Aneuploidy) අයත් ත්‍රිදේහතාවකි (Trisomy). ඩවුන් සහලක්ෂණය යනු මෙලෙස ඇතිවන ත්‍රිදේහතාවකට නිදසුනකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('232bced7-5b61-430f-9921-708e4ba4b0ea', 'e1b9787f-cb2f-51fa-8f29-a66e1aee03b8', 'විෂම ගුණකතාව, ත්‍රි දේහතාව, ඩවුන් සහලක්ෂණය', 'විෂම ගුණකතාව, ත්‍රි දේහතාව, ඩවුන් සහලක්ෂණය', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fee752fd-70be-4d4c-b75a-b8bb03205cb4', 'e1b9787f-cb2f-51fa-8f29-a66e1aee03b8', 'බහුගුණකතාව, ත්‍රිදේහතාව, ක්ලයින්ෆෙල්ටර් සහලක්ෂණය', 'බහුගුණකතාව, ත්‍රිදේහතාව, ක්ලයින්ෆෙල්ටර් සහලක්ෂණය', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9c63bad6-e0de-4f12-a7a2-8dbefa234f29', 'e1b9787f-cb2f-51fa-8f29-a66e1aee03b8', 'විෂම ගුණකතාව, ඒක දේහතාව, ඩවුන් සහලක්ෂණය', 'විෂම ගුණකතාව, ඒක දේහතාව, ඩවුන් සහලක්ෂණය', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b9808c9e-714c-460a-bb32-975915684bf0', 'e1b9787f-cb2f-51fa-8f29-a66e1aee03b8', 'විෂම ගුණකතාව, ඒක දේහතාව, ක්ලයින්ෆෙල්ටර් සහලක්ෂණය', 'විෂම ගුණකතාව, ඒක දේහතාව, ක්ලයින්ෆෙල්ටර් සහලක්ෂණය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('96b3d700-b293-4ba5-bda2-5d5dfb1d1509', 'e1b9787f-cb2f-51fa-8f29-a66e1aee03b8', 'බහුගුණකතාව, ත්‍රිදේහතාව, ඩවුන් සහලක්ෂණය', 'බහුගුණකතාව, ත්‍රිදේහතාව, ඩවුන් සහලක්ෂණය', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('023e403a-f0c4-5360-996c-14f791dc071c', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 33, '<p>DNA ප්‍රතිවලිත වීමේදී ජානයක තයිමීන් අණුවක් වෙනුවට සයිටොසීන් අණුවක් එකතු විය. විකෘති වූ මෙම ජානය මගින්, විකෘති වීමට පෙර එය මගින් නිපදවනු ලැබූ පෙප්ටයිඩයේ ඇමයිනෝ අම්ල අනුපිළිවෙළ ම සහිත පෙප්ටයිඩයක් නිපදවනු ලැබීය. මෙය</p>', '<p>DNA ප්‍රතිවලිත වීමේදී ජානයක තයිමීන් අණුවක් වෙනුවට සයිටොසීන් අණුවක් එකතු විය. විකෘති වූ මෙම ජානය මගින්, විකෘති වීමට පෙර එය මගින් නිපදවනු ලැබූ පෙප්ටයිඩයේ ඇමයිනෝ අම්ල අනුපිළිවෙළ ම සහිත පෙප්ටයිඩයක් නිපදවනු ලැබීය. මෙය</p>', NULL, 'එක් නයිට්‍රජනීය භෂ්මයක් වෙනුවට තවත් භෂ්මයක් එකතු වීම ආදේශනයකි (Substitution). එමගින් නිපදවෙන ඇමයිනෝ අම්ල අනුපිළිවෙළ වෙනස් නොවුණි නම් එය නිශ්ශබ්ද විකෘතියකි (Silent mutation).', 'එක් නයිට්‍රජනීය භෂ්මයක් වෙනුවට තවත් භෂ්මයක් එකතු වීම ආදේශනයකි (Substitution). එමගින් නිපදවෙන ඇමයිනෝ අම්ල අනුපිළිවෙළ වෙනස් නොවුණි නම් එය නිශ්ශබ්ද විකෘතියකි (Silent mutation).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5f37c577-d013-4981-9b57-074c86c47df3', '023e403a-f0c4-5360-996c-14f791dc071c', 'නිවේශනයට සහ නිරර්ථක (nonsense) විකෘතියකට නිදසුනකි.', 'නිවේශනයට සහ නිරර්ථක (nonsense) විකෘතියකට නිදසුනකි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ad6f7d66-5b49-43ea-83d4-ccc623305805', '023e403a-f0c4-5360-996c-14f791dc071c', 'ආදේශනයට සහ නිශ්ශබ්ද විකෘතියකට නිදසුනකි.', 'ආදේශනයට සහ නිශ්ශබ්ද විකෘතියකට නිදසුනකි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('43f4876b-c6f2-4467-aaa6-5471036444a9', '023e403a-f0c4-5360-996c-14f791dc071c', 'නිවේශනයට සහ නිශ්ශබ්ද විකෘතියකට නිදසුනකි.', 'නිවේශනයට සහ නිශ්ශබ්ද විකෘතියකට නිදසුනකි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2cd817d8-5f43-457e-be10-e9460b23bddc', '023e403a-f0c4-5360-996c-14f791dc071c', 'ආදේශනයට සහ අපගතාර්ථක (missense) විකෘතියකට නිදසුනකි.', 'ආදේශනයට සහ අපගතාර්ථක (missense) විකෘතියකට නිදසුනකි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('799c520b-99f7-4e2b-bfce-5395b4c4c390', '023e403a-f0c4-5360-996c-14f791dc071c', 'නිවේශනයට සහ අපගතාර්ථක විකෘතියකට නිදසුනකි.', 'නිවේශනයට සහ අපගතාර්ථක විකෘතියකට නිදසුනකි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('bc1282a4-ef5c-5a79-8516-df90d4337f8a', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 34, '<p>PCR සඳහා තාපකාමී බැක්ටීරියා වලින් ලබාගත් DNA පොලිමරේස් භාවිත කරනු ලබන්නේ</p>', '<p>PCR සඳහා තාපකාමී බැක්ටීරියා වලින් ලබාගත් DNA පොලිමරේස් භාවිත කරනු ලබන්නේ</p>', NULL, 'PCR ක්‍රියාවලියේදී DNA දාම වෙන් කිරීමට අධික උෂ්ණත්වයක් ($90^\circ C - 95^\circ C$) අවශ්‍ය වේ. තාපකාමී බැක්ටීරියාවලින් ලබාගන්නා Taq පොලිමරේස් වැනි එන්සයිම මෙම ඉහළ උෂ්ණත්වයේදී වුවද අක්‍රිය නොවන බැවින් (තාප ස්ථායී බැවින්) ඒවා භාවිතා කරයි.', 'PCR ක්‍රියාවලියේදී DNA දාම වෙන් කිරීමට අධික උෂ්ණත්වයක් ($90^\circ C - 95^\circ C$) අවශ්‍ය වේ. තාපකාමී බැක්ටීරියාවලින් ලබාගන්නා Taq පොලිමරේස් වැනි එන්සයිම මෙම ඉහළ උෂ්ණත්වයේදී වුවද අක්‍රිය නොවන බැවින් (තාප ස්ථායී බැවින්) ඒවා භාවිතා කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f53f3f1c-35b5-45bd-8298-c2c53b09a2f0', 'bc1282a4-ef5c-5a79-8516-df90d4337f8a', 'වෙනත් ජීවීන්ට වඩා ඔවුන්ගේ DNA පොලිමරේස් ඇති බැවිනි.', 'වෙනත් ජීවීන්ට වඩා ඔවුන්ගේ DNA පොලිමරේස් ඇති බැවිනි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2a82bb22-8b11-4bba-9ada-df23ad7f444a', 'bc1282a4-ef5c-5a79-8516-df90d4337f8a', 'එම DNA පොලිමරේස්වලට සෝදුපත් කියවීමේ හැකියාව නැති බැවිනි.', 'එම DNA පොලිමරේස්වලට සෝදුපත් කියවීමේ හැකියාව නැති බැවිනි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4452daee-3da6-4499-bc8e-e21b64c698d7', 'bc1282a4-ef5c-5a79-8516-df90d4337f8a', 'පරීක්ෂණාගාරයේදී DNA දාම වෙන් කිරීම සඳහා අවශ්‍ය ඉහළ උෂ්ණත්වයේදී එම DNA පොලිමරේස් ස්ථායි බැවිනි.', 'පරීක්ෂණාගාරයේදී DNA දාම වෙන් කිරීම සඳහා අවශ්‍ය ඉහළ උෂ්ණත්වයේදී එම DNA පොලිමරේස් ස්ථායි බැවිනි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5f1c5d1f-1f90-4989-8cff-b2b2c4b8d382', 'bc1282a4-ef5c-5a79-8516-df90d4337f8a', 'පරීක්ෂණාගාරයේදී DNA පිටපත් කිරීමේ හැකියාව ඇති එකම පොලිමරේස් එය බැවිනි.', 'පරීක්ෂණාගාරයේදී DNA පිටපත් කිරීමේ හැකියාව ඇති එකම පොලිමරේස් එය බැවිනි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d04560a2-a22f-45d9-92a1-e2bc3479abd2', 'bc1282a4-ef5c-5a79-8516-df90d4337f8a', 'DNA සංශ්ලේෂණ ආරම්භ කිරීම සඳහා එම DNA පොලිමරේස්වලට මූලිකයක් අවශ්‍ය නොවන බැවිනි.', 'DNA සංශ්ලේෂණ ආරම්භ කිරීම සඳහා එම DNA පොලිමරේස්වලට මූලිකයක් අවශ්‍ය නොවන බැවිනි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b711e41f-7073-5d46-b26c-12594ff4a2b4', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 35, '<p>DNA ඛණ්ඩයක් ප්ලාස්මීය වාහකයෙකු තුළට ඇතුලු කළ හැක්කේ</p>', '<p>DNA ඛණ්ඩයක් ප්ලාස්මීය වාහකයෙකු තුළට ඇතුලු කළ හැක්කේ</p>', NULL, 'ලකුණු දීමේ පටිපාටියට අනුව මෙහි ඕනෑම පිළිතුරක් (All marks given) සඳහා ලකුණු ලබා දී ඇත. කෙසේ වුවද වඩාත්ම නිවැරදි ප්‍රායෝගික ක්‍රමවේදය වන්නේ වාහකයා කැපීමට භාවිත කළ සීමා එන්සයිමය (Restriction enzyme) මගින්ම අදාළ DNA ඛණ්ඩයත් කැපීමයි. එවිට ගැළපෙන ඇලෙන සුළු අන්ත සෑදේ.', 'ලකුණු දීමේ පටිපාටියට අනුව මෙහි ඕනෑම පිළිතුරක් (All marks given) සඳහා ලකුණු ලබා දී ඇත. කෙසේ වුවද වඩාත්ම නිවැරදි ප්‍රායෝගික ක්‍රමවේදය වන්නේ වාහකයා කැපීමට භාවිත කළ සීමා එන්සයිමය (Restriction enzyme) මගින්ම අදාළ DNA ඛණ්ඩයත් කැපීමයි. එවිට ගැළපෙන ඇලෙන සුළු අන්ත සෑදේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('907578e9-30b5-439f-9c5a-a8d67e13ffd6', 'b711e41f-7073-5d46-b26c-12594ff4a2b4', 'එම වාහකයාගේ නියුක්ලියොඩයිඩ අනුපිළිවෙළට සර්වසම නියුක්ලියොටයිඩ අනුපිළිවෙළක් එයට ඇති විට ය.', 'එම වාහකයාගේ නියුක්ලියොඩයිඩ අනුපිළිවෙළට සර්වසම නියුක්ලියොටයිඩ අනුපිළිවෙළක් එයට ඇති විට ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d5d29d76-9eea-4fca-a762-eb366fb81819', 'b711e41f-7073-5d46-b26c-12594ff4a2b4', 'වාහකයා කැපීමට භාවිත කළ සීමා එන්සයිමය මගින් ම එයත් කපා ඇති විට ය.', 'වාහකයා කැපීමට භාවිත කළ සීමා එන්සයිමය මගින් ම එයත් කපා ඇති විට ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e56ba17c-fa04-491c-a308-811fc0be52c6', 'b711e41f-7073-5d46-b26c-12594ff4a2b4', 'එය සහ වාහකයා එකම සෛල වර්ගයෙන් සම්භවය වී ඇති විටය.', 'එය සහ වාහකයා එකම සෛල වර්ගයෙන් සම්භවය වී ඇති විටය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('619b61f2-249e-486a-a4cb-347054cff19a', 'b711e41f-7073-5d46-b26c-12594ff4a2b4', 'එය සහ වාහකයා එකම දිගින් යුක්ත වූ විට ය.', 'එය සහ වාහකයා එකම දිගින් යුක්ත වූ විට ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2218df02-e6cd-46a3-8ae4-de2b357b87c4', 'b711e41f-7073-5d46-b26c-12594ff4a2b4', 'එයට අවම වශයෙන් එක් ප්‍රතිවලිත ආරම්භයක් (Ori) ඇති විට ය.', 'එයට අවම වශයෙන් එක් ප්‍රතිවලිත ආරම්භයක් (Ori) ඇති විට ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fa014fe8-f284-5f08-9077-b46131a44e4a', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 36, '<p>ශ්‍රී ලංකාවේ වියළි පතන තණ බිම් ඇත්තේ,</p>', '<p>ශ්‍රී ලංකාවේ වියළි පතන තණ බිම් ඇත්තේ,</p>', NULL, 'ලකුණු දීමේ පටිපාටියේ මෙම ප්‍රශ්නයට පිළිතුරක් දක්වා නොමැත (සියලුම සිසුන්ට ලකුණු ලබා දී තිබිය හැක). සාමාන්‍යයෙන් වියළි පතන ප්‍රධාන වශයෙන් අතරමැදි කලාපයේ (ඌව ද්‍රෝණියේ) ව්‍යාප්ත වී පවතී.', 'ලකුණු දීමේ පටිපාටියේ මෙම ප්‍රශ්නයට පිළිතුරක් දක්වා නොමැත (සියලුම සිසුන්ට ලකුණු ලබා දී තිබිය හැක). සාමාන්‍යයෙන් වියළි පතන ප්‍රධාන වශයෙන් අතරමැදි කලාපයේ (ඌව ද්‍රෝණියේ) ව්‍යාප්ත වී පවතී.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9102c56e-b57a-48bd-9351-beeb38ee8163', 'fa014fe8-f284-5f08-9077-b46131a44e4a', 'අතරමැදි සහ තෙත් කලාපවලය.', 'අතරමැදි සහ තෙත් කලාපවලය.', NULL, 'sanitized', 'v1', 0, 1);
