INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('823f59b9-9aee-4872-b5f0-fc6821a4246f', 'fa014fe8-f284-5f08-9077-b46131a44e4a', 'වියළි සහ ශුෂ්ක කලාපවල ය.', 'වියළි සහ ශුෂ්ක කලාපවල ය.', NULL, 'sanitized', 'v1', 2, 0);
