INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('184da21b-cadf-4951-bb6c-e86270ad9eb3', 'b1ce01d9-cf91-5a31-af79-9676fcda7291', 'දිලීර සඳහා වූ රෝපණ මාධ්‍ය සෑදීමට සාමාන්‍යයෙන් ග්ලූකෝස් භාවිත කෙරේ.', 'දිලීර සඳහා වූ රෝපණ මාධ්‍ය සෑදීමට සාමාන්‍යයෙන් ග්ලූකෝස් භාවිත කෙරේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('13e18d1a-3ec1-4a59-bf60-c6a1a1223f2f', 'b1ce01d9-cf91-5a31-af79-9676fcda7291', 'බැක්ටීරියා සඳහා වූ රෝපණ මාධ්‍ය සාදනු ලබන්නේ අර්තාපල් භාවිත කිරීමෙනි.', 'බැක්ටීරියා සඳහා වූ රෝපණ මාධ්‍ය සාදනු ලබන්නේ අර්තාපල් භාවිත කිරීමෙනි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('924157c5-db06-4962-9191-1222dabb66f4', 'b1ce01d9-cf91-5a31-af79-9676fcda7291', 'ඕනෑම ක්ෂුද්‍රජීවියෙකු රෝපණ මාධ්‍යයක වගා කළ හැකි ය.', 'ඕනෑම ක්ෂුද්‍රජීවියෙකු රෝපණ මාධ්‍යයක වගා කළ හැකි ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e15e4eb2-c260-4132-b98d-814425e9641d', 'b1ce01d9-cf91-5a31-af79-9676fcda7291', 'සියලු ම රෝපණ මාධ්‍ය වලට සාමාන්‍යයෙන් සෝඩියම් ක්ලෝරයිඩ් එකතු කරනු ලැබේ.', 'සියලු ම රෝපණ මාධ්‍ය වලට සාමාන්‍යයෙන් සෝඩියම් ක්ලෝරයිඩ් එකතු කරනු ලැබේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('acc478ce-d85d-56c7-9148-b79b65e2752e', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 40, '<p>ගංගාවකින් ලබා ගත් ජල සාම්පලයක කෝලිෆෝම් බැක්ටීරියා සිටින බව අනාවරණය කර ගන්නා ලදී. එම ගංගාවෙන් පිරියම් නොකළ ජලය පානය කිරීම නිසා වැළදිය හැකි රෝගයක් නොවන්නේ,</p>', '<p>ගංගාවකින් ලබා ගත් ජල සාම්පලයක කෝලිෆෝම් බැක්ටීරියා සිටින බව අනාවරණය කර ගන්නා ලදී. එම ගංගාවෙන් පිරියම් නොකළ ජලය පානය කිරීම නිසා වැළදිය හැකි රෝගයක් නොවන්නේ,</p>', NULL, 'කෝලිෆෝම් බැක්ටීරියා (Coliform bacteria) ජලයේ සිටීමෙන් ජලය මළ ද්‍රව්‍ය මගින් දූෂණය වී ඇති බව පෙන්නුම් කරයි. උණසන්නිපාතය, කොළරාව, අතීසාරය සහ පැරාටයිෆොයිඩ් යනු අපිරිසිදු ජලයෙන් බෝවන රෝග වේ. පිටගැස්ම (Tetanus) යනු පසෙහි සිටින බැක්ටීරියාවක් මගින් තුවාල හරහා බෝවන රෝගයකි.', 'කෝලිෆෝම් බැක්ටීරියා (Coliform bacteria) ජලයේ සිටීමෙන් ජලය මළ ද්‍රව්‍ය මගින් දූෂණය වී ඇති බව පෙන්නුම් කරයි. උණසන්නිපාතය, කොළරාව, අතීසාරය සහ පැරාටයිෆොයිඩ් යනු අපිරිසිදු ජලයෙන් බෝවන රෝග වේ. පිටගැස්ම (Tetanus) යනු පසෙහි සිටින බැක්ටීරියාවක් මගින් තුවාල හරහා බෝවන රෝගයකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
