INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7b464e0e-9c81-4d5a-b138-c6e6b4dc70a1', 'fb5482dd-4e3d-52f4-8ed0-d79389a0e813', 'වෙනත් කිසියම් ප්‍රතිචාරයක් හෝ ප්‍රතිචාර සංයෝජනයක් හෝ නිවැරදි ය.', 'වෙනත් කිසියම් ප්‍රතිචාරයක් හෝ ප්‍රතිචාර සංයෝජනයක් හෝ නිවැරදි ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('db49aa01-bc48-51af-b38b-27afc775ed50', '648a7157-1448-5f18-bf6c-71e3dc39a19c', 49, '<p>කර්මාන්ත සඳහා ක්ෂුද්‍රජීවීන් භාවිත කිරීම පිළිබඳ නිවැරදි සංකලනය/සංකලන තෝරන්න.<br><br>නිෂ්පාදිත ද්‍රව්‍යය - නිෂ්පාදනය සඳහා භාවිත කරනු ලබන ක්ෂුද්‍රජීවියා<br>(A) යෝගට් - Lactobacillus bulgaricus<br>(B) විනාකිරි - Gluconobacter sp.<br>(C) සිට්රික් අම්ලය - Spirulina sp.<br>(D) ලයිපේස් - Rhizopus sp.<br>(E) විටමින් C - Aspergillus oryzae</p>', '<p>කර්මාන්ත සඳහා ක්ෂුද්‍රජීවීන් භාවිත කිරීම පිළිබඳ නිවැරදි සංකලනය/සංකලන තෝරන්න.<br><br>නිෂ්පාදිත ද්‍රව්‍යය - නිෂ්පාදනය සඳහා භාවිත කරනු ලබන ක්ෂුද්‍රජීවියා<br>(A) යෝගට් - Lactobacillus bulgaricus<br>(B) විනාකිරි - Gluconobacter sp.<br>(C) සිට්රික් අම්ලය - Spirulina sp.<br>(D) ලයිපේස් - Rhizopus sp.<br>(E) විටමින් C - Aspergillus oryzae</p>', NULL, 'යෝගට් නිෂ්පාදනයට Lactobacillus bulgaricus ද, විනාකිරි සඳහා Gluconobacter ද, ලයිපේස් එන්සයිම නිපදවීමට Rhizopus දිලීරය ද යොදා ගනී. සිට්‍රික් අම්ලය නිපදවන්නේ Aspergillus niger මගිනි.', 'යෝගට් නිෂ්පාදනයට Lactobacillus bulgaricus ද, විනාකිරි සඳහා Gluconobacter ද, ලයිපේස් එන්සයිම නිපදවීමට Rhizopus දිලීරය ද යොදා ගනී. සිට්‍රික් අම්ලය නිපදවන්නේ Aspergillus niger මගිනි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
