INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('855e63f6-c076-50b6-b6a2-582fe64b1078', '66add217-8e3a-5bd6-b85b-cd8b2ccee07f', 12, '<p>''වෙජ්ජසාලා'' යනු කුමක්ද ?</p>', '<p>''වෙජ්ජසාලා'' යනු කුමක්ද ?</p>', NULL, '''වෙජ්ජ'' යනු වෛද්‍ය යන්නයි. ''වෙජ්ජසාලා'' (Vejjasala) යනු පුරාණ ලංකාවේ රෝගීන්ට ප්‍රතිකාර කිරීම සඳහා ඉදිකළ ආරෝග්‍යශාලා හෙවත් රෝහල් වේ.', '''වෙජ්ජ'' යනු වෛද්‍ය යන්නයි. ''වෙජ්ජසාලා'' (Vejjasala) යනු පුරාණ ලංකාවේ රෝගීන්ට ප්‍රතිකාර කිරීම සඳහා ඉදිකළ ආරෝග්‍යශාලා හෙවත් රෝහල් වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
