INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ec0db18b-d32b-42a8-b990-198d7ab1bcd8', '7f31be7f-bc03-5328-9912-5253c9b223d4', 'සිදුරු සහිත ගල් පතුරේ ඝනකම අඩු කිරීම ය.', 'සිදුරු සහිත ගල් පතුරේ ඝනකම අඩු කිරීම ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('668d523b-d684-56d3-9931-c9d61d5800fa', '66add217-8e3a-5bd6-b85b-cd8b2ccee07f', 18, '<p>අතීතයේ ශ්‍රී ලංකාව හා පැවැති විදේශ වෙළෙඳ ගනුදෙනුවල දී භාවිත කළ කාසි පිළිබඳ නිවැරදි ප්‍රකාශය කුමක්ද?</p>', '<p>අතීතයේ ශ්‍රී ලංකාව හා පැවැති විදේශ වෙළෙඳ ගනුදෙනුවල දී භාවිත කළ කාසි පිළිබඳ නිවැරදි ප්‍රකාශය කුමක්ද?</p>', NULL, 'මෙරටින් හමුවන රෝම, චීන, හා අරාබි කාසි මගින් තහවුරු වන්නේ අතීතයේ දී විදේශීය කාසි වල අඩංගු ලෝහයේ වටිනාකම මත ඕනෑම රටකට අයත් කාසි මෙරට වෙළඳ ගනුදෙනු සඳහා පිළිගත් බවයි.', 'මෙරටින් හමුවන රෝම, චීන, හා අරාබි කාසි මගින් තහවුරු වන්නේ අතීතයේ දී විදේශීය කාසි වල අඩංගු ලෝහයේ වටිනාකම මත ඕනෑම රටකට අයත් කාසි මෙරට වෙළඳ ගනුදෙනු සඳහා පිළිගත් බවයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2ccbcae2-6bf8-49be-a602-e2bb9e59c951', '668d523b-d684-56d3-9931-c9d61d5800fa', 'සෑම කාසියක්ම එකම ලෝහයකින් සාදා තිබීම', 'සෑම කාසියක්ම එකම ලෝහයකින් සාදා තිබීම', NULL, 'sanitized', 'v1', 0, 1);
