INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1979be4a-4e28-5481-98f8-7e5213905f9f', '66add217-8e3a-5bd6-b85b-cd8b2ccee07f', 23, '<p>පෘතුගීසීන් හා යාපනේ පාලකයන් අතර නිරතුරුව ගැටුම් ඇතිවීම කෙරෙහි බලපෑ ප්‍රධානතම හේතුව වූයේ,</p>', '<p>පෘතුගීසීන් හා යාපනේ පාලකයන් අතර නිරතුරුව ගැටුම් ඇතිවීම කෙරෙහි බලපෑ ප්‍රධානතම හේතුව වූයේ,</p>', NULL, 'මන්නාරම් බොක්ක ආශ්‍රිත මුතු කිමිදීමේ ලාභදායී කර්මාන්තයේ ආධිපත්‍යය පෘතුගීසීන්ට අවශ්‍ය වූ අතර, යාපනයේ ආර්යචක්‍රවර්තී රජවරුන් ඊට එරෙහි වීම ඔවුන් අතර ඇති වූ මූලික ආර්ථික හා දේශපාලනික ගැටුමට ප්‍රධාන හේතුව විය.', 'මන්නාරම් බොක්ක ආශ්‍රිත මුතු කිමිදීමේ ලාභදායී කර්මාන්තයේ ආධිපත්‍යය පෘතුගීසීන්ට අවශ්‍ය වූ අතර, යාපනයේ ආර්යචක්‍රවර්තී රජවරුන් ඊට එරෙහි වීම ඔවුන් අතර ඇති වූ මූලික ආර්ථික හා දේශපාලනික ගැටුමට ප්‍රධාන හේතුව විය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('48d85a4b-f290-48b4-9c2b-81843531f79d', '1979be4a-4e28-5481-98f8-7e5213905f9f', 'පහතරට සිංහල පාලකයන්ගේ පෘතුගීසි විරෝධි සටන් වලට යාපනේ පාලකයන් සහාය දැක්වීමයි.', 'පහතරට සිංහල පාලකයන්ගේ පෘතුගීසි විරෝධි සටන් වලට යාපනේ පාලකයන් සහාය දැක්වීමයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7ee6079c-ff4d-43e2-a6df-e2213ee0369e', '1979be4a-4e28-5481-98f8-7e5213905f9f', 'මන්නාරම් මුහුදේ මුතු කිමිදීමේ කටයුතු වල දී යාපනේ පාලකයන්ගෙන් පෘතුගීසීන්ට බාධා එල්ල වීමයි.', 'මන්නාරම් මුහුදේ මුතු කිමිදීමේ කටයුතු වල දී යාපනේ පාලකයන්ගෙන් පෘතුගීසීන්ට බාධා එල්ල වීමයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c617289c-fd0d-43ea-a1f5-ecea8f623323', '1979be4a-4e28-5481-98f8-7e5213905f9f', 'යාපනේ සිංහාසනයට උරුමකම් කියූ ඇතැම් ද්‍රවිඩ කුමාරවරුන් පෘතුගීසීන්ට පක්ෂව කටයුතු කිරීමයි.', 'යාපනේ සිංහාසනයට උරුමකම් කියූ ඇතැම් ද්‍රවිඩ කුමාරවරුන් පෘතුගීසීන්ට පක්ෂව කටයුතු කිරීමයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3d9a6245-284c-4133-b945-3ebbecae908e', '1979be4a-4e28-5481-98f8-7e5213905f9f', 'යාපනය රාජධානියේ කතෝලික ආගම ප්‍රචාරය කිරීමට එරෙහිව එහි පාලකයන්ගෙන් දැඩි විරෝධතා එල්ල වීමයි.', 'යාපනය රාජධානියේ කතෝලික ආගම ප්‍රචාරය කිරීමට එරෙහිව එහි පාලකයන්ගෙන් දැඩි විරෝධතා එල්ල වීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e67bf63d-a2c8-5e39-983d-5f484d2a649c', '66add217-8e3a-5bd6-b85b-cd8b2ccee07f', 24, '<p>මධ්‍යතන යුගයේ දී ආසියානු වෙළෙඳ ඒකාධිකාරය හිමි වූයේ,</p>', '<p>මධ්‍යතන යුගයේ දී ආසියානු වෙළෙඳ ඒකාධිකාරය හිමි වූයේ,</p>', NULL, 'මධ්‍යතන යුගයේ (Middle Ages) ඉන්දියන් සාගරයේ සහ ආසියානු වෙළෙඳාමේ ඒකාධිකාරය මුස්ලිම් හෙවත් අරාබි වෙළෙඳුන් සතුව පැවතිණි. පෘතුගීසීන් පෙරදිගට පැමිණියේ මෙම ඒකාධිකාරය බිඳ දැමීම සඳහාය.', 'මධ්‍යතන යුගයේ (Middle Ages) ඉන්දියන් සාගරයේ සහ ආසියානු වෙළෙඳාමේ ඒකාධිකාරය මුස්ලිම් හෙවත් අරාබි වෙළෙඳුන් සතුව පැවතිණි. පෘතුගීසීන් පෙරදිගට පැමිණියේ මෙම ඒකාධිකාරය බිඳ දැමීම සඳහාය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
