INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('86bec126-16b9-4e77-9427-7e4a2c438ff1', '23c61b8c-d26f-5c94-84eb-4ae2222acf99', 'අස්වැන්නෙන් කොටසක් බදු වශයෙන් ගෙවීමට සිදු වූ නිසාය.', 'අස්වැන්නෙන් කොටසක් බදු වශයෙන් ගෙවීමට සිදු වූ නිසාය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b3b35a2a-40cc-5966-b89d-fdf227a6838c', '66add217-8e3a-5bd6-b85b-cd8b2ccee07f', 39, '<p>"මේ අවස්ථාවේ අප බලය අල්ලා නොගතහොත් ඉතිහාසය අපට සමාව නොදෙනු ඇත." මෙම ප්‍රකාශය කිනම් විප්ලවයක් හා සම්බන්ධ වේ ද?</p>', '<p>"මේ අවස්ථාවේ අප බලය අල්ලා නොගතහොත් ඉතිහාසය අපට සමාව නොදෙනු ඇත." මෙම ප්‍රකාශය කිනම් විප්ලවයක් හා සම්බන්ධ වේ ද?</p>', NULL, 'මෙම ප්‍රකාශය රුසියානු විප්ලවයේ නායක ව්ලැදිමීර් ලෙනින් විසින් 1917 ඔක්තෝබර් විප්ලවයට ආසන්න දිනවලදී සිය බොල්ෂෙවික් පාක්ෂිකයින් දිරිමත් කිරීම සඳහා කරන ලද්දකි.', 'මෙම ප්‍රකාශය රුසියානු විප්ලවයේ නායක ව්ලැදිමීර් ලෙනින් විසින් 1917 ඔක්තෝබර් විප්ලවයට ආසන්න දිනවලදී සිය බොල්ෂෙවික් පාක්ෂිකයින් දිරිමත් කිරීම සඳහා කරන ලද්දකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
