INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('21a3312b-539f-5d69-ba47-5456b7b732b4', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 3, '<p>ATP අවශ්‍ය වන්නේ පහත සඳහන් කුමන ජෛවරසායනික ක්‍රියාවලිය සඳහා ද?</p>', '<p>ATP අවශ්‍ය වන්නේ පහත සඳහන් කුමන ජෛවරසායනික ක්‍රියාවලිය සඳහා ද?</p>', NULL, '$C_4$ ශාක වල පත්‍ර මධ්‍ය සෛල තුළදී පයිරුවේට් (Pyruvate) නැවත පොස්පොඊනෝල් පයිරුවේට් (PEP) බවට පරිවර්තනය වීමේදී ATP අණු වැය වේ.', '$C_4$ ශාක වල පත්‍ර මධ්‍ය සෛල තුළදී පයිරුවේට් (Pyruvate) නැවත පොස්පොඊනෝල් පයිරුවේට් (PEP) බවට පරිවර්තනය වීමේදී ATP අණු වැය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d7caf588-9328-4735-aaab-0714655fa5d8', '21a3312b-539f-5d69-ba47-5456b7b732b4', 'ප්‍රභාසංශ්ලේෂණයේදී ජලය ප්‍රභාවිච්ඡේදනය වීම', 'ප්‍රභාසංශ්ලේෂණයේදී ජලය ප්‍රභාවිච්ඡේදනය වීම', NULL, 'sanitized', 'v1', 0, 1);
