INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('021c9101-684b-4e5e-8903-817dfdd2a6a3', '21a3312b-539f-5d69-ba47-5456b7b732b4', 'කැල්වින් චක්‍රයේදී කාබන් ඩයොක්සයිඩ් අණුවක් RuBP සමග සම්බන්ධ වීම', 'කැල්වින් චක්‍රයේදී කාබන් ඩයොක්සයිඩ් අණුවක් RuBP සමග සම්බන්ධ වීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('695bde1d-d7c6-4754-a478-5de050ddc852', '21a3312b-539f-5d69-ba47-5456b7b732b4', '$C_4$ මාර්ගයේදී පයිරුවේට, PEP බවට පරිවර්තනය වීම', '$C_4$ මාර්ගයේදී පයිරුවේට, PEP බවට පරිවර්තනය වීම', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ff4e33b2-b480-51e0-87e3-726df7f7b726', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 4, '<p>ජීවී දේහ වල අඩංගු මූලද්‍රව්‍ය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>ජීවී දේහ වල අඩංගු මූලද්‍රව්‍ය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'විවිධ ජීවීන්ගේ දේහ තුළ අන්තර්ගත මූලද්‍රව්‍යවල සංයුතිය ජීවියාගෙන් ජීවියාට මෙන්ම පටකයෙන් පටකයට ද වෙනස් වන බැවින් එය නියත නොවේ.', 'විවිධ ජීවීන්ගේ දේහ තුළ අන්තර්ගත මූලද්‍රව්‍යවල සංයුතිය ජීවියාගෙන් ජීවියාට මෙන්ම පටකයෙන් පටකයට ද වෙනස් වන බැවින් එය නියත නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
