INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5461a6d7-1419-4a6c-8781-0028061bf74a', 'ff4e33b2-b480-51e0-87e3-726df7f7b726', 'ජීවීන්ගේ වියළි බරින් 0.1% කට වඩා අඩුවෙන් ඇති මූල ද්‍රව්‍ය අංශුමාත්‍ර මූලද්‍රව්‍ය ලෙස සැලකේ.', 'ජීවීන්ගේ වියළි බරින් 0.1% කට වඩා අඩුවෙන් ඇති මූල ද්‍රව්‍ය අංශුමාත්‍ර මූලද්‍රව්‍ය ලෙස සැලකේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('55285183-72f7-4ae0-8514-3ac1b3d98669', 'ff4e33b2-b480-51e0-87e3-726df7f7b726', 'යකඩ සියලු ම ජීවීන් තුළ දක්නට ලැබෙන අධි මාත්‍ර මූල ද්‍රව්‍යයකට නිදසුනකි.', 'යකඩ සියලු ම ජීවීන් තුළ දක්නට ලැබෙන අධි මාත්‍ර මූල ද්‍රව්‍යයකට නිදසුනකි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b6cf294b-c2bc-4538-ac70-e023bc591dc7', 'ff4e33b2-b480-51e0-87e3-726df7f7b726', 'ජීවී දේහ තුළ වඩාත්ම බහුල මුල ද්‍රව්‍ය හය වන්නේ කාබන්, හයිඩ්‍රජන්, ඔක්සිජන්, නයිට්‍රජන්, ෆොස්පරස් සහ මැග්නීසියම් ය.', 'ජීවී දේහ තුළ වඩාත්ම බහුල මුල ද්‍රව්‍ය හය වන්නේ කාබන්, හයිඩ්‍රජන්, ඔක්සිජන්, නයිට්‍රජන්, ෆොස්පරස් සහ මැග්නීසියම් ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('087a13bc-e51d-5bcf-aef1-c53beb0caf82', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 5, '<p>ශක්තිමත් ආසක්ත සහ සංසක්ත බල තිබීම ජල අණු වල වැදගත් භෞතික ගුණාංගයකි. එම ගුණාංගය සමග සම්බන්ධයක් නොදක්වන්නේ ශාකවල පහත සඳහන් කුමන කෘත්‍යය ද?</p>', '<p>ශක්තිමත් ආසක්ත සහ සංසක්ත බල තිබීම ජල අණු වල වැදගත් භෞතික ගුණාංගයකි. එම ගුණාංගය සමග සම්බන්ධයක් නොදක්වන්නේ ශාකවල පහත සඳහන් කුමන කෘත්‍යය ද?</p>', NULL, 'ජලය හොඳ ද්‍රාවකයක් ලෙස ක්‍රියා කිරීම (ද්‍රව්‍ය ද්‍රවණය වීම) ජල අණු වල ධ්‍රැවීය ස්වභාවය නිසා සිදුවන්නක් වන අතර, එයට ආසක්ත සහ සංසක්ත බල ඍජුවම දායක නොවේ.', 'ජලය හොඳ ද්‍රාවකයක් ලෙස ක්‍රියා කිරීම (ද්‍රව්‍ය ද්‍රවණය වීම) ජල අණු වල ධ්‍රැවීය ස්වභාවය නිසා සිදුවන්නක් වන අතර, එයට ආසක්ත සහ සංසක්ත බල ඍජුවම දායක නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
