INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d3433abc-4f6a-4eba-ae52-a7b117d7ae49', '087a13bc-e51d-5bcf-aef1-c53beb0caf82', 'ප්‍රාක්ප්ලාස්මය තුළ ද්‍රව්‍ය ද්‍රවණය වීම', 'ප්‍රාක්ප්ලාස්මය තුළ ද්‍රව්‍ය ද්‍රවණය වීම', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c30fd1ad-e26a-521b-8b60-a138aceabcf6', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 6, '<p>පහත සඳහන් කුමන ප්‍රතිචාරයේ දක්වා ඇති සියලුම ලක්ෂණ ත්‍රි අංක පුෂ්ප කොටස් සහිත ශාකයක දක්නට ලැබේ ද?</p>', '<p>පහත සඳහන් කුමන ප්‍රතිචාරයේ දක්වා ඇති සියලුම ලක්ෂණ ත්‍රි අංක පුෂ්ප කොටස් සහිත ශාකයක දක්නට ලැබේ ද?</p>', NULL, 'ත්‍රි අංක පුෂ්ප කොටස් දැකිය හැක්කේ ඒකබීජපත්‍රී ශාකවලය. ඒවායේ බීජ ඵල තුළ පිහිටන අතර (ආවෘතබීජක), ප්‍රමුඛ බීජාණු ශාකයක් ඇත. යුකැරියෝටාවන් බැවින් RNA පොලිමරේස් වර්ග කීපයක් දරන අතර කඳේ සනාල කලාප විසිරී පවතී.', 'ත්‍රි අංක පුෂ්ප කොටස් දැකිය හැක්කේ ඒකබීජපත්‍රී ශාකවලය. ඒවායේ බීජ ඵල තුළ පිහිටන අතර (ආවෘතබීජක), ප්‍රමුඛ බීජාණු ශාකයක් ඇත. යුකැරියෝටාවන් බැවින් RNA පොලිමරේස් වර්ග කීපයක් දරන අතර කඳේ සනාල කලාප විසිරී පවතී.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('18b57e2f-9529-4d31-b103-f2e0422ce1d3', 'c30fd1ad-e26a-521b-8b60-a138aceabcf6', 'පත්‍රවල සමාන්තර නාරටි, බීජපත්‍ර එකක් සහිත කලල, තන්තු මුල්, සෛල පටලයේ ශාඛනය වූ ලිපිඩ', 'පත්‍රවල සමාන්තර නාරටි, බීජපත්‍ර එකක් සහිත කලල, තන්තු මුල්, සෛල පටලයේ ශාඛනය වූ ලිපිඩ', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7dfa380c-91ae-4863-8557-64a40b02fe7c', 'c30fd1ad-e26a-521b-8b60-a138aceabcf6', 'ඵල තුළ පිහිටන බීජ, ප්‍රමුඛ බීජාණුශාකය, RNA පොලිමරේස් වර්ග කීපයක්, කඳේ සනාල කලාප විසිරී තිබීම', 'ඵල තුළ පිහිටන බීජ, ප්‍රමුඛ බීජාණුශාකය, RNA පොලිමරේස් වර්ග කීපයක්, කඳේ සනාල කලාප විසිරී තිබීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2254fdff-62f4-4d17-95de-dd2504ab48c3', 'c30fd1ad-e26a-521b-8b60-a138aceabcf6', 'බීජපත්‍ර එකක් සහිත කලල, ප්‍රභාසංශ්ලේෂක ජන්මාණු ශාකය, කඳේ සනාල කලාප කැම්බියම රහිත වීම, සෛල පටලයේ ශාඛනය නොවූ ලිපිඩ', 'බීජපත්‍ර එකක් සහිත කලල, ප්‍රභාසංශ්ලේෂක ජන්මාණු ශාකය, කඳේ සනාල කලාප කැම්බියම රහිත වීම, සෛල පටලයේ ශාඛනය නොවූ ලිපිඩ', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('537a11cb-add7-4f9c-9cb4-eb3264373b82', 'c30fd1ad-e26a-521b-8b60-a138aceabcf6', 'පත්‍ර වල සමාන්තර නාරටි, විෂමබීජාණුකතාව, තන්තු මුල්, ෆෝමයිල් මෙතියොනින් වලින් ආරම්භ වන ප්‍රෝටීන සංශ්ලේෂණය', 'පත්‍ර වල සමාන්තර නාරටි, විෂමබීජාණුකතාව, තන්තු මුල්, ෆෝමයිල් මෙතියොනින් වලින් ආරම්භ වන ප්‍රෝටීන සංශ්ලේෂණය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b8235218-1a3e-4ac7-a613-dfddceadf703', 'c30fd1ad-e26a-521b-8b60-a138aceabcf6', 'කඳේ සනාල කලාප විසිරී තිබීම, පරිපුෂ්ප, නග්න බීජ, සෛල පටලයේ ශාඛනය නොවූ ලිපිඩ', 'කඳේ සනාල කලාප විසිරී තිබීම, පරිපුෂ්ප, නග්න බීජ, සෛල පටලයේ ශාඛනය නොවූ ලිපිඩ', NULL, 'sanitized', 'v1', 4, 0);
