INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('af33d861-0c23-50d1-8cb3-990421b1b253', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 8, '<p>ජීවීන්ගේ වර්ගීකරණය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>ජීවීන්ගේ වර්ගීකරණය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'ශාක රාජධානිය (Plantae) ප්‍රථමයෙන්ම විධිමත්ව වර්ගීකරණය කොට හඳුනාගනු ලැබුවේ කැරොලස් ලිනේයස් විසිනි. ලකුණු දීමේ පටිපාටියට අනුව නිවැරදි පිළිතුර මෙය වේ.', 'ශාක රාජධානිය (Plantae) ප්‍රථමයෙන්ම විධිමත්ව වර්ගීකරණය කොට හඳුනාගනු ලැබුවේ කැරොලස් ලිනේයස් විසිනි. ලකුණු දීමේ පටිපාටියට අනුව නිවැරදි පිළිතුර මෙය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f5867e23-346c-4b04-9059-05bf0fcdc329', 'af33d861-0c23-50d1-8cb3-990421b1b253', 'හොඳින් සංවිධානය වූ න්‍යෂ්ටියක් නොදරන බැවින් වයිරස කිසිම රාජධානියකට අයත් නොවේ.', 'හොඳින් සංවිධානය වූ න්‍යෂ්ටියක් නොදරන බැවින් වයිරස කිසිම රාජධානියකට අයත් නොවේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7d063ee4-e271-4aca-be2f-2a84b9ae512a', 'af33d861-0c23-50d1-8cb3-990421b1b253', 'ප්‍රොටිස්ටා යනු විවිධ පරිණාමික සම්භවයන් සහිත ජීවීන් අන්තර්ගත ස්වාභාවික රාජධානියකි.', 'ප්‍රොටිස්ටා යනු විවිධ පරිණාමික සම්භවයන් සහිත ජීවීන් අන්තර්ගත ස්වාභාවික රාජධානියකි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3ccbfa1c-7d55-4ff9-8106-a0405250cbcb', 'af33d861-0c23-50d1-8cb3-990421b1b253', 'ගණයක් තුළ දැකිය හැකි පොදු ලක්ෂණ සංඛ්‍යාව, විශේෂයක් තුළ දැකිය හැකි පොදු ලක්ෂණ සංඛ්‍යාවට වඩා වැඩිය.', 'ගණයක් තුළ දැකිය හැකි පොදු ලක්ෂණ සංඛ්‍යාව, විශේෂයක් තුළ දැකිය හැකි පොදු ලක්ෂණ සංඛ්‍යාවට වඩා වැඩිය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('adb77e35-cb26-4dde-9090-9a63dc42d50d', 'af33d861-0c23-50d1-8cb3-990421b1b253', 'ශාක රාජධානිය මුලින් ම හඳුනා ගත්තේ කැරොලස් ලිනේයස් ය.', 'ශාක රාජධානිය මුලින් ම හඳුනා ගත්තේ කැරොලස් ලිනේයස් ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('43c07f64-8b2d-4e5d-bce4-d73131831124', 'af33d861-0c23-50d1-8cb3-990421b1b253', 'අධිරාජධානි තුනේ වර්ගීකරණය හඳුන්වා දුන්නේ රොබට් විටේකර්ය.', 'අධිරාජධානි තුනේ වර්ගීකරණය හඳුන්වා දුන්නේ රොබට් විටේකර්ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('16dfd63f-e033-546d-8bcb-74125403d462', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 9, '<p>ග්‍රාහිකා දරන, උදරීය හෘදයක් නොදරන, ද්වීපාර්ශ්වික සම්මිතික සීලෝමික සතෙකුට තිබිය හැක්කේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', '<p>ග්‍රාහිකා දරන, උදරීය හෘදයක් නොදරන, ද්වීපාර්ශ්වික සම්මිතික සීලෝමික සතෙකුට තිබිය හැක්කේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', NULL, 'උදරීය හෘදයක් නොදරන, ද්විපාර්ශ්වික සම්මිතික සහ සීලෝමික සතුන් වන ආත්‍රොපෝඩාවන් හෝ මොලුස්කාවන් වැනි අපෘෂ්ඨවංශීන් සතුව ශ්වසනය සඳහා ජලක්ලෝම (Gills) පිහිටිය හැක.', 'උදරීය හෘදයක් නොදරන, ද්විපාර්ශ්වික සම්මිතික සහ සීලෝමික සතුන් වන ආත්‍රොපෝඩාවන් හෝ මොලුස්කාවන් වැනි අපෘෂ්ඨවංශීන් සතුව ශ්වසනය සඳහා ජලක්ලෝම (Gills) පිහිටිය හැක.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
