INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f0db042d-a398-470c-803f-f836c1723b31', 'ec8a8349-f71c-505b-9517-d97c3f7e6cca', 'සුෂුම්නා ශීර්ෂකයේ පිහිටි ආශ්වාස මධ්‍යස්ථානය උත්තේජනය වීම නිසා බාහිර අන්තර්පර්ශුක පේශි වලට ස්නායු ආවේග සැපයේ.', 'සුෂුම්නා ශීර්ෂකයේ පිහිටි ආශ්වාස මධ්‍යස්ථානය උත්තේජනය වීම නිසා බාහිර අන්තර්පර්ශුක පේශි වලට ස්නායු ආවේග සැපයේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8ccd6f74-644a-4a3c-b179-18354faad573', 'ec8a8349-f71c-505b-9517-d97c3f7e6cca', 'ධමනි රුධිරයේ pH අගය වැඩිවීම නිසා මහා ධමනියේ රසායන ප්‍රතිග්‍රාහක උත්තේජනය වේ.', 'ධමනි රුධිරයේ pH අගය වැඩිවීම නිසා මහා ධමනියේ රසායන ප්‍රතිග්‍රාහක උත්තේජනය වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('653b45a1-a4b1-4560-a885-d97e90c625f4', 'ec8a8349-f71c-505b-9517-d97c3f7e6cca', 'පෙනහැලි වල ප්‍රසාර ප්‍රතිග්‍රාහක උත්තේජනය වීම නිසා ප්‍රශ්වාස මධ්‍යස්ථානය නිෂේධනය වේ.', 'පෙනහැලි වල ප්‍රසාර ප්‍රතිග්‍රාහක උත්තේජනය වීම නිසා ප්‍රශ්වාස මධ්‍යස්ථානය නිෂේධනය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e0009de4-1408-491d-8792-b6531d25c296', 'ec8a8349-f71c-505b-9517-d97c3f7e6cca', 'ප්‍රශ්වාස මධ්‍යස්ථානය උත්තේජනය වීම නිසා මහා ප්‍රාචීරය සංකෝචනය වේ.', 'ප්‍රශ්වාස මධ්‍යස්ථානය උත්තේජනය වීම නිසා මහා ප්‍රාචීරය සංකෝචනය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('18ca1603-961b-5ade-883b-18e16a032939', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 12, '<p>ශාක තුළ ජලය සහ ඛණිජ පරිවහනය වීම</p>', '<p>ශාක තුළ ජලය සහ ඛණිජ පරිවහනය වීම</p>', NULL, 'ශාක තුළ ජලය සහ ඛනිජ පරිවහනය ප්‍රධාන වශයෙන් උත්ස්වේදන ආකර්ෂණය නිසා ඇතිවන සෘණ පීඩන අනුක්‍රමණයක් (ආතතියක්) ඔස්සේ ශෛලම වාහිනී තුළින් ඉහළට ගමන් කරයි.', 'ශාක තුළ ජලය සහ ඛනිජ පරිවහනය ප්‍රධාන වශයෙන් උත්ස්වේදන ආකර්ෂණය නිසා ඇතිවන සෘණ පීඩන අනුක්‍රමණයක් (ආතතියක්) ඔස්සේ ශෛලම වාහිනී තුළින් ඉහළට ගමන් කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
