INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4d521d5b-f6ca-551d-b247-1609bfd29937', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 16, '<p>මිනිස් කන පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මිනිස් කන පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'අභ්‍යන්තර කනේ කර්ණශංඛය තුළ ඇති කෝර්ටි අවයවය (Organ of Corti) ශ්‍රවණ ප්‍රතිග්‍රාහක සෛල දරන අතර එය ශ්‍රවණ කෘත්‍යයට ඍජුවම සම්බන්ධ වේ.', 'අභ්‍යන්තර කනේ කර්ණශංඛය තුළ ඇති කෝර්ටි අවයවය (Organ of Corti) ශ්‍රවණ ප්‍රතිග්‍රාහක සෛල දරන අතර එය ශ්‍රවණ කෘත්‍යයට ඍජුවම සම්බන්ධ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('90997b58-863d-4d7c-b387-63b05693cbe4', '4d521d5b-f6ca-551d-b247-1609bfd29937', 'එහි සාමාන්‍ය ශ්‍රවණ පරාසය $40$ - $20000 Hz$ වේ.', 'එහි සාමාන්‍ය ශ්‍රවණ පරාසය $40$ - $20000 Hz$ වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('14472027-61ee-4b7b-b221-36c7cfea2f00', '4d521d5b-f6ca-551d-b247-1609bfd29937', 'නිඝාතිය, අණ්ඩාකාර ගවාක්ෂයට සම්බන්ධ වේ.', 'නිඝාතිය, අණ්ඩාකාර ගවාක්ෂයට සම්බන්ධ වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('43551f8c-dc5f-4982-bf4f-f711c20afeb3', '4d521d5b-f6ca-551d-b247-1609bfd29937', 'කන් පෙත්ත පාරදෘශ්‍ය කාටිලේජ වලින් තැනී ඇත.', 'කන් පෙත්ත පාරදෘශ්‍ය කාටිලේජ වලින් තැනී ඇත.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b30e1098-24c4-42d2-aa34-302eb4a03de6', '4d521d5b-f6ca-551d-b247-1609bfd29937', 'පටලමය ගහණය පරිවසාවලින් පිරී ඇත.', 'පටලමය ගහණය පරිවසාවලින් පිරී ඇත.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('df8cf530-5472-4901-b3e5-434e16b50acb', '4d521d5b-f6ca-551d-b247-1609bfd29937', 'කෝර්ටි අවයවය ශ්‍රවණ කෘත්‍යය හා සම්බන්ධ ය.', 'කෝර්ටි අවයවය ශ්‍රවණ කෘත්‍යය හා සම්බන්ධ ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('782b7c16-7956-565b-904c-d7c584369097', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 17, '<p>මිනිසාගේ ප්‍රත්‍යානුවේගී උත්තේජන</p>', '<p>මිනිසාගේ ප්‍රත්‍යානුවේගී උත්තේජන</p>', NULL, 'ප්‍රත්‍යානුවේගී ස්නායු පද්ධතිය (Parasympathetic nervous system) සාමාන්‍ය විවේකී අවස්ථාවලදී ක්‍රියාත්මක වන අතර, එය හෘත් ස්පන්දන ශීඝ්‍රතාව අඩු කර දේහය සාමාන්‍ය තත්ත්වයට පත් කිරීමට ක්‍රියා කරයි.', 'ප්‍රත්‍යානුවේගී ස්නායු පද්ධතිය (Parasympathetic nervous system) සාමාන්‍ය විවේකී අවස්ථාවලදී ක්‍රියාත්මක වන අතර, එය හෘත් ස්පන්දන ශීඝ්‍රතාව අඩු කර දේහය සාමාන්‍ය තත්ත්වයට පත් කිරීමට ක්‍රියා කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e6ca262f-429d-41c4-8213-1c7a6297aee2', '782b7c16-7956-565b-904c-d7c584369097', 'ඇසේ කණිනිකාව විස්තාරණය කරයි.', 'ඇසේ කණිනිකාව විස්තාරණය කරයි.', NULL, 'sanitized', 'v1', 0, 1);
