INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e0a609a7-6908-4736-ae3e-f1b08e4560ac', '782b7c16-7956-565b-904c-d7c584369097', 'දහදිය ස්‍රාවය වීම වැඩි කරයි.', 'දහදිය ස්‍රාවය වීම වැඩි කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e067a526-08d7-4d21-b5b9-73814a4c9de1', '782b7c16-7956-565b-904c-d7c584369097', 'ශ්වාසනාලිකා විස්තාරණය කරයි.', 'ශ්වාසනාලිකා විස්තාරණය කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fc6e02d6-85ca-4596-ad09-6f8f0a90f758', '782b7c16-7956-565b-904c-d7c584369097', 'අක්මාවේදී ග්ලයිකොජන් ග්ලූකෝස් බවට පරිවර්තනය කිරීම වැඩි කරයි.', 'අක්මාවේදී ග්ලයිකොජන් ග්ලූකෝස් බවට පරිවර්තනය කිරීම වැඩි කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('45d3a338-1966-5e83-a1da-494f15c77525', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 18, '<p>මිනිස් නියුරෝනයක ක්‍රියා විභවය පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මිනිස් නියුරෝනයක ක්‍රියා විභවය පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'ක්‍රියා විභවයක් යනු උත්තේජයක් හේතුවෙන් ස්නායු සෛල පටලයේ විධ්‍රැවණය වීම නිසා ඇතිවන පටලයේ ධ්‍රැවීයතාවේ තාවකාලික (අනිත්‍ය) ප්‍රතිවර්තනයකි.', 'ක්‍රියා විභවයක් යනු උත්තේජයක් හේතුවෙන් ස්නායු සෛල පටලයේ විධ්‍රැවණය වීම නිසා ඇතිවන පටලයේ ධ්‍රැවීයතාවේ තාවකාලික (අනිත්‍ය) ප්‍රතිවර්තනයකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
