INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d6bd659b-d702-4645-9adc-e12e4286c663', '45d3a338-1966-5e83-a1da-494f15c77525', 'එය ස්නායු සෛල පටලයේ ධ්‍රැවීයතාවේ අනිත්‍ය ප්‍රතිවර්තනයකි.', 'එය ස්නායු සෛල පටලයේ ධ්‍රැවීයතාවේ අනිත්‍ය ප්‍රතිවර්තනයකි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b7dc280a-c717-45ec-915c-d3452ed63760', '45d3a338-1966-5e83-a1da-494f15c77525', 'එක් ක්‍රියා විභවයකට පසුව වහාම තවත් ක්‍රියා විභවයක් ඇති විය හැකි ය.', 'එක් ක්‍රියා විභවයකට පසුව වහාම තවත් ක්‍රියා විභවයක් ඇති විය හැකි ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b1e24c67-1870-57c7-a317-28aeb8d7f20b', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 19, '<p>මානව හෝර්මෝන පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මානව හෝර්මෝන පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'තයිරොක්සින් (Thyroxine) හෝර්මෝනය දේහයේ මූලික පරිවෘත්තීය ශීඝ්‍රතාව (BMR) ඉහළ නංවන අතර, එමගින් ශ්වසනය වේගවත් කර තාප නිෂ්පාදනය වැඩි කරයි.', 'තයිරොක්සින් (Thyroxine) හෝර්මෝනය දේහයේ මූලික පරිවෘත්තීය ශීඝ්‍රතාව (BMR) ඉහළ නංවන අතර, එමගින් ශ්වසනය වේගවත් කර තාප නිෂ්පාදනය වැඩි කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
