INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e5374675-464b-4b38-a154-d429c8e18ffc', 'b1e24c67-1870-57c7-a317-28aeb8d7f20b', 'අධිවෘක්ක බාහිකයෙන් ස්‍රාවය කරනු ලබන ප්‍රධාන ග්ලූකොකෝර්ටිකොයිඩය ඇල්ඩොස්ටෙරොන් ය.', 'අධිවෘක්ක බාහිකයෙන් ස්‍රාවය කරනු ලබන ප්‍රධාන ග්ලූකොකෝර්ටිකොයිඩය ඇල්ඩොස්ටෙරොන් ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2c122a8e-9d38-42ee-9543-e55f544453ed', 'b1e24c67-1870-57c7-a317-28aeb8d7f20b', 'පැරාතයිරොයිඩ හෝර්මෝනය රුධිර කැල්සියම් මට්ටම අඩු කරයි.', 'පැරාතයිරොයිඩ හෝර්මෝනය රුධිර කැල්සියම් මට්ටම අඩු කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('24f6c678-5752-4e4d-b882-e5e72feaba8d', 'b1e24c67-1870-57c7-a317-28aeb8d7f20b', 'තයිරොක්සින් දේහයේ තාප නිෂ්පාදනය වැඩි කරයි.', 'තයිරොක්සින් දේහයේ තාප නිෂ්පාදනය වැඩි කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a5716ee2-7dd0-463e-a299-fdac8ca3bf0b', 'b1e24c67-1870-57c7-a317-28aeb8d7f20b', 'ඉන්හිබින්, FSH ස්‍රාවය වීම උත්තේජනය කරයි.', 'ඉන්හිබින්, FSH ස්‍රාවය වීම උත්තේජනය කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('33a4d1a1-11d0-5ab8-9bfa-65bcb1207ef3', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 20, '<p>පර්ව දික්වීම උත්තේජනය කරන සහ බීජ ප්‍රරෝහණයේදී එන්සයිම සක්‍රිය කරන ශාක වර්ධක ද්‍රව්‍යය තෝරන්න.</p>', '<p>පර්ව දික්වීම උත්තේජනය කරන සහ බීජ ප්‍රරෝහණයේදී එන්සයිම සක්‍රිය කරන ශාක වර්ධක ද්‍රව්‍යය තෝරන්න.</p>', NULL, 'ගිබෙරලින් (Gibberellins) මගින් කඳේ පර්ව දික්වීම උත්තේජනය කරන අතර, බීජ ප්‍රරෝහණයේදී ඇಮයිලේස් වැනි එන්සයිම සක්‍රිය කර පෝෂක ද්‍රව්‍ය ජීරණයට උපකාරී වේ.', 'ගිබෙරලින් (Gibberellins) මගින් කඳේ පර්ව දික්වීම උත්තේජනය කරන අතර, බීජ ප්‍රරෝහණයේදී ඇಮයිලේස් වැනි එන්සයිම සක්‍රිය කර පෝෂක ද්‍රව්‍ය ජීරණයට උපකාරී වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
